function normalizeOpsPlanTypeName(planType) {
	const normalizedType = String(planType || "").trim();
	return OPS_PLAN_TYPE_NAME_ALIASES[normalizedType] || normalizedType;
}

function normalizeCompositeRepeatCycleUnit(value) {
	const normalized = String(value || "").trim().toLowerCase();
	if (["day", "week", "month"].includes(normalized)) return normalized;
	return "day";
}

function getCompositeRepeatCycleValue(item = {}) {
	const rawValue = Number(item?.repeatCycleValue ?? item?.repeatCycle ?? 1);
	return Number.isFinite(rawValue) && rawValue > 0 ? Math.floor(rawValue) : 1;
}

function getCompositeRepeatCycleDays(item = {}) {
	const value = getCompositeRepeatCycleValue(item);
	const unit = normalizeCompositeRepeatCycleUnit(item?.repeatCycleUnit);
	if (unit === "week") return value * 7;
	if (unit === "month") return value * 30;
	return value;
}

function formatCompositeRepeatCycleLabel(item = {}) {
	const value = getCompositeRepeatCycleValue(item);
	const unit = normalizeCompositeRepeatCycleUnit(item?.repeatCycleUnit);
	if (unit === "week") return `${value}周`;
	if (unit === "month") return `${value}月`;
	return `${value}日`;
}

function addCompositeRepeatOffset(dateValue, repeatIndex, repeatCycleValue, repeatCycleUnit) {
	const safeDate = dateValue instanceof Date ? new Date(dateValue.getTime()) : new Date(dateValue);
	if (Number.isNaN(safeDate.valueOf())) return null;
	const index = Math.max(0, Number(repeatIndex) || 0);
	const cycleValue = Number.isFinite(Number(repeatCycleValue)) && Number(repeatCycleValue) > 0 ? Math.floor(Number(repeatCycleValue)) : 1;
	const unit = normalizeCompositeRepeatCycleUnit(repeatCycleUnit);
	if (index === 0) return safeDate;
	if (unit === "month") {
		safeDate.setMonth(safeDate.getMonth() + cycleValue * index);
		return safeDate;
	}
	const dayOffset = unit === "week" ? cycleValue * 7 * index : cycleValue * index;
	return addDaysToDate(safeDate, dayOffset);
}

function normalizePrevRepairTriggerModes(value) {
	const source = Array.isArray(value) ? value : [value];
	const normalized = Array.from(
		new Set(
			source
				.map((item) => String(item || "").trim())
				.filter((item) => PREV_REPAIR_TRIGGER_MODE_OPTIONS.includes(item))
		)
	);
	return normalized;
}

function parsePreventiveMaintenanceHours(value) {
	const text = String(value || "").trim();
	if (!text) return 0;
	const match = text.match(/(\d+(?:\.\d+)?)\s*小时/);
	if (!match) return 0;
	const hourValue = Number(match[1]);
	return Number.isFinite(hourValue) && hourValue > 0 ? hourValue : 0;
}

function getOpsPlanTypePhaseLabel(planType) {
	const normalizedType = normalizeOpsPlanTypeName(planType);
	return OPS_PLAN_TYPE_PHASE_LABEL[normalizedType] || normalizedType || "直接准备";
}

function buildOpsPlanSchemeDisplayName(modelName, schemeNo) {
	const normalizedModelName = String(modelName || "").trim() || "机型";
	const normalizedSchemeNo = Number.isInteger(Number(schemeNo)) && Number(schemeNo) > 0 ? Number(schemeNo) : 1;
	const schemePrefix = OPS_PLAN_SCHEME_NAME_PREFIX[normalizedModelName] || `${normalizedModelName}保障方案`;
	return `${schemePrefix}${normalizedSchemeNo}`;
}

function resolveOpsPlanSchemeDisplayName(scheme, modelName, schemeNo, preferredPlanType = "") {
	return resolveOpsPlanSchemeActivityName(scheme, modelName, schemeNo);
}

function resolveOpsPlanSchemeActivityName(scheme, modelName, schemeNo) {
	const allPlans = Array.isArray(scheme?.allPlans) ? scheme.allPlans : [];
	const customName = allPlans
		.map((plan) => String(plan?.draft?.activityName || "").trim())
		.find(Boolean);
	return customName || buildOpsPlanActivityNameByScheme(modelName, schemeNo, OPS_PLAN_TYPE_OPTIONS[0]);
}

function buildOpsPlanActivityNameByScheme(modelName, schemeNo, planType) {
	return `${buildOpsPlanSchemeDisplayName(modelName, schemeNo)}`;
}

function buildOpsPlanPlanNameByScheme(modelName, schemeNo, planType) {
	return `${buildOpsPlanSchemeDisplayName(modelName, schemeNo)}-${getOpsPlanTypePhaseLabel(planType)}`;
}

