function renderMultiRowSubModal(group, dataStr) {
	let title = "";
	let rowsHtml = "";
	if (group === "personnel") {
		title = "编辑人员需求";
		const list = parsePersonnelString(dataStr);
		if (list.length === 0) list.push({ major: "", level: "L1", count: "" });
		const majorOptions = getPersonnelMajorOptions();
		const levelOptions = ["L1", "L2", "L3"];
		rowsHtml = list.map((row, i) => `
			<div class="multi-row-item" data-group="personnel" data-index="${i}">
				<select data-field="major" style="flex:1;">
					<option value="">请选择专业</option>
					${majorOptions.map((m) => `<option value="${htmlEscape(m)}" ${row.major === m ? "selected" : ""}>${htmlEscape(m)}</option>`).join("")}
				</select>
				<select data-field="level" style="width:90px;">
					<option value="">专业等级</option>
					${levelOptions.map((r) => `<option value="${htmlEscape(r)}" ${String(row.level || "L1") === r ? "selected" : ""}>${htmlEscape(r)}</option>`).join("")}
				</select>
				<input data-field="count" type="number" min="0" style="width:80px;" placeholder="数量" value="${htmlEscape(row.count)}" />
				<button type="button" class="inline-edit-btn btn-danger" data-action="remove-subrow" data-group="personnel" data-index="${i}">删除</button>
			</div>
		`).join("");
	} else if (group === "equipment") {
		title = "编辑设备需求";
		const list = parseEquipmentString(dataStr);
		if (list.length === 0) list.push({ name: "", model: "", count: "" });
		const nameOptions = getEquipmentNameOptions();
		rowsHtml = list.map((row, i) => `
			<div class="multi-row-item" data-group="equipment" data-index="${i}">
				<input data-field="model" style="width:100px;" placeholder="型号" value="${htmlEscape(row.model)}" />
				<select data-field="name" style="flex:1;">
					<option value="">请选择设备</option>
					${nameOptions.map((n) => `<option value="${htmlEscape(n)}" ${row.name === n ? "selected" : ""}>${htmlEscape(n)}</option>`).join("")}
				</select>
				<input data-field="count" type="number" min="0" style="width:70px;" placeholder="数量" value="${htmlEscape(row.count)}" />
				<button type="button" class="inline-edit-btn btn-danger" data-action="remove-subrow" data-group="equipment" data-index="${i}">删除</button>
			</div>
		`).join("");
	} else if (group === "facility") {
		title = "编辑设施功能要求";
		const list = parseFacilityString(dataStr);
		if (list.length === 0) list.push("");
		const fnOptions = getFacilityFnOptions();
		rowsHtml = list.map((val, i) => `
			<div class="multi-row-item" data-group="facility" data-index="${i}">
				<select data-field="fn" style="flex:1;">
					<option value="">请选择功能</option>
					${Array.from(new Set([...fnOptions, normalizeFacilityFunctionName(val)])).filter(Boolean).map((f) => `<option value="${htmlEscape(f)}" ${normalizeFacilityFunctionName(val) === f ? "selected" : ""}>${htmlEscape(f)}</option>`).join("")}
				</select>
				<button type="button" class="inline-edit-btn btn-danger" data-action="remove-subrow" data-group="facility" data-index="${i}">删除</button>
			</div>
		`).join("");
	} else if (group === "ammunition") {
		title = "编辑保障资源需求";
		const list = parseAmmunitionString(dataStr);
		if (list.length === 0) list.push({ name: "", model: "", count: "" });
		const ammunitionOptions = getAmmunitionNameOptions();
		rowsHtml = list.map((row, i) => `
			<div class="multi-row-item" data-group="ammunition" data-index="${i}">
				<input data-field="model" style="width:100px;" placeholder="型号" value="${htmlEscape(row.model)}" />
				<select data-field="name" style="flex:1;">
					<option value="">请选择弹药名称</option>
					${ammunitionOptions.map((n) => `<option value="${htmlEscape(n)}" ${row.name === n ? "selected" : ""}>${htmlEscape(n)}</option>`).join("")}
				</select>
				<input data-field="count" type="number" min="0" style="width:80px;" placeholder="数量" value="${htmlEscape(row.count)}" />
				<button type="button" class="inline-edit-btn btn-danger" data-action="remove-subrow" data-group="ammunition" data-index="${i}">删除</button>
			</div>
		`).join("");
	} else if (group === "spare") {
		title = "编辑保障资源需求";
		const list = parseSpareString(dataStr);
		if (list.length === 0) list.push({ name: "", model: "", count: "" });
		const spareNameOptions = getEquipmentConfigSpareNameOptions();
		const spareModelOptions = getEquipmentConfigSpareModelOptions();
		rowsHtml = list.map((row, i) => `
			<div class="multi-row-item" data-group="spare" data-index="${i}">
				<input data-field="model" list="basicActivitySubSpareModelOptions" style="width:120px;" placeholder="请输入或搜索型号" value="${htmlEscape(row.model)}" />
				<input data-field="name" list="basicActivitySubSpareNameOptions" style="flex:1;" placeholder="请输入或搜索名称" value="${htmlEscape(row.name)}" />
				<input data-field="count" type="number" min="0" style="width:80px;" placeholder="数量" value="${htmlEscape(row.count)}" />
				<button type="button" class="inline-edit-btn btn-danger" data-action="remove-subrow" data-group="spare" data-index="${i}">删除</button>
			</div>
		`).join("");
		rowsHtml = `<datalist id="basicActivitySubSpareModelOptions">${spareModelOptions.map((model) => `<option value="${htmlEscape(model)}"></option>`).join("")}</datalist><datalist id="basicActivitySubSpareNameOptions">${spareNameOptions.map((name) => `<option value="${htmlEscape(name)}"></option>`).join("")}</datalist>${rowsHtml}`;
	}

	return `
		<div class="modal-mask sub-modal" style="z-index: 2100;">
			<div class="modal" style="width:min(600px,94vw); max-height: 80vh; overflow-y: auto;">
				<h3>${title}</h3>
				<div class="submodal-content-areaWrapper" style="margin-bottom:16px;">
					<div id="subModalItemsContainer">${rowsHtml}</div>
					<button type="button" class="inline-edit-btn btn-primary" data-action="add-subrow" data-group="${group}" style="margin-top:8px;">+ 新增</button>
				</div>
				<div class="modal-foot" style="justify-content: center; gap: 12px;">
					<button class="btn-primary" data-action="confirm-submodal" data-group="${group}">保存并返回</button>
					<button data-action="cancel-submodal">取消</button>
				</div>
			</div>
		</div>
	`;
}

// --- END 结构化字段工具 ---

function bindBasicActivityMultiRowEvents() {
	bindBasicActivityStructuredFieldEvents();
}

function collectSubModalData(group) {
	const container = document.getElementById("subModalItemsContainer");
	if (!container) return "";
	if (group === "personnel") {
		const list = [];
		container.querySelectorAll("[data-group='personnel']").forEach((row) => {
			const major = row.querySelector("[data-field='major']")?.value || "";
			const level = row.querySelector("[data-field='level']")?.value || "L1";
			const count = row.querySelector("[data-field='count']")?.value || "";
			if (major) list.push({ major, level, count });
		});
		return serializePersonnelList(list);
	} else if (group === "equipment") {
		const list = [];
		container.querySelectorAll("[data-group='equipment']").forEach((row) => {
			const name = row.querySelector("[data-field='name']")?.value || "";
			const model = row.querySelector("[data-field='model']")?.value || "";
			const count = row.querySelector("[data-field='count']")?.value || "";
			if (name) list.push({ name, model, count });
		});
		return serializeEquipmentList(list);
	} else if (group === "facility") {
		const list = [];
		container.querySelectorAll("[data-group='facility']").forEach((row) => {
			const fn = row.querySelector("[data-field='fn']")?.value || "";
			if (fn) list.push(fn);
		});
		return serializeFacilityList(list);
	} else if (group === "ammunition") {
		const list = [];
		container.querySelectorAll("[data-group='ammunition']").forEach((row) => {
			const name = row.querySelector("[data-field='name']")?.value || "";
			const model = row.querySelector("[data-field='model']")?.value || "";
			const count = row.querySelector("[data-field='count']")?.value || "";
			if (name) list.push({ name, model, count });
		});
		return serializeAmmunitionList(list);
	} else if (group === "spare") {
		const list = [];
		container.querySelectorAll("[data-group='spare']").forEach((row) => {
			const name = row.querySelector("[data-field='name']")?.value || "";
			const model = row.querySelector("[data-field='model']")?.value || "";
			const count = row.querySelector("[data-field='count']")?.value || "";
			if (name) list.push({ name, model, count });
		});
		return serializeSpareList(list);
	}
	return "";
}

function bindSubModalEvents(group) {
	const wrapper = document.getElementById("basicActivitySubModalWrapper");
	if (!wrapper) return;

	// Add row
	wrapper.querySelector("[data-action='add-subrow']").addEventListener("click", () => {
		const currentData = collectSubModalData(group);
		let nextData = "";
		if (group === "personnel") {
			const list = parsePersonnelString(currentData);
			list.push({ major: "", level: "L1", count: "" });
			nextData = serializePersonnelList(list);
		} else if (group === "equipment") {
			const list = parseEquipmentString(currentData);
			list.push({ name: "", model: "", count: "" });
			nextData = serializeEquipmentList(list);
		} else if (group === "facility") {
			const list = parseFacilityString(currentData);
			list.push("");
			nextData = serializeFacilityList(list);
		} else if (group === "ammunition") {
			const list = parseAmmunitionString(currentData);
			list.push({ name: "", model: "", count: "" });
			nextData = serializeAmmunitionList(list);
		} else if (group === "spare") {
			const list = parseSpareString(currentData);
			list.push({ name: "", model: "", count: "" });
			nextData = serializeSpareList(list);
		}
		wrapper.innerHTML = renderMultiRowSubModal(group, nextData);
		bindSubModalEvents(group);
	});

	// Remove row
	wrapper.querySelectorAll("[data-action='remove-subrow']").forEach((btn) => {
		btn.addEventListener("click", () => {
			const idx = Number(btn.dataset.index);
			const currentData = collectSubModalData(group);
			let nextData = "";
			if (group === "personnel") {
				const list = parsePersonnelString(currentData);
				list.splice(idx, 1);
				nextData = serializePersonnelList(list);
			} else if (group === "equipment") {
				const list = parseEquipmentString(currentData);
				list.splice(idx, 1);
				nextData = serializeEquipmentList(list);
			} else if (group === "facility") {
				const list = parseFacilityString(currentData);
				list.splice(idx, 1);
				nextData = serializeFacilityList(list);
			} else if (group === "ammunition") {
				const list = parseAmmunitionString(currentData);
				list.splice(idx, 1);
				nextData = serializeAmmunitionList(list);
			} else if (group === "spare") {
				const list = parseSpareString(currentData);
				list.splice(idx, 1);
				nextData = serializeSpareList(list);
			}
			wrapper.innerHTML = renderMultiRowSubModal(group, nextData);
			bindSubModalEvents(group);
		});
	});

	// Cancel
	wrapper.querySelector("[data-action='cancel-submodal']").addEventListener("click", () => {
		wrapper.remove();
	});

	// Confirm (Save and Close)
	wrapper.querySelector("[data-action='confirm-submodal']").addEventListener("click", () => {
		const finalData = collectSubModalData(group);
		// Update the display and hidden value in the main modal
		let displayContainer = null;
		if (group === "personnel") {
			displayContainer = document.getElementById("basicActivityPersonnelContainer");
			displayContainer.innerHTML = renderBasicActivityPersonnelEditor(finalData);
		} else if (group === "equipment") {
			displayContainer = document.getElementById("basicActivityEquipmentContainer");
			displayContainer.innerHTML = renderBasicActivityEquipmentEditor(finalData);
		} else if (group === "facility") {
			displayContainer = document.getElementById("basicActivityFacilityContainer");
			displayContainer.innerHTML = renderBasicActivityFacilityEditor(finalData);
		} else if (group === "ammunition") {
			displayContainer = document.getElementById("basicActivityAmmunitionContainer");
			displayContainer.innerHTML = renderBasicActivityAmmunitionEditor(finalData);
		} else if (group === "spare") {
			displayContainer = document.getElementById("basicActivitySpareContainer");
			displayContainer.innerHTML = renderBasicActivitySpareEditor(finalData);
		}
		wrapper.remove();
		bindBasicActivityMultiRowEvents(); // Re-bind main modal events
	});
}

function ensureBasicActivityCollectionsState() {
	for (let index = 0; index < BASIC_OPS_ACTIVITIES.length; index += 1) {
		BASIC_OPS_ACTIVITIES[index] = cloneBasicActivityItem("basic_ops", BASIC_OPS_ACTIVITIES[index]);
	}
	ensureBasicActivityCodes("basic_ops", BASIC_OPS_ACTIVITIES);
	for (let index = 0; index < BASIC_REPAIR_ACTIVITIES.length; index += 1) {
		BASIC_REPAIR_ACTIVITIES[index] = cloneBasicActivityItem("basic_repair", BASIC_REPAIR_ACTIVITIES[index]);
	}
	ensureBasicActivityCodes("basic_repair", BASIC_REPAIR_ACTIVITIES);
	for (let index = 0; index < BASIC_OPS_BASELINE_ACTIVITIES.length; index += 1) {
		BASIC_OPS_BASELINE_ACTIVITIES[index] = cloneBasicActivityItem("basic_ops", BASIC_OPS_BASELINE_ACTIVITIES[index]);
	}
	ensureBasicActivityCodes("basic_ops", BASIC_OPS_BASELINE_ACTIVITIES);
}

ensureBasicActivityCollectionsState();

function getBasicActivityCollection(activityType) {
	ensureBasicActivityCollectionsState();
	return activityType === "basic_repair" ? BASIC_REPAIR_ACTIVITIES : BASIC_OPS_ACTIVITIES;
}

function ensureBasicActivitySelectedState() {
	if (!state.ui.selectedBasicActivityIds || typeof state.ui.selectedBasicActivityIds !== "object") {
		state.ui.selectedBasicActivityIds = {
			basic_ops: [],
			basic_repair: []
		};
	}
	["basic_ops", "basic_repair"].forEach((activityType) => {
		if (!Array.isArray(state.ui.selectedBasicActivityIds[activityType])) {
			state.ui.selectedBasicActivityIds[activityType] = [];
		}
		const validIds = new Set(getBasicActivityCollection(activityType).map((item) => item.id));
		state.ui.selectedBasicActivityIds[activityType] = state.ui.selectedBasicActivityIds[activityType].filter((id) => validIds.has(id));
	});
	return state.ui.selectedBasicActivityIds;
}

function buildBasicActivityTreeNodes(activityType, items) {
	const groups = new Map();
	(items || []).forEach((item) => {
		const aircraftName = String(activityType === "basic_repair" ? item.target : item.aircraftType || "").trim() || "未分类飞机";
		if (!groups.has(aircraftName)) {
			groups.set(aircraftName, []);
		}
		groups.get(aircraftName).push(item);
	});
	return Array.from(groups.entries()).map(([aircraftName, rows]) => ({
		id: `aircraft:${aircraftName}`,
		label: aircraftName,
		rows,
		children: rows.map((row) => ({
			id: `work:${row.id}`,
			label: String(row.workName || "未命名作业").trim(),
			rowId: row.id
		}))
	}));
}

function ensureBasicActivityTreeUiState(activityType, treeNodes) {
	if (!state.ui || typeof state.ui !== "object") {
		state.ui = {};
	}
	if (!state.ui.basicActivityTree || typeof state.ui.basicActivityTree !== "object") {
		state.ui.basicActivityTree = {};
	}
	if (!state.ui.basicActivityTree[activityType] || typeof state.ui.basicActivityTree[activityType] !== "object") {
		state.ui.basicActivityTree[activityType] = { selectedId: "", collapsedAircraftIds: [] };
	}
	const treeState = state.ui.basicActivityTree[activityType];
	if (!Array.isArray(treeState.collapsedAircraftIds)) {
		treeState.collapsedAircraftIds = [];
	}
	const validIds = new Set();
	treeNodes.forEach((node) => {
		validIds.add(node.id);
		node.children.forEach((child) => validIds.add(child.id));
	});
	if (!validIds.has(String(treeState.selectedId || "").trim())) {
		treeState.selectedId = treeNodes[0]?.id || "";
	}
	treeState.collapsedAircraftIds = treeState.collapsedAircraftIds.filter((id) => validIds.has(String(id || "").trim()));
	return treeState;
}

function filterBasicActivityRowsByTreeSelection(rows, selectedTreeId) {
	const selectedId = String(selectedTreeId || "").trim();
	if (!selectedId) return rows;
	if (selectedId.startsWith("work:")) {
		const rowId = selectedId.slice(5);
		return rows.filter((item) => String(item.id || "").trim() === rowId);
	}
	if (selectedId.startsWith("aircraft:")) {
		const aircraftName = selectedId.slice(9);
		return rows.filter((item) => String(item.aircraftType || item.target || "").trim() === aircraftName);
	}
	return rows;
}

function ensureBasicActivityTableFieldExpandedState() {
	if (!state.ui.basicActivityTableFieldExpanded || typeof state.ui.basicActivityTableFieldExpanded !== "object") {
		state.ui.basicActivityTableFieldExpanded = {
			basic_ops: {},
			basic_repair: {}
		};
	}
	["basic_ops", "basic_repair"].forEach((activityType) => {
		if (!state.ui.basicActivityTableFieldExpanded[activityType] || typeof state.ui.basicActivityTableFieldExpanded[activityType] !== "object") {
			state.ui.basicActivityTableFieldExpanded[activityType] = {};
		}
		const validIds = new Set(getBasicActivityCollection(activityType).map((item) => item.id));
		Object.keys(state.ui.basicActivityTableFieldExpanded[activityType]).forEach((rowId) => {
			if (!validIds.has(rowId)) {
				delete state.ui.basicActivityTableFieldExpanded[activityType][rowId];
			}
		});
	});
	return state.ui.basicActivityTableFieldExpanded;
}

function isBasicActivityTableFieldExpanded(activityType, rowId, group) {
	const expandedState = ensureBasicActivityTableFieldExpandedState();
	return Boolean(expandedState[activityType]?.[rowId]?.[group]);
}

function setBasicActivityTableFieldExpanded(activityType, rowId, group, expanded) {
	if (!rowId) return;
	const expandedState = ensureBasicActivityTableFieldExpandedState();
	if (!expandedState[activityType][rowId] || typeof expandedState[activityType][rowId] !== "object") {
		expandedState[activityType][rowId] = {};
	}
	expandedState[activityType][rowId][group] = Boolean(expanded);
}

function renderBasicActivityMiniTable(headers, rows, emptyText = "-", showHeader = true) {
	const safeHeaders = Array.isArray(headers) && headers.length > 0 ? headers : ["内容"];
	const normalizedRows = Array.isArray(rows) ? rows : [];
	const headerHtml = safeHeaders.map((title) => `<th>${htmlEscape(title)}</th>`).join("");
	const rowHtml =
		normalizedRows.length > 0
			? normalizedRows.map((row) => `<tr>${row.map((cell) => `<td>${htmlEscape(cell)}</td>`).join("")}</tr>`).join("")
			: `<tr><td colspan="${safeHeaders.length}" class="muted">${htmlEscape(emptyText)}</td></tr>`;
	return `
		<div class="basic-activity-mini-table-wrap">
			<table class="basic-activity-mini-table">
				${showHeader ? `<thead><tr>${headerHtml}</tr></thead>` : ""}
				<tbody>${rowHtml}</tbody>
			</table>
		</div>
	`;
}

function renderBasicOpsLineListCell(lines, emptyText = "-") {
	const normalizedLines = (Array.isArray(lines) ? lines : []).map((line) => String(line || "").trim()).filter(Boolean);
	if (normalizedLines.length === 0) {
		return `<span class="muted">${htmlEscape(emptyText)}</span>`;
	}
	return `<div class="basic-ops-line-list">${normalizedLines.map((line) => `<div class="basic-ops-line-item">${htmlEscape(line)}</div>`).join("")}</div>`;
}

function renderBasicOpsPlainLineList(lines, emptyText = "-") {
	const normalizedLines = (Array.isArray(lines) ? lines : []).map((line) => String(line || "").trim()).filter(Boolean);
	if (normalizedLines.length === 0) {
		return `<span class="muted">${htmlEscape(emptyText)}</span>`;
	}
	return `<div class="basic-ops-plain-line-list">${normalizedLines.map((line) => `<div class="basic-ops-plain-line-item">${htmlEscape(line)}</div>`).join("")}</div>`;
}

function renderBasicOpsMatrixLikeColumn(lines, emptyText = "-") {
	const normalizedLines = (Array.isArray(lines) ? lines : []).map((line) => String(line || "").trim()).filter(Boolean);
	if (normalizedLines.length === 0) {
		return `<span class="muted">${htmlEscape(emptyText)}</span>`;
	}
	return `<div class="basic-ops-matrix-lines">${normalizedLines.map((line) => `<div class="basic-ops-matrix-line">${htmlEscape(line)}</div>`).join("")}</div>`;
}

function getBasicOpsResourceRows(item = {}, activityType = "basic_ops") {
	if (activityType === "basic_repair") {
		return parseSpareString(item.spare || "");
	}
	return [...parseAmmunitionString(item.ammunition || ""), ...parseSpareString(item.spare || "")];
}

function renderBasicOpsResourceCell(item = {}) {
	const rows = [
		...parseAmmunitionString(item.ammunition || "").map((row) => [row.model || "-", row.name || "-", row.count || "-"]),
		...parseSpareString(item.spare || "").map((row) => [row.model || "-", row.name || "-", row.count || "-"])
	];
	return renderBasicActivityMiniTable(["型号", "资源名称", "资源数量"], rows, "-", false);
}

function renderBasicOpsStructuredCell(group, dataStr, activityType, rowId) {
	if (group === "personnel") {
		const parsedRows = parsePersonnelString(dataStr || "");
		const headers = ["机务组织", "专业", "专业等级", "数量"];
		const rows = parsedRows.map((row) => [row.department || "-", row.major || "-", row.level || "L1", row.count || "-"]);
		return renderBasicActivityMiniTable(headers, rows, "-", false);
	}
	if (group === "servicePersonnel") {
		const parsedRows = parsePersonnelString(dataStr || "");
		const lines =
			parsedRows.length > 0
				? parsedRows.map((row) => `${row.major || "-"}${row.level ? `（${row.level}）` : ""}${row.count ? `，${row.count}` : ""}`)
				: [String(dataStr || "").trim()].filter(Boolean);
		return renderBasicOpsPlainLineList(lines, "-");
	}
	if (group === "facility") {
		const rows = parseFacilityString(dataStr || "").map((name) => [name || "-"]);
		return renderBasicActivityMiniTable(["设施名称"], rows, "-", false);
	}
	if (group === "equipment") {
		const rows = parseEquipmentString(dataStr || "").map((row) => [row.model || "-", row.name || "-", row.count || "-"]);
		return renderBasicActivityMiniTable(["设备型号", "设备名称", "数量"], rows, "-", false);
	}
	if (group === "ammunition") {
		const rows = parseAmmunitionString(dataStr || "").map((row) => [row.model || "-", row.name || "-", row.count || "-"]);
		return renderBasicActivityMiniTable(["型号", "资源名称", "资源数量"], rows, "-", false);
	}
	if (group === "spare") {
		const rows = parseSpareString(dataStr || "").map((row) => [row.model || "-", row.name || "-", row.count || "-"]);
		return renderBasicActivityMiniTable(["型号", "资源名称", "资源数量"], rows, "-", false);
	}
	return renderBasicActivityTableFieldCell(group, dataStr, activityType, rowId);
}

function renderBasicActivityTableFieldCell(group, dataStr, activityType, rowId) {
	const meta = getBasicActivityFieldMeta(group);
	const list = meta.parse(dataStr || "");
	if (!list.length) {
		return `<span class="muted">-</span>`;
	}
	const expanded = isBasicActivityTableFieldExpanded(activityType, rowId, group);
	const visibleItems = expanded ? list : list.slice(0, 2);
	const rowsHtml = visibleItems
		.map((row, index) => `<div style="font-size:12px;line-height:1.5;color:#334155;margin-bottom:4px;">${index + 1}. ${meta.summary(row)}</div>`)
		.join("");
	const toggleHtml = list.length > 2
		? `<div style="display:flex;justify-content:flex-end;margin-top:4px;"><button type="button" class="btn-link" data-action="toggle-basic-activity-table-field-expand" data-type="${activityType}" data-id="${rowId}" data-group="${group}">${expanded ? "收起" : "展开全部"}</button></div>`
		: "";
	return `<div style="min-width:220px;max-width:260px;white-space:normal;">${rowsHtml}${toggleHtml}</div>`;
}

function createBasicActivityDraft(activityType, item = null) {
	const baseItem =
		activityType === "basic_repair"
			? {
				target: APP_CONFIG.modelTypes[0] || "",
				supportActivity: "维修保障",
				workName: "",
				duration: 10,
				personnel: "",
				team: "",
				servicePersonnel: "",
				equipment: "",
				facility: "",
				spare: ""
			}
			: {
				aircraftType: getAircraftTypeOptions()[0] || APP_CONFIG.modelTypes[0] || "",
				supportActivity: "使用保障",
				workName: "",
				duration: 10,
				personnel: "",
				servicePersonnel: "",
				equipment: "",
				facility: "",
				ammunition: "",
				spare: ""
			};
	return cloneBasicActivityItem(activityType, {
		...baseItem,
		...(item || {})
	});
}

function convertBasicActivityDraftType(nextActivityType, item = null) {
	const targetActivityType = nextActivityType === "basic_repair" ? "basic_repair" : "basic_ops";
	const sourceItem = item && typeof item === "object" ? item : {};
	const currentType = sourceItem.activityType === "basic_repair" ? "basic_repair" : "basic_ops";
	if (currentType === targetActivityType) {
		return createBasicActivityDraft(targetActivityType, sourceItem);
	}
	const sharedFields = {
		id: String(sourceItem.id || "").trim(),
		activityCode: String(sourceItem.activityCode || "").trim(),
		supportActivity: String(sourceItem.supportActivity || "").trim(),
		workName: String(sourceItem.workName || "").trim(),
		duration: Number(sourceItem.duration || 10),
		personnel: String(sourceItem.personnel || "").trim(),
		servicePersonnel: String(sourceItem.servicePersonnel || sourceItem.team || "").trim(),
		team: String(sourceItem.team || sourceItem.servicePersonnel || "").trim(),
		equipment: String(sourceItem.equipment || "").trim(),
		facility: String(sourceItem.facility || "").trim(),
		spare: String(sourceItem.spare || "").trim(),
		durationProfile: cloneActivityDurationProfile(sourceItem.durationProfile, Number(sourceItem.duration || 10))
	};
	if (targetActivityType === "basic_repair") {
		return createBasicActivityDraft("basic_repair", {
			...sharedFields,
			target: String(sourceItem.target || sourceItem.aircraftType || APP_CONFIG.modelTypes[0] || "").trim()
		});
	}
	return createBasicActivityDraft("basic_ops", {
		...sharedFields,
		aircraftType: String(sourceItem.aircraftType || sourceItem.target || getAircraftTypeOptions()[0] || APP_CONFIG.modelTypes[0] || "").trim(),
		ammunition: String(sourceItem.ammunition || "").trim()
	});
}

function getBasicActivityItemById(activityType, id) {
	if (!id) return null;
	return getBasicActivityCollection(activityType).find((item) => item.id === id) || null;
}

function getBasicActivityNameSuggestionRows(activityType, keyword, currentId = "") {
	const safeKeyword = String(keyword || "").trim();
	if (!safeKeyword) return [];
	const rows = getRowsByKeywordPriority(
		getBasicActivityCollection(activityType).filter((item) => String(item?.id || "").trim() !== String(currentId || "").trim()),
		(row) => [row.workName],
		safeKeyword
	);
	return rows.slice(0, 8).map((item) => createBasicActivityDraft(activityType, item));
}

function findBasicActivityCodeConflict(item) {
	const activityCode = normalizeSearchText(item?.activityCode || "");
	if (!activityCode) return null;
	const currentId = String(item?.id || "").trim();
	for (const activityType of ["basic_ops", "basic_repair"]) {
		const matched = getBasicActivityCollection(activityType).find((row) => {
			if (!row || typeof row !== "object") return false;
			if (String(row.id || "").trim() === currentId) return false;
			return normalizeSearchText(row.activityCode || "") === activityCode;
		});
		if (matched) {
			return createBasicActivityDraft(activityType, matched);
		}
	}
	return null;
}

function readBasicActivityDurationProfileFromEditor(fallbackProfile, durationValue) {
	const rawValue = String(document.getElementById("basicActivityDurationProfile")?.value || "").trim();
	if (!rawValue) {
		return cloneActivityDurationProfile(fallbackProfile, durationValue);
	}
	try {
		return cloneActivityDurationProfile(JSON.parse(rawValue), durationValue);
	} catch (error) {
		return cloneActivityDurationProfile(fallbackProfile, durationValue);
	}
}

function syncBasicActivityDurationEditor(item) {
	const nextItem = item && typeof item === "object" ? item : {};
	const durationInput = document.getElementById("basicActivityDuration");
	const durationProfileInput = document.getElementById("basicActivityDurationProfile");
	const durationSummary = document.getElementById("basicActivityDurationSummary");
	if (durationInput) {
		durationInput.value = String(Number(nextItem.duration || 10));
	}
	if (durationProfileInput) {
		durationProfileInput.value = JSON.stringify(cloneActivityDurationProfile(nextItem.durationProfile, nextItem.duration || 10));
	}
	if (durationSummary) {
		durationSummary.textContent = describeBasicActivityDurationProfile(nextItem.durationProfile, nextItem.duration);
	}
}

function renderBasicActivityNameSuggestionPanel(activityType, keyword, currentId = "") {
	const rows = getBasicActivityNameSuggestionRows(activityType, keyword, currentId);
	if (!String(keyword || "").trim()) {
		return "";
	}
	if (rows.length === 0) {
		return '<div class="basic-activity-suggestion-empty">未找到匹配项，可继续录入新名称。</div>';
	}
	return rows
		.map(
			(item) => `
				<button type="button" class="basic-activity-suggestion-item" data-action="apply-basic-activity-suggestion" data-type="${activityType}" data-id="${htmlEscape(String(item.id || ""))}">
					<span class="basic-activity-suggestion-name">${htmlEscape(item.workName || "未命名活动")}</span>
					<span class="basic-activity-suggestion-meta">${htmlEscape(item.activityCode || "-")} | ${htmlEscape(activityType === "basic_repair" ? item.target || "-" : item.aircraftType || "-")}</span>
				</button>
			`
		)
		.join("");
}

function applyBasicActivitySuggestionToEditor(activityType, sourceItem) {
	if (!sourceItem) return;
	const modalItem = createBasicActivityDraft(activityType, state.ui.modal?.payload?.item || null);
	const nextItem = createBasicActivityDraft(activityType, {
		...modalItem,
		...sourceItem,
		id: modalItem.id
	});
	const workNameInput = document.getElementById("basicActivityWorkName");
	const codeInput = document.getElementById("basicActivityCode");
	const aircraftTypeSelect = document.getElementById("basicActivityAircraftType");
	const targetSelect = document.getElementById("basicActivityTarget");
	if (workNameInput) workNameInput.value = String(nextItem.workName || "");
	if (codeInput) codeInput.value = String(nextItem.activityCode || "");
	if (aircraftTypeSelect && activityType === "basic_ops") {
		aircraftTypeSelect.value = String(nextItem.aircraftType || "");
	}
	if (targetSelect && activityType === "basic_repair") {
		targetSelect.value = String(nextItem.target || "");
	}
	syncBasicActivityDurationEditor(nextItem);
	updateBasicActivityStructuredField("personnel", nextItem.personnel || "");
	updateBasicActivityStructuredField("servicePersonnel", nextItem.servicePersonnel || nextItem.team || "");
	updateBasicActivityStructuredField("facility", nextItem.facility || "");
	updateBasicActivityStructuredField("equipment", nextItem.equipment || "");
	updateBasicActivityStructuredField("spare", nextItem.spare || "");
	if (activityType === "basic_ops") {
		updateBasicActivityStructuredField("ammunition", nextItem.ammunition || "");
	}
	if (state.ui?.modal?.payload) {
		state.ui.modal.payload.item = nextItem;
	}
	const suggestionPanel = document.getElementById("basicActivityNameSuggestions");
	if (suggestionPanel) {
		suggestionPanel.innerHTML = renderBasicActivityNameSuggestionPanel(activityType, nextItem.workName, modalItem.id);
		suggestionPanel.style.display = String(nextItem.workName || "").trim() ? "block" : "none";
	}
}

function bindBasicActivityNameAutocomplete(activityType) {
	const workNameInput = document.getElementById("basicActivityWorkName");
	const suggestionPanel = document.getElementById("basicActivityNameSuggestions");
	if (!workNameInput || !suggestionPanel || workNameInput.dataset.autocompleteBound === "true" || workNameInput.readOnly) return;
	workNameInput.dataset.autocompleteBound = "true";
	const renderSuggestions = () => {
		const currentItem = createBasicActivityDraft(activityType, state.ui.modal?.payload?.item || null);
		const keyword = String(workNameInput.value || "").trim();
		suggestionPanel.innerHTML = renderBasicActivityNameSuggestionPanel(activityType, keyword, currentItem.id);
		suggestionPanel.style.display = keyword ? "block" : "none";
	};
	workNameInput.addEventListener("input", renderSuggestions);
	suggestionPanel.addEventListener("click", (event) => {
		const trigger = event.target.closest("[data-action='apply-basic-activity-suggestion']");
		if (!trigger) return;
		const rowId = String(trigger.dataset.id || "").trim();
		const sourceItem = getBasicActivityItemById(activityType, rowId);
		if (!sourceItem) return;
		applyBasicActivitySuggestionToEditor(activityType, sourceItem);
	});
	renderSuggestions();
}

function syncBasicActivityState(activityType) {
	ensureBasicActivityCodes(activityType, getBasicActivityCollection(activityType));
	if (activityType === "basic_repair") {
		syncBasicRepairDerivedCache();
		return;
	}
	syncBasicOpsDerivedCache();
	syncBasicOpsBaselineFromCurrent();
	syncSingleMissionSchemeOverrides();
}

function upsertBasicActivityItem(activityType, item) {
	const collection = getBasicActivityCollection(activityType);
	const nextItem = createBasicActivityDraft(activityType, item);
	const targetIndex = collection.findIndex((row) => row.id === nextItem.id);
	if (targetIndex >= 0) {
		collection[targetIndex] = nextItem;
	} else {
		collection.push(nextItem);
	}
	syncBasicActivityState(activityType);
	return nextItem;
}

function removeBasicActivityItem(activityType, id) {
	removeBasicActivityItems(activityType, new Set(id ? [id] : []));
}

function removeBasicActivityItems(activityType, idsSet) {
	if (!idsSet || idsSet.size === 0) return;
	const collection = getBasicActivityCollection(activityType);
	const hasMatchedRow = collection.some((item) => idsSet.has(item.id));
	if (!hasMatchedRow) return;
	const nextRows = collection.filter((item) => !idsSet.has(item.id));
	collection.length = 0;
	collection.push(...nextRows);
	syncBasicActivityState(activityType);
	ensureBasicActivitySelectedState();
	ensureBasicActivityTableFieldExpandedState();
	state.ui.selectedBasicActivityIds[activityType] = (state.ui.selectedBasicActivityIds[activityType] || []).filter((selectedId) => !idsSet.has(selectedId));
	idsSet.forEach((rowId) => {
		if (state.ui.basicActivityTableFieldExpanded?.[activityType]) {
			delete state.ui.basicActivityTableFieldExpanded[activityType][rowId];
		}
	});
}

function describeBasicActivityDurationProfile(profile, duration) {
	const normalizedProfile = cloneActivityDurationProfile(profile, duration);
	switch (normalizedProfile.distributionType) {
		case "正态分布":
			return `正态分布（均值 ${normalizedProfile.normalMean}，标准差 ${normalizedProfile.normalStdDev}）`;
		case "均匀分布":
			return `均匀分布（最小值 ${normalizedProfile.uniformMin}，最大值 ${normalizedProfile.uniformMax}）`;
		case "三角分布":
			return `三角分布（最小值 ${normalizedProfile.triangularMin}，最大值 ${normalizedProfile.triangularMax}，众数 ${normalizedProfile.triangularMode}）`;
		default:
			return `固定值（${Number(duration || 0)}）`;
	}
}

function validateBasicActivityDurationProfile(duration, profile) {
	if (!(Number(duration) > 0)) {
		return "工作时长（min）必须大于 0。";
	}
	const normalizedProfile = cloneActivityDurationProfile(profile, duration);
	if (normalizedProfile.distributionType === "正态分布") {
		if (!(normalizedProfile.normalMean > 0)) {
			return "正态分布均值必须大于 0。";
		}
		if (!(normalizedProfile.normalStdDev > 0)) {
			return "正态分布标准差必须大于 0。";
		}
	}
	if (normalizedProfile.distributionType === "均匀分布") {
		if (!(normalizedProfile.uniformMin >= 0)) {
			return "均匀分布最小值必须大于等于 0。";
		}
		if (!(normalizedProfile.uniformMax >= normalizedProfile.uniformMin)) {
			return "均匀分布最大值必须大于等于最小值。";
		}
	}
	if (normalizedProfile.distributionType === "三角分布") {
		if (!(normalizedProfile.triangularMin >= 0)) {
			return "三角分布最小值必须大于等于 0。";
		}
		if (!(normalizedProfile.triangularMax >= normalizedProfile.triangularMin)) {
			return "三角分布最大值必须大于等于最小值。";
		}
		if (!(normalizedProfile.triangularMode >= normalizedProfile.triangularMin && normalizedProfile.triangularMode <= normalizedProfile.triangularMax)) {
			return "三角分布众数必须位于最小值和最大值之间。";
		}
	}
	return "";
}

function validateBasicActivityItem(activityType, item) {
	const isValidCountText = (value) => {
		const text = String(value ?? "").trim();
		if (!text) return false;
		const numberValue = Number(text);
		return Number.isFinite(numberValue) && numberValue >= 0;
	};
	const isValidLevel = (departmentName, value) => {
		const options = getPersonnelLevelDictionaryOptions(departmentName);
		return options.includes(String(value || "").trim());
	};
	const personnelList = parsePersonnelString(item?.personnel || "");
	const invalidPersonnelLevelIndex = personnelList.findIndex(
		(row) => String(row?.major || "").trim() && !isValidLevel(String(row?.department || "").trim(), row?.level)
	);
	if (invalidPersonnelLevelIndex >= 0) {
		const row = personnelList[invalidPersonnelLevelIndex] || {};
		const allowedLevels = getPersonnelLevelDictionaryOptions(String(row?.department || "").trim()).join("/") || "L1/L2/L3";
		return `机务人员第${invalidPersonnelLevelIndex + 1}行专业等级必须为 ${allowedLevels}。`;
	}
	const invalidPersonnelIndex = personnelList.findIndex((row) => String(row?.major || "").trim() && !isValidCountText(row?.count));
	if (invalidPersonnelIndex >= 0) {
		return `机务人员第${invalidPersonnelIndex + 1}行数量为必填项。`;
	}
	const insufficientPersonnelIndex = personnelList.findIndex((row) => {
		const departmentName = String(row?.department || "").trim();
		const majorName = String(row?.major || "").trim();
		const levelName = String(row?.level || "").trim();
		const requestedCount = Number(row?.count || 0);
		if (!departmentName || !majorName || !levelName || !Number.isFinite(requestedCount)) return false;
		const availableCount = getPersonnelAvailableCount(departmentName, majorName, levelName);
		return requestedCount > availableCount;
	});
	if (insufficientPersonnelIndex >= 0) {
		const row = personnelList[insufficientPersonnelIndex] || {};
		const departmentName = String(row.department || "").trim();
		const majorName = String(row.major || "").trim();
		const levelName = String(row.level || "").trim();
		const requestedCount = Number(row.count || 0);
		const availableCount = getPersonnelAvailableCount(departmentName, majorName, levelName);
		return `机务人员第${insufficientPersonnelIndex + 1}行当前组织可用人数不足（组织：${departmentName || "-"}，专业：${majorName || "-"}，等级：${levelName || "-"}，可用 ${availableCount}，已填 ${requestedCount}）。`;
	}
	if (!String(item?.servicePersonnel || item?.team || "").trim()) {
		return "勤务人员不能为空。";
	}
	const equipmentList = parseEquipmentString(item?.equipment || "");
	const invalidEquipmentModelIndex = equipmentList.findIndex((row) => String(row?.name || "").trim() && !String(row?.model || "").trim());
	if (invalidEquipmentModelIndex >= 0) {
		return `保障设备第${invalidEquipmentModelIndex + 1}行型号为必填项。`;
	}
	const invalidEquipmentIndex = equipmentList.findIndex((row) => String(row?.name || "").trim() && !isValidCountText(row?.count));
	if (invalidEquipmentIndex >= 0) {
		return `保障设备第${invalidEquipmentIndex + 1}行数量为必填项。`;
	}
	const resourceList = activityType === "basic_repair" ? parseSpareString(item?.spare || "") : parseAmmunitionString(item?.ammunition || "");
	if (activityType === "basic_ops") {
		const invalidAmmunitionModelIndex = resourceList.findIndex((row) => String(row?.name || "").trim() && !String(row?.model || "").trim());
		if (invalidAmmunitionModelIndex >= 0) {
			return `弹药第${invalidAmmunitionModelIndex + 1}行型号为必填项。`;
		}
	}
	const invalidResourceIndex = resourceList.findIndex((row) => String(row?.name || "").trim() && !isValidCountText(row?.count));
	if (invalidResourceIndex >= 0) {
		return `保障资源第${invalidResourceIndex + 1}行数量为必填项。`;
	}
	const spareList = parseSpareString(item?.spare || "");
	const invalidSpareModelIndex = spareList.findIndex((row) => String(row?.name || "").trim() && !String(row?.model || "").trim());
	if (invalidSpareModelIndex >= 0) {
		return `备件第${invalidSpareModelIndex + 1}行型号为必填项。`;
	}
	const invalidSpareCountIndex = spareList.findIndex((row) => String(row?.name || "").trim() && !isValidCountText(row?.count));
	if (invalidSpareCountIndex >= 0) {
		return `备件第${invalidSpareCountIndex + 1}行数量为必填项。`;
	}
	if (activityType === "basic_repair" && !String(item.target || "").trim()) {
		return "飞机类型不能为空。";
	}
	if (activityType === "basic_ops" && !String(item.aircraftType || "").trim()) {
		return "飞机类型不能为空。";
	}
	const duplicatedCodeItem = findBasicActivityCodeConflict(item);
	if (duplicatedCodeItem) {
		return `基本保障活动编号重复：${String(item.activityCode || "").trim()} 已存在，请修改后再保存。`;
	}
	if (!String(item.workName || "").trim()) {
		return "工作名称不能为空。";
	}
	const durationError = validateBasicActivityDurationProfile(item.duration, item.durationProfile);
	if (durationError) {
		return durationError;
	}
	return "";
}

