function isServiceDepartmentStatic(departmentName) {
	return ORG_RESOURCE_SERVICE_LEVEL_ONLY_DEPARTMENTS.has(String(departmentName || "").trim());
}

function ensureOrgResourceRowsPerDepartment(baseRows, departments, minRowsPerDepartment, createSupplementRow) {
	const nextRows = (Array.isArray(baseRows) ? baseRows : []).map((row) => ({ ...row }));
	const departmentCountMap = new Map();
	nextRows.forEach((row) => {
		const departmentName = String(row?.department || "").trim();
		if (!departmentName) return;
		departmentCountMap.set(departmentName, (departmentCountMap.get(departmentName) || 0) + 1);
	});
	departments.forEach((departmentName, departmentIndex) => {
		const existingCount = departmentCountMap.get(departmentName) || 0;
		for (let rowIndex = existingCount; rowIndex < minRowsPerDepartment; rowIndex += 1) {
			nextRows.push(createSupplementRow(departmentName, rowIndex, departmentIndex));
		}
	});
	return nextRows;
}

