const DECK_SUPPORT_FUNCTIONS = ["供电", "加油", "氧气", "氮气", "压缩空气", "液压", "座舱通风", "设备舱通风", "淡水", "惯导对准", "接地", "维修机位", "试车机位"];
const DECK_CASE_SHIP_TYPE_IDS = ["ship-1", "ship-2", "ship-3", "ship-4"];
const DECK_CASE_SUPPORT_STATION_COUNTS = [25, 27, 29, 30];
const DECK_CASE_PARKING_STATION_COUNT = 15;
const DECK_PARKING_PREFIX = "非保障停机站位";
const DECK_HANGAR_PARKING_PREFIX = "机库非保障停机站位";
const DECK_PARKING_TYPE_LABEL = "非保障停机站位";
const DECK_HANGAR_PARKING_TYPE_LABEL = "机库非保障停机站位";

function getDeckParkingPrefixAliases(prefix) {
	if (prefix === DECK_PARKING_PREFIX || prefix === "停机位") {
		return [DECK_PARKING_PREFIX, "停机位"];
	}
	if (prefix === DECK_HANGAR_PARKING_PREFIX || prefix === "机库停机位") {
		return [DECK_HANGAR_PARKING_PREFIX, "机库停机位"];
	}
	return [String(prefix || "").trim()].filter(Boolean);
}

function buildDeckParkingCaseFields(stationNo, parkingType = DECK_PARKING_TYPE_LABEL) {
	const normalizedNo = Number(stationNo);
	const safeNo = Number.isFinite(normalizedNo) && normalizedNo > 0 ? normalizedNo : 1;
	const typeLabel = String(parkingType || DECK_PARKING_TYPE_LABEL).trim() || DECK_PARKING_TYPE_LABEL;
	return {
		description: `${typeLabel}${safeNo}案例数据`
	};
}

function normalizeDeckTrialRunValue(value, fallbackValue = "否") {
	const text = String(value || "").trim();
	if (text === "是") return "是";
	if (text === "否") return "否";
	return fallbackValue === "是" ? "是" : "否";
}

function buildDeckCaseTrialRunValue(index) {
	return index % 2 === 0 ? "是" : "否";
}

function buildDeckSupportCaseTrialRunValue(index) {
	return index < 12 ? "是" : "否";
}

function getDeckParkingStationNo(item, fallbackNo = 1) {
	const codeMatch = String(item?.code || "").trim().match(/(\d+)$/);
	if (codeMatch && Number.isFinite(Number(codeMatch[1]))) {
		return Number(codeMatch[1]);
	}
	const nameMatch = String(item?.name || "").trim().match(/(\d+)$/);
	if (nameMatch && Number.isFinite(Number(nameMatch[1]))) {
		return Number(nameMatch[1]);
	}
	return Number.isFinite(Number(fallbackNo)) && Number(fallbackNo) > 0 ? Number(fallbackNo) : 1;
}

const DECK_INITIAL_STATIONS = DECK_CASE_SHIP_TYPE_IDS.flatMap((shipTypeId, shipIndex) => {
	const supportStationCount = DECK_CASE_SUPPORT_STATION_COUNTS[shipIndex] || DECK_CASE_SUPPORT_STATION_COUNTS[DECK_CASE_SUPPORT_STATION_COUNTS.length - 1] || 25;
	const supportStations = Array.from({ length: supportStationCount }, (_, index) => {
		const stationNo = index + 1;
		return {
			id: `station_${shipTypeId}_${stationNo}`,
			code: `ST-${String(stationNo).padStart(2, "0")}`,
			name: `保障站位${stationNo}`,
			type: index % 2 === 0 ? "起飞区" : "停机区",
			canTrialRun: buildDeckSupportCaseTrialRunValue(index),
			shipTypeId
		};
	});
	const parkingStations = Array.from({ length: DECK_CASE_PARKING_STATION_COUNT }, (_, index) => {
		const stationNo = index + 1;
		return {
			id: `parking_station_${shipTypeId}_${stationNo}`,
			code: `PK-${String(stationNo).padStart(2, "0")}`,
			name: `${DECK_PARKING_PREFIX}${stationNo}`,
			type: DECK_PARKING_TYPE_LABEL,
			canTrialRun: buildDeckCaseTrialRunValue(index),
			shipTypeId,
			...buildDeckParkingCaseFields(stationNo, DECK_PARKING_TYPE_LABEL)
		};
	});
	return supportStations.concat(parkingStations);
});

