function normalizeCorrRepairTypeSelection(value) {
	const fromArray = Array.isArray(value)
		? value
		: String(value || "")
			.split(/[，,、|]/)
			.map((item) => String(item || "").trim())
			.filter(Boolean);
	const normalized = Array.from(new Set(fromArray.filter((item) => CORR_REPAIR_TYPE_OPTIONS.includes(item))));
	return normalized.length > 0 ? normalized : [CORR_REPAIR_TYPE_OPTIONS[0]];
}

