function buildCorrRepairNodeCaseDetail(repairNodeName, equipmentName = "", repairProfile = null) {
	const nodeName = String(repairNodeName || "").trim() || "维修对象";
	const normalizedEquipmentName = String(equipmentName || "").trim();
	const normalizedRepairProfile = repairProfile && typeof repairProfile === "object" ? repairProfile : {};
	const normalizedMeanRepairTime = Number(normalizedRepairProfile.meanRepairTime);
	const seed = Array.from(nodeName).reduce((sum, ch) => sum + ch.charCodeAt(0), 0);
	const facilityOptions = getFacilityFnOptions();
	const serviceOptions = getServicePersonnelOptions();
	const departmentOptions = getPersonnelDepartmentOptions();
	const fallbackDepartments = departmentOptions.length > 0 ? departmentOptions : ["机务保障中队", "动力保障组"];
	const primaryDepartment = fallbackDepartments[seed % fallbackDepartments.length];
	const secondaryDepartment = fallbackDepartments[(seed + 3) % fallbackDepartments.length];
	const primaryLevelOptions = getPersonnelLevelDictionaryOptions(primaryDepartment);
	const secondaryLevelOptions = getPersonnelLevelDictionaryOptions(secondaryDepartment);
	const primaryMajorOptions = getPersonnelMajorOptions(primaryDepartment);
	const secondaryMajorOptions = getPersonnelMajorOptions(secondaryDepartment);
	const primaryMajor = (primaryMajorOptions[seed % Math.max(1, primaryMajorOptions.length)] || ORG_PERSONNEL_MAJOR_DICTIONARY[seed % ORG_PERSONNEL_MAJOR_DICTIONARY.length] || "机电");
	const secondaryMajor = (secondaryMajorOptions[(seed + 1) % Math.max(1, secondaryMajorOptions.length)] || ORG_PERSONNEL_MAJOR_DICTIONARY[(seed + 1) % ORG_PERSONNEL_MAJOR_DICTIONARY.length] || "航电");
	const personnel = serializePersonnelList([
		{
			department: primaryDepartment,
			major: primaryMajor,
			level: primaryLevelOptions[seed % Math.max(1, primaryLevelOptions.length)] || "L1",
			count: String((seed % 3) + 1)
		},
		{
			department: secondaryDepartment,
			major: secondaryMajor,
			level: secondaryLevelOptions[(seed + 1) % Math.max(1, secondaryLevelOptions.length)] || "L1",
			count: String(((seed + 1) % 3) + 1)
		}
	]);
	const equipmentSourceRows = (state.organizationResources?.equipment || ORG_EQUIPMENT_MODELS)
		.map((row) => ({ name: String(row?.name || "").trim(), model: String(row?.model || "").trim(), supportModel: String(row?.supportModel || "").trim() }))
		.filter((row) => row.name && row.model);
	const scopedEquipmentRows = normalizedEquipmentName
		? equipmentSourceRows.filter((row) => isRepairTargetMatched(row.supportModel, normalizedEquipmentName))
		: equipmentSourceRows;
	const equipmentCandidates = scopedEquipmentRows.length > 0 ? scopedEquipmentRows : equipmentSourceRows;
	const equipment = serializeEquipmentList(
		(equipmentCandidates.length > 0 ? [0, 1] : [])
			.map((offset, index) => equipmentCandidates[(seed + offset) % equipmentCandidates.length])
			.filter(Boolean)
			.map((row, index) => ({
				name: row.name,
				model: row.model,
				count: String(((seed + index) % 2) + 1)
			}))
	);
	const spareSourceRows = (state.organizationResources?.spare || ORG_SPARE_MODELS)
		.map((row) => ({ name: String(row?.name || "").trim(), model: String(row?.model || "").trim(), supportModel: String(row?.supportModel || "").trim() }))
		.filter((row) => row.name && row.model);
	const scopedSpareRows = normalizedEquipmentName
		? spareSourceRows.filter((row) => isRepairTargetMatched(row.supportModel, normalizedEquipmentName))
		: spareSourceRows;
	const spareCandidates = scopedSpareRows.length > 0 ? scopedSpareRows : spareSourceRows;
	const spare = serializeSpareList(
		(spareCandidates.length > 0 ? [0, 1] : [])
			.map((offset, index) => spareCandidates[(seed + offset + 3) % spareCandidates.length])
			.filter(Boolean)
			.map((row, index) => ({
				name: row.name,
				model: row.model,
				count: String(((seed + index + 1) % 4) + 1)
			}))
	);
	const facility = facilityOptions.length > 0
		? serializeFacilityList([
			facilityOptions[seed % facilityOptions.length],
			facilityOptions[(seed + 2) % facilityOptions.length]
		])
		: "";

	return {
		target: normalizedEquipmentName,
		supportActivity: "维修保障",
		workName: nodeName,
		meanRepairTime: normalizedMeanRepairTime > 0 ? normalizedMeanRepairTime : "",
		repairSampleDistribution: String(normalizedRepairProfile.repairSampleDistribution || "").trim(),
		repairSampleDistributionParam1: String(normalizedRepairProfile.repairSampleDistributionParam1 || "").trim(),
		repairSampleDistributionParam2: String(normalizedRepairProfile.repairSampleDistributionParam2 || "").trim(),
		durationProfile: cloneActivityDurationProfile(normalizedRepairProfile.durationProfile, normalizedMeanRepairTime > 0 ? normalizedMeanRepairTime : 10),
		repairTypes: [seed % 2 === 0 ? "原位维修" : "换件维修"],
		repairType: seed % 2 === 0 ? "原位维修" : "换件维修",
		personnel,
		servicePersonnel: serviceOptions[seed % Math.max(1, serviceOptions.length)] || "",
		facility,
		equipment,
		spare
	};
}

