const INITIAL_COMPREHENSIVE_PLAN_STATE = createInitialComprehensivePlanState();

function getInitialOpsActivityOptionsByModel(comprehensiveState, modelName) {
	const normalizedModelName = String(modelName || "").trim();
	if (!normalizedModelName) return [];
	return Array.from(
		new Set(
			((comprehensiveState?.comprehensivePlans?.ops_plan) || [])
				.filter((plan) => String(plan?.draft?.model || "").trim() === normalizedModelName)
				.map((plan) => String(plan?.draft?.activityName || "").trim())
				.filter(Boolean)
		)
	);
}

