function renderBasicTaskSupportActivityOptionHtml(modelName, selectedValue = "") {
	const options = getSingleMissionOpsActivityOptionsByModel(modelName);
	const selectedName = String(selectedValue || "").trim();
	const normalizedOptions = [...options];
	if (selectedName && !normalizedOptions.includes(selectedName)) {
		normalizedOptions.push(selectedName);
	}
	if (normalizedOptions.length === 0) {
		return `<option value="">当前机型暂无使用保障活动</option>`;
	}
	return [`<option value="">请选择使用保障活动</option>`]
		.concat(
			normalizedOptions.map((activityName) => `<option value="${htmlEscape(activityName)}" ${selectedName === activityName ? "selected" : ""}>${htmlEscape(activityName)}</option>`)
		)
		.join("");
}

