state.tasks.basicTasks = state.tasks.basicTasks || [];

function rebalanceDemoCaseUnitStations() {
	const parkingCount = Math.max(1, getDeckStationNamesByPrefix(DECK_PARKING_PREFIX).length);
	const supportCount = Math.max(1, getDeckStationNamesByPrefix("保障站位").length);
	if (!Array.isArray(state.tasks?.units) || state.tasks.units.length === 0) return;
	const buildExecutionUnitListByTask = (groupUnits, requiredEquipmentList) => {
		const sortedUnits = [...groupUnits].sort((left, right) =>
			String(left?.aircraftNo || "").localeCompare(String(right?.aircraftNo || ""), "zh-Hans-CN", { numeric: true })
		);
		const groupedRows = new Map();
		(requiredEquipmentList || []).forEach((row) => {
			const aircraftType = String(row?.aircraftType || "").trim();
			const singleMissionType = String(row?.singleMissionType || "").trim();
			const quantity = Math.floor(Number(row?.quantity || 0));
			if (!aircraftType || !singleMissionType || !Number.isFinite(quantity) || quantity <= 0) return;
			const key = `${aircraftType}__${singleMissionType}`;
			const previous = groupedRows.get(key) || { aircraftType, singleMissionType, quantity: 0 };
			previous.quantity += quantity;
			groupedRows.set(key, previous);
		});
		const requiredRows = Array.from(groupedRows.values());
		const availableUnitsByModel = sortedUnits.reduce((acc, unit) => {
			const modelName = String(unit?.model || "").trim();
			if (!modelName) return acc;
			if (!acc.has(modelName)) acc.set(modelName, []);
			acc.get(modelName).push(unit);
			return acc;
		}, new Map());
		const executionUnits = [];
		requiredRows.forEach((requiredRow) => {
			const pool = availableUnitsByModel.get(requiredRow.aircraftType) || [];
			for (let index = 0; index < requiredRow.quantity; index += 1) {
				const selectedUnit = pool.shift();
				if (!selectedUnit) break;
				executionUnits.push(selectedUnit);
			}
		});
		return executionUnits;
	};
	const unitsByGroup = new Map();
	state.tasks.units.forEach((unit) => {
		const groupName = normalizeUnitGroupName(unit?.groupName || "", "");
		if (!groupName) return;
		if (!unitsByGroup.has(groupName)) {
			unitsByGroup.set(groupName, []);
		}
		unitsByGroup.get(groupName).push(unit);
	});
	const basicTasks = Array.isArray(state.tasks?.basicTasks) ? state.tasks.basicTasks : [];
	unitsByGroup.forEach((groupUnits, groupName) => {
		const groupBasicTasks = basicTasks
			.filter((task) => normalizeUnitGroupName(inferBasicTaskGroupName(task) || "", "") === groupName)
			.filter((task) => Array.isArray(task?.requiredEquipmentList) && task.requiredEquipmentList.length > 0);
		const anchorTask = groupBasicTasks.reduce((best, current) => {
			const currentCount = (current.requiredEquipmentList || []).reduce((sum, row) => sum + Math.max(0, Math.floor(Number(row?.quantity || 0))), 0);
			const bestCount = (best?.requiredEquipmentList || []).reduce((sum, row) => sum + Math.max(0, Math.floor(Number(row?.quantity || 0))), 0);
			return currentCount > bestCount ? current : best;
		}, null);
		const anchorExecutionUnits = anchorTask ? buildExecutionUnitListByTask(groupUnits, anchorTask.requiredEquipmentList || []) : [];
		const anchorUnitIdSet = new Set(anchorExecutionUnits.map((unit) => String(unit?.id || "").trim()).filter(Boolean));
		const orderedGroupUnits = [
			...anchorExecutionUnits,
			...[...groupUnits]
				.filter((unit) => !anchorUnitIdSet.has(String(unit?.id || "").trim()))
				.sort((left, right) => String(left?.aircraftNo || "").localeCompare(String(right?.aircraftNo || ""), "zh-Hans-CN", { numeric: true }))
		];
		orderedGroupUnits.forEach((unit, index) => {
			const parkingNo = (index % parkingCount) + 1;
			const supportNoPrimary = (index % supportCount) + 1;
			const supportNoSecondary = ((index + 7) % supportCount) + 1;
			const parkingName = `${DECK_PARKING_PREFIX}${parkingNo}`;
			const supportNames = supportNoPrimary === supportNoSecondary
				? [`保障站位${supportNoPrimary}`]
				: [`保障站位${supportNoPrimary}`, `保障站位${supportNoSecondary}`];
			unit.initialPosition = parkingName;
			unit.initialStationName = parkingName;
			unit.initialSupportStationNames = supportNames;
			unit.initialSupportStationName = supportNames[0] || "";
		});
	});

	const unitById = new Map(state.tasks.units.map((unit) => [String(unit?.id || "").trim(), unit]));
	if (Array.isArray(state.tasks?.basicTasks)) {
		state.tasks.basicTasks = state.tasks.basicTasks.map((task) => {
			const taskGroupName = normalizeUnitGroupName(inferBasicTaskGroupName(task) || task?.groupName || "", "");
			const groupUnits = unitsByGroup.get(taskGroupName) || [];
			const groupedRows = new Map();
			(task?.requiredEquipmentList || []).forEach((row) => {
				const aircraftType = String(row?.aircraftType || "").trim();
				const singleMissionType = String(row?.singleMissionType || "").trim();
				const quantity = Math.floor(Number(row?.quantity || 0));
				if (!aircraftType || !singleMissionType || !Number.isFinite(quantity) || quantity <= 0) return;
				const key = `${aircraftType}__${singleMissionType}`;
				const previous = groupedRows.get(key) || { aircraftType, singleMissionType, quantity: 0 };
				previous.quantity += quantity;
				groupedRows.set(key, previous);
			});
			const requiredRows = Array.from(groupedRows.values());
			const availableUnitsByModel = [...groupUnits]
				.sort((left, right) => String(left?.aircraftNo || "").localeCompare(String(right?.aircraftNo || ""), "zh-Hans-CN", { numeric: true }))
				.reduce((acc, unit) => {
					const modelName = String(unit?.model || "").trim();
					if (!modelName) return acc;
					if (!acc.has(modelName)) acc.set(modelName, []);
					acc.get(modelName).push(unit);
					return acc;
				}, new Map());
			const executionRows = [];
			requiredRows.forEach((requiredRow) => {
				const pool = availableUnitsByModel.get(requiredRow.aircraftType) || [];
				for (let index = 0; index < requiredRow.quantity; index += 1) {
					const selectedUnit = pool.shift();
					if (!selectedUnit) break;
					executionRows.push({ unit: selectedUnit, singleMissionName: requiredRow.singleMissionType });
				}
			});
			const sourceTroopByAircraftNo = new Map(
				(Array.isArray(task?.troops) ? task.troops : [])
					.map((troop) => [String(troop?.aircraftNo || "").trim(), troop])
					.filter(([aircraftNo]) => Boolean(aircraftNo))
			);
			return {
				...task,
				troops: executionRows.map((row, index) => {
					const matchedUnit = row.unit || null;
					if (!matchedUnit) return null;
					const aircraftNo = String(matchedUnit?.aircraftNo || "").trim();
					const sourceTroop = sourceTroopByAircraftNo.get(aircraftNo) || null;
					const rowNoBase = String(task?.id || "").trim() === "basic_demo_2" ? 6 : 1;
					const rowNo = rowNoBase + index;
					const parkingName = `${DECK_PARKING_PREFIX}${rowNo}`;
					const supportPrimary = `保障站位${rowNo}`;
					const supportSecondary = `保障站位${((rowNo + 10 - 1) % supportCount) + 1}`;
					const supportNames = supportPrimary === supportSecondary ? [supportPrimary] : [supportPrimary, supportSecondary];
					return {
						groupName: taskGroupName,
						unitId: String(matchedUnit?.id || sourceTroop?.unitId || "").trim(),
						aircraftNo,
						singleMissionName: String(row.singleMissionName || sourceTroop?.singleMissionName || "").trim(),
						initialStationName: parkingName,
						initialSupportStationNames: supportNames,
						model: String(matchedUnit?.model || sourceTroop?.model || "").trim(),
						taskType: String(row.singleMissionName || sourceTroop?.taskType || "").trim(),
						lifeLimit: Number(matchedUnit?.lifeLimit || sourceTroop?.lifeLimit || 0),
						flightHours: Number(matchedUnit?.flightHours || sourceTroop?.flightHours || 0),
						takeoffLimit: Number(matchedUnit?.takeoffLimit || sourceTroop?.takeoffLimit || 0),
						takeoffCount: Number(matchedUnit?.takeoffCount || sourceTroop?.takeoffCount || 0),
						count: 1
					};
				}).filter(Boolean)
			};
		});
	}
}

function getDeckStationNamesByPrefix(prefix) {
	const source = Array.isArray(state.deckModeling?.stations) ? state.deckModeling.stations : [];
	const aliases = new Set(getDeckParkingPrefixAliases(prefix));
	return source
		.filter((station) => {
			const stationName = String(station?.name || "").trim();
			if (!stationName) return false;
			return Array.from(aliases).some((alias) => stationName.startsWith(alias)) || stationName.startsWith(prefix);
		})
		.map((station) => normalizeParkingStationName(String(station.name || "").trim()) || String(station.name || "").trim())
		.filter(Boolean)
		.filter((value, index, list) => list.indexOf(value) === index)
		.sort((left, right) => {
			const leftNo = Number(String(left).replace(/\D+/g, ""));
			const rightNo = Number(String(right).replace(/\D+/g, ""));
			if (Number.isFinite(leftNo) && Number.isFinite(rightNo) && leftNo !== rightNo) {
				return leftNo - rightNo;
			}
			return left.localeCompare(right, "zh-Hans-CN", { numeric: true });
		});
}

function ensureDeckParkingCapacity(requiredCount) {
	if (!Number.isFinite(requiredCount) || requiredCount <= 0) return;
	if (!Array.isArray(state.deckModeling?.stations)) {
		state.deckModeling.stations = [];
	}
	const existingParkingNos = getDeckStationNamesByPrefix(DECK_PARKING_PREFIX)
		.map((name) => Number(String(name).replace(/\D+/g, "")))
		.filter((value) => Number.isFinite(value) && value > 0);
	let nextNo = existingParkingNos.length > 0 ? Math.max(...existingParkingNos) + 1 : 1;
	while (getDeckStationNamesByPrefix(DECK_PARKING_PREFIX).length < requiredCount) {
		const stationNo = nextNo;
		state.deckModeling.stations.push({
			id: `parking_station_${stationNo}`,
			code: `PK-${String(stationNo).padStart(2, "0")}`,
			name: `${DECK_PARKING_PREFIX}${stationNo}`,
			type: DECK_PARKING_TYPE_LABEL,
			...buildDeckParkingCaseFields(stationNo, DECK_PARKING_TYPE_LABEL)
		});
		nextNo += 1;
	}
}

function applyDemoCaseUnitModelTargets() {
	if (!Array.isArray(state.tasks?.units) || state.tasks.units.length === 0) return;
	const targetModelCounts = [
		{ model: "直-20F", count: 5, prefix: "Z20F" },
		{ model: "歼-15T", count: 13, prefix: "J15T" },
		{ model: "歼-35", count: 13, prefix: "J35" }
	];
	const units = state.tasks.units;
	const targetModels = new Set(targetModelCounts.map((item) => item.model));
	const normalizedUnits = units.filter((unit) => !targetModels.has(String(unit?.model || "").trim()));
	const existingAircraftNos = new Set(units.map((unit) => String(unit?.aircraftNo || "").trim()).filter(Boolean));
	const groupCycle = ["编队1", "编队2", "编队3"];

	function nextAircraftNo(prefix) {
		let nextIndex = 1;
		while (existingAircraftNos.has(`${prefix}-${String(nextIndex).padStart(3, "0")}`)) {
			nextIndex += 1;
		}
		const value = `${prefix}-${String(nextIndex).padStart(3, "0")}`;
		existingAircraftNos.add(value);
		return value;
	}

	targetModelCounts.forEach((target, modelIndex) => {
		const modelUnits = units
			.filter((unit) => String(unit?.model || "").trim() === target.model)
			.sort((left, right) => String(left?.aircraftNo || "").localeCompare(String(right?.aircraftNo || ""), "zh-Hans-CN", { numeric: true }));
		const keptUnits = modelUnits.slice(0, target.count);
		const template = keptUnits[0] || modelUnits[0] || {};
		for (let index = keptUnits.length; index < target.count; index += 1) {
			keptUnits.push({
				id: uid("unit"),
				name: `${target.model}-${index + 1}`,
				groupName: groupCycle[(modelIndex + index) % groupCycle.length],
				model: target.model,
				aircraftNo: nextAircraftNo(target.prefix),
				lifeLimit: Number(template.lifeLimit || 0),
				flightHours: Number(template.flightHours || 0),
				takeoffLimit: Number(template.takeoffLimit || 0),
				takeoffCount: Number(template.takeoffCount || 0),
				initialPosition: "",
				initialStationName: "",
				initialSupportStationNames: []
			});
		}
		normalizedUnits.push(...keptUnits);
	});

	state.tasks.units = normalizedUnits;
}

function ensureDemoUnitsGlobalUniqueStations() {
	if (!Array.isArray(state.tasks?.units) || state.tasks.units.length === 0) return;
	const parkingNames = getDeckStationNamesByPrefix(DECK_PARKING_PREFIX);
	const hangarParkingNames = getDeckStationNamesByPrefix(DECK_HANGAR_PARKING_PREFIX);
	const supportNames = getDeckStationNamesByPrefix("保障站位");
	const supportLength = Math.max(1, supportNames.length);
	const sortedUnits = [...state.tasks.units].sort((left, right) =>
		String(left?.aircraftNo || "").localeCompare(String(right?.aircraftNo || ""), "zh-Hans-CN", { numeric: true })
	);
	const designatedHangarModels = ["歼-15T", "歼-35"];
	const desiredPerModel = 3;
	const assignedStationByUnitId = new Map();
	let hangarCursor = 0;
	designatedHangarModels.forEach((modelName) => {
		const modelUnits = sortedUnits
			.filter((unit) => String(unit?.model || "").trim() === modelName)
			.slice(0, desiredPerModel);
		modelUnits.forEach((unit) => {
			const stationName = hangarParkingNames[hangarCursor] || "";
			if (!stationName) return;
			assignedStationByUnitId.set(String(unit?.id || ""), stationName);
			hangarCursor += 1;
		});
	});
	let deckCursor = 0;
	sortedUnits.forEach((unit, index) => {
		const unitId = String(unit?.id || "");
		const designatedStation = assignedStationByUnitId.get(unitId) || "";
		const parkingName = designatedStation || parkingNames[deckCursor] || `${DECK_PARKING_PREFIX}${deckCursor + 1}`;
		if (!designatedStation) {
			deckCursor += 1;
		}
		const supportName = supportNames[index % supportLength] || "";
		unit.initialPosition = parkingName;
		unit.initialStationName = parkingName;
		unit.initialSupportStationNames = supportName ? [supportName] : [];
		unit.initialSupportStationName = supportName;
	});
}

applyDemoCaseUnitModelTargets();
rebalanceDemoCaseUnitStations();
ensureDemoUnitsGlobalUniqueStations();

function uid(prefix) {
	return `${prefix}_${Math.random().toString(36).slice(2, 10)}`;
}

function htmlEscape(value) {
	return String(value ?? "")
		.replaceAll("&", "&amp;")
		.replaceAll("<", "&lt;")
		.replaceAll(">", "&gt;")
		.replaceAll('"', "&quot;");
}

function getHashRoute() {
	const raw = window.location.hash.replace(/^#/, "") || "/login";
	return raw.startsWith("/") ? raw : `/${raw}`;
}

function setRoute(route) {
	if (window.location.hash !== `#${route}`) {
		window.location.hash = route;
	} else {
		render();
	}
}

function syncExperimentTabByRoute(route) {
	if (route === "/simulation/experiments") {
		state.ui.expTab = "experiments";
		return;
	}
	if (route === "/simulation/visual") {
		state.ui.expTab = "visual";
		return;
	}
	if (route === "/simulation/mc") {
		state.ui.expTab = "mc";
		if (!["mc_config_eval", "ortho_config_analysis"].includes(state.ui.expMcTab || "")) {
			state.ui.expMcTab = "mc_config_eval";
		}
	}
}

function ensureExperimentManagerConfig() {
	const defaults = createDefaultExperimentManagerConfig();
	const current = state.ui?.experimentManagerConfig && typeof state.ui.experimentManagerConfig === "object"
		? state.ui.experimentManagerConfig
		: {};
	const compositeSchemeIdSet = new Set(getPeriodicTaskSchemeOptions().map((item) => item.id));
	const legacyTaskDispatchDeckOccupationRule = String(state.ui?.taskDispatchModelingConfig?.deckOccupationRule || "").trim();
	const deckOccupationRuleSource = String(current.deckOccupationRule || legacyTaskDispatchDeckOccupationRule || defaults.deckOccupationRule).trim();
	const deckOccupationRule = ["单波次", "两波次", "三波次"].includes(deckOccupationRuleSource)
		? deckOccupationRuleSource
		: defaults.deckOccupationRule;
	const taskSchemeIdSource = String(current.taskSchemeId || defaults.taskSchemeId || "").trim();
	const taskSchemeId = compositeSchemeIdSet.has(taskSchemeIdSource) ? taskSchemeIdSource : "";
	const seedType = String(current.seedType || defaults.seedType).trim() === "fixed" ? "fixed" : "random";
	const seedValue = Number(current.seedValue);
	const safetyRadius = Number(current.safetyRadius);
	const normalizeOrthoOutputParams = (value) => {
		const candidates = Array.isArray(value)
			? value
			: String(value || "")
				.split(/[;,，]/)
				.map((item) => String(item || "").trim())
				.filter(Boolean);
		const normalized = Array.from(new Set(candidates.filter((item) => ORTHO_OUTPUT_PARAM_OPTIONS.includes(item))));
		return normalized.length >= 2 ? normalized.slice(0, 2) : defaults.orthoOutputParams.slice();
	};
	const normalizeOrthoParamName = (value, fallbackIndex) => {
		const requestedName = String(value || "").trim();
		if (ORTHO_PARAM_NAME_OPTIONS.includes(requestedName)) return requestedName;
		return ORTHO_PARAM_NAME_OPTIONS[fallbackIndex] || ORTHO_PARAM_NAME_OPTIONS[0];
	};
	const normalizePositiveNumber = (value, fallback) => {
		const numberValue = Number(value);
		return Number.isFinite(numberValue) && numberValue > 0 ? numberValue : fallback;
	};
	const normalizeNonNegativeNumber = (value, fallback) => {
		const numberValue = Number(value);
		return Number.isFinite(numberValue) && numberValue >= 0 ? numberValue : fallback;
	};
	const taskSuccessRateThreshold = Number(current.taskSuccessRateThreshold);
	state.ui.experimentManagerConfig = {
		deckOccupationRule,
		taskSchemeId,
		backupAircraftRule: String(current.backupAircraftRule || defaults.backupAircraftRule).trim() || defaults.backupAircraftRule,
		resourceConflictStrategy: String(current.resourceConflictStrategy || defaults.resourceConflictStrategy).trim() || defaults.resourceConflictStrategy,
		personnelWorkHours: normalizePositiveNumber(current.personnelWorkHours, defaults.personnelWorkHours),
		personnelRestHours: normalizeNonNegativeNumber(current.personnelRestHours, defaults.personnelRestHours),
		personnelHandoverMinutes: normalizeNonNegativeNumber(current.personnelHandoverMinutes, defaults.personnelHandoverMinutes),
		minimumEquipmentQuantity: Number.isFinite(Number(current.minimumEquipmentQuantity)) ? Math.max(0, Math.floor(Number(current.minimumEquipmentQuantity))) : defaults.minimumEquipmentQuantity,
		taskSuccessRateThreshold: Number.isFinite(taskSuccessRateThreshold) ? Math.min(1, Math.max(0, taskSuccessRateThreshold)) : defaults.taskSuccessRateThreshold,
		safetyRadius: Number.isFinite(safetyRadius) ? Math.max(0, safetyRadius) : defaults.safetyRadius,
		seedType,
		seedValue: Number.isFinite(seedValue) ? seedValue : defaults.seedValue,
		description: String(current.description || defaults.description),
		orthoParamAIndicatorId: normalizeOrthoParamName(current.orthoParamAIndicatorId, 0),
		orthoParamBIndicatorId: normalizeOrthoParamName(current.orthoParamBIndicatorId, 1),
		orthoParamCIndicatorId: normalizeOrthoParamName(current.orthoParamCIndicatorId, 2),
		orthoOutputParams: normalizeOrthoOutputParams(current.orthoOutputParams)
	};
	return state.ui.experimentManagerConfig;
}

function ensureTaskDispatchModelingConfig() {
	const defaults = createDefaultTaskDispatchModelingConfig();
	const current = state.ui?.taskDispatchModelingConfig && typeof state.ui.taskDispatchModelingConfig === "object"
		? state.ui.taskDispatchModelingConfig
		: {};
	const normalizeStationList = (value) => {
		if (!Array.isArray(value)) return [];
		return Array.from(new Set(value.map((item) => String(item || "").trim()).filter(Boolean)));
	};
	const deckOccupationRule = ["单波次", "两波次", "三波次"].includes(String(current.deckOccupationRule || "").trim())
		? String(current.deckOccupationRule || "").trim()
		: defaults.deckOccupationRule;
	state.ui.taskDispatchModelingConfig = {
		deckOccupationRule,
		initialParkingStations: normalizeStationList(current.initialParkingStations),
		temporaryRecoveryStations: normalizeStationList(current.temporaryRecoveryStations),
		finalRecoveryStations: normalizeStationList(current.finalRecoveryStations)
	};
	return state.ui.taskDispatchModelingConfig;
}

function syncTasksTabByRoute(route, previousRoute = "") {
	if (route === "/modeling/tasks" && previousRoute !== "/modeling/tasks") {
		const pendingTab = String(state.ui?.pendingTasksModelingTab || "").trim();
		state.tasksTab = ["basic", "composite", "unit", "periodic"].includes(pendingTab) ? pendingTab : "basic";
		state.ui.pendingTasksModelingTab = "";
	}
}

function showConfirm(message, callback) {
	const modalId = "confirm-modal-" + Date.now();
	const modalHtml = `
		<div id="${modalId}" class="modal-mask">
			<div class="modal" style="width: min(400px, 90vw); text-align: center; display: flex; flex-direction: column; justify-content: center; align-items: center; min-height: 160px;">
				<div style="flex: 1; display: flex; align-items: center; justify-content: center; padding: 20px; font-size: 16px; line-height: 1.5;">
					${htmlEscape(message).replace(/\n/g, "<br>")}
				</div>
				<div class="modal-foot" style="width: 100%; justify-content: center; padding-bottom: 16px;">
					<button class="btn-primary btn-confirm" style="min-width: 80px;">确定</button>
					<button class="btn-cancel" style="min-width: 80px;">取消</button>
				</div>
			</div>
		</div>
	`;
	document.body.insertAdjacentHTML("beforeend", modalHtml);
	const modalEl = document.getElementById(modalId);
	const cancelBtn = modalEl.querySelector(".btn-cancel");
	const confirmBtn = modalEl.querySelector(".btn-confirm");

	const close = (result) => {
		modalEl.remove();
		if (result && callback) callback();
	};

	cancelBtn.addEventListener("click", () => close(false));
	confirmBtn.addEventListener("click", () => close(true));
}

function showToast(message) {
	toastEl.textContent = message;
	toastEl.classList.toggle("toast-center", String(message).includes("导出成功"));
	toastEl.classList.add("show");
	clearTimeout(state.ui.toastTimer);
	state.ui.toastTimer = setTimeout(() => {
		toastEl.classList.remove("show");
	}, 2500);
}

function getStorageKey(suffix) {
	if (!state.auth) return suffix;
	return `${state.auth.username}_${suffix}`;
}

function loadLastProject() {
	const value = localStorage.getItem(getStorageKey("lastProject"));
	if (value && state.projects.some((project) => project.id === value)) {
		state.currentProjectId = value;
	}
}

function saveLastProject(projectId) {
	localStorage.setItem(getStorageKey("lastProject"), projectId);
}

function ensurePlanRecords(projectId) {
	if (!projectId) return [];
	if (!state.planRecords[projectId]) {
		const fallbackPlans = APP_CONFIG.planOptions[projectId] || [];
		state.planRecords[projectId] = fallbackPlans.map((name, index) => ({
			id: `plan_${projectId}_${index + 1}`,
			name,
			createdAt: "2026-03-02",
			description: ""
		}));
	}
	return state.planRecords[projectId];
}

function syncPlanOptions(projectId) {
	if (!projectId) return;
	const plans = ensurePlanRecords(projectId);
	APP_CONFIG.planOptions[projectId] = plans.map((plan) => plan.name);
}

function resolveProjectShipTypeId(project) {
	const directShipTypeId = String(project?.shipTypeId || "").trim();
	if (directShipTypeId && state.shipTypes.some((item) => item.id === directShipTypeId)) {
		return directShipTypeId;
	}
	const shipTypeCode = String(project?.shipType || "").trim();
	const codeMatch = shipTypeCode.match(/^0*(\d+)$/);
	if (codeMatch) {
		const shipTypeIdByCode = `ship-${Number(codeMatch[1])}`;
		if (state.shipTypes.some((item) => item.id === shipTypeIdByCode)) {
			return shipTypeIdByCode;
		}
	}
	const shipTypeByName = state.shipTypes.find((item) => String(item?.name || "").includes(shipTypeCode));
	return shipTypeByName?.id || "";
}

function resolveProjectLayoutPlanId(project) {
	const directLayoutPlanId = String(project?.layoutPlanId || "").trim();
	const shipTypeId = resolveProjectShipTypeId(project);
	const plans = getInitialLayoutPlansByShipType(shipTypeId);
	if (directLayoutPlanId && plans.some((plan) => String(plan?.id || "").trim() === directLayoutPlanId)) {
		return directLayoutPlanId;
	}
	return String(plans[0]?.id || "").trim();
}

function getInitialLayoutPlansByProject(projectId) {
	const project = state.projects.find((item) => item.id === projectId);
	if (!project) return [];
	const shipTypeId = resolveProjectShipTypeId(project);
	if (!shipTypeId) return [];
	return state.initialLayoutPlans.filter((plan) => plan.shipTypeId === shipTypeId);
}

function getInitialLayoutPlansByShipType(shipTypeId) {
	const normalizedShipTypeId = String(shipTypeId || "").trim();
	if (!normalizedShipTypeId) return [];
	return state.initialLayoutPlans.filter((plan) => String(plan.shipTypeId || "").trim() === normalizedShipTypeId);
}

function getProjectLayoutPlanDisplayName(projectId) {
	const project = state.projects.find((item) => item.id === projectId);
	if (!project) return "未选择";
	const layoutPlanId = resolveProjectLayoutPlanId(project);
	const layoutPlan = getInitialLayoutPlansByProject(projectId).find((plan) => String(plan?.id || "").trim() === layoutPlanId);
	return String(layoutPlan?.name || "").trim() || "未选择";
}

function getInitialLayoutPlanShortDisplayName(planName = "") {
	const normalizedName = String(planName || "").trim();
	if (!normalizedName) return "未选择";
	return normalizedName.replace(/^\d+号船-/, "").trim() || normalizedName;
}

function buildProjectLayoutPlanOptionsHtml(shipTypeId, selectedLayoutPlanId = "") {
	const normalizedShipTypeId = String(shipTypeId || "").trim();
	const normalizedSelectedId = String(selectedLayoutPlanId || "").trim();
	const plans = getInitialLayoutPlansByShipType(normalizedShipTypeId);
	return [`<option value="">请选择布列方案</option>`]
		.concat(
			plans.map(
				(plan) =>
					`<option value="${htmlEscape(plan.id)}" ${String(plan.id || "").trim() === normalizedSelectedId ? "selected" : ""}>${htmlEscape(getInitialLayoutPlanShortDisplayName(plan.name || ""))}</option>`
			)
		)
		.join("");
}

function activateProjectContext(projectId, options = {}) {
	const normalizedProjectId = String(projectId || "").trim();
	const project = state.projects.find((item) => String(item?.id || "").trim() === normalizedProjectId);
	if (!project) {
		state.currentProjectId = "";
		state.currentPlanId = "";
		state.currentLayoutPlanId = "";
		state.ui.selectedPlanIds = [];
		if (state.ui && typeof state.ui === "object") {
			state.ui.homeSelectedShipTypeId = "";
		}
		saveLastProject("");
		return;
	}
	const shipTypeId = resolveProjectShipTypeId(project);
	const layoutPlanId = resolveProjectLayoutPlanId(project);
	project.shipTypeId = shipTypeId;
	project.shipType = getProjectShipTypeDisplayName(project.id);
	project.layoutPlanId = layoutPlanId;
	state.currentProjectId = project.id;
	state.currentPlanId = "";
	state.currentLayoutPlanId = layoutPlanId;
	state.ui.selectedPlanIds = [];
	if (!state.ui || typeof state.ui !== "object") {
		state.ui = {};
	}
	state.ui.homeSelectedShipTypeId = shipTypeId;
	saveLastProject(project.id);
	if (options.syncLayoutStorage !== false) {
		saveLastLayoutPlan(project.id, layoutPlanId);
	}
}

function getHomeSelectedShipTypeId() {
	const current = String(state.ui?.homeSelectedShipTypeId || "").trim();
	if (!current) {
		if (!state.ui || typeof state.ui !== "object") {
			state.ui = {};
		}
		state.ui.homeSelectedShipTypeId = "";
		return "";
	}
	if (current && state.shipTypes.some((item) => item.id === current)) {
		return current;
	}
	if (!state.ui || typeof state.ui !== "object") {
		state.ui = {};
	}
	state.ui.homeSelectedShipTypeId = "";
	return "";
}

const ORG_STRUCTURE_BASE_TREE_TEMPLATE = JSON.parse(JSON.stringify(state.organizationTree || []));

function cloneOrganizationTree(tree) {
	return JSON.parse(JSON.stringify(Array.isArray(tree) ? tree : []));
}

function buildOrganizationTreeByShipType(shipTypeId) {
	const normalizedShipTypeId = String(shipTypeId || "").trim();
	const tree = cloneOrganizationTree(ORG_STRUCTURE_BASE_TREE_TEMPLATE);
	const mainRoot = findOrgNodeById(tree, "org-wing-main");
	const serviceRoot = findOrgNodeById(tree, "org-wing-svc");
	const fighterTeam = findOrgNodeById(tree, "org-wing-main-1");
	const technicalTeam = findOrgNodeById(tree, "org-wing-main-1-2");
	const helicopterTeam = findOrgNodeById(tree, "org-wing-main-2");
	const thirdMainTeam = findOrgNodeById(tree, "org-wing-main-3");

	if (normalizedShipTypeId === "ship-2") {
		if (thirdMainTeam) {
			thirdMainTeam.name = "舰载电子战机分队";
		}
		if (helicopterTeam) {
			helicopterTeam.children = [
				{ id: "org-wing-main-2-1", name: "反潜保障组", type: "group" },
				{ id: "org-wing-main-2-2", name: "搜救保障组", type: "group" }
			];
		}
		const deckServiceTeam = findOrgNodeById(tree, "org-wing-svc-2");
		if (deckServiceTeam) {
			deckServiceTeam.children = [
				...(Array.isArray(deckServiceTeam.children) ? deckServiceTeam.children : []),
				{ id: "org-wing-svc-2-5", name: "特种油料区队", type: "group" }
			];
		}
	}

	if (normalizedShipTypeId === "ship-3") {
		if (thirdMainTeam) {
			thirdMainTeam.name = "舰载预警/指挥机分队";
		}
		if (technicalTeam) {
			technicalTeam.children = [
				...(Array.isArray(technicalTeam.children) ? technicalTeam.children : []),
				{ id: "org-wing-main-1-2-6", name: "隐身涂层保障组", type: "group" }
			];
		}
		if (mainRoot) {
			mainRoot.children = [
				...(Array.isArray(mainRoot.children) ? mainRoot.children : []),
				{ id: "org-wing-main-4", name: "应急抢修分队", type: "team", children: [{ id: "org-wing-main-4-1", name: "快速抢修组", type: "group" }] }
			];
		}
	}

	if (normalizedShipTypeId === "ship-4") {
		if (thirdMainTeam) {
			thirdMainTeam.name = "舰载无人机分队";
		}
		if (fighterTeam) {
			fighterTeam.name = "舰载多用途机分队";
		}
		const ammoTeam = findOrgNodeById(tree, "org-wing-svc-4");
		if (ammoTeam) {
			ammoTeam.children = [
				...(Array.isArray(ammoTeam.children) ? ammoTeam.children : []),
				{ id: "org-wing-svc-4-3", name: "精确制导弹药区队", type: "group" },
				{ id: "org-wing-svc-4-4", name: "弹药安全监测区队", type: "group" }
			];
		}
		if (serviceRoot) {
			serviceRoot.children = [
				...(Array.isArray(serviceRoot.children) ? serviceRoot.children : []),
				{ id: "org-wing-svc-5", name: "远海补给协同中队", type: "team", children: [{ id: "org-wing-svc-5-1", name: "舰岸协同保障组", type: "group" }] }
			];
		}
	}

	return tree;
}

function ensureOrganizationTreeBySelectedShipType() {
	if (!state.ui || typeof state.ui !== "object") {
		state.ui = {};
	}
	const selectedShipTypeId = getHomeSelectedShipTypeId();
	if (!selectedShipTypeId) {
		return;
	}
	if (!state.ui.organizationTreesByShipType || typeof state.ui.organizationTreesByShipType !== "object") {
		state.ui.organizationTreesByShipType = {};
	}
	const shipTreeStore = state.ui.organizationTreesByShipType;
	if (Object.keys(shipTreeStore).length === 0) {
		(state.shipTypes || []).forEach((shipType) => {
			const shipTypeId = String(shipType?.id || "").trim();
			if (!shipTypeId) return;
			shipTreeStore[shipTypeId] = buildOrganizationTreeByShipType(shipTypeId);
		});
	}
	const currentBoundShipTypeId = String(state.ui.organizationTreeShipTypeId || "").trim();
	if (!shipTreeStore[selectedShipTypeId]) {
		shipTreeStore[selectedShipTypeId] = buildOrganizationTreeByShipType(selectedShipTypeId);
	}
	if (currentBoundShipTypeId && currentBoundShipTypeId !== selectedShipTypeId) {
		shipTreeStore[currentBoundShipTypeId] = state.organizationTree;
	}
	if (state.organizationTree !== shipTreeStore[selectedShipTypeId]) {
		state.organizationTree = shipTreeStore[selectedShipTypeId];
		state.ui.collapsedOrganizationNodeIds = [];
	}
	if (!findOrgNodeById(state.organizationTree, state.selectedOrgId)) {
		state.selectedOrgId = findFirstOrgNodeId(state.organizationTree) || "";
	}
	state.ui.organizationTreeShipTypeId = selectedShipTypeId;
}

function getInitialLayoutSupportStationOptions(shipTypeId = "") {
	const normalizedShipTypeId = String(shipTypeId || "").trim();
	const rows = (Array.isArray(ensureDeckModelingState()?.stations) ? ensureDeckModelingState().stations : [])
		.filter((item) => !isDeckParkingStation(item))
		.filter((item) => !normalizedShipTypeId || normalizeDeckShipTypeId(item?.shipTypeId, "") === normalizedShipTypeId)
		.map((item) => ({
			code: String(item?.code || "").trim(),
			name: String(item?.name || "").trim() || String(item?.code || "").trim()
		}))
		.filter((item) => item.code || item.name);
	const parseNo = (text) => {
		const match = String(text || "").match(/(\d+)/);
		return match ? Number(match[1]) : Number.POSITIVE_INFINITY;
	};
	return rows.sort((left, right) => {
		const leftNo = parseNo(left.name || left.code);
		const rightNo = parseNo(right.name || right.code);
		if (leftNo !== rightNo) return leftNo - rightNo;
		return String(left.name || left.code).localeCompare(String(right.name || right.code), "zh-Hans-CN");
	});
}

function getInitialLayoutParkingStationCodeOptions(shipTypeId = "") {
	const deck = ensureDeckModelingState();
	const normalizedShipTypeId = String(shipTypeId || "").trim();
	const seen = new Set();
	const rows = (Array.isArray(deck?.stations) ? deck.stations : [])
		.filter((item) => isDeckParkingStation(item))
		.filter((item) => !normalizedShipTypeId || normalizeDeckShipTypeId(item?.shipTypeId, "") === normalizedShipTypeId)
		.map((item) => {
			const code = String(item?.code || "").trim();
			if (!code || seen.has(code)) return null;
			seen.add(code);
			return {
				code,
				shipTypeId: normalizeDeckShipTypeId(item?.shipTypeId, "")
			};
		})
		.filter(Boolean);
	const parseCode = (codeText) => {
		const text = String(codeText || "").trim();
		const match = text.match(/^([A-Za-z]+)-?(\d+)$/);
		if (!match) return { prefix: text, no: Number.POSITIVE_INFINITY };
		return { prefix: match[1].toUpperCase(), no: Number(match[2]) };
	};
	return rows.sort((left, right) => {
		const leftCode = parseCode(left.code);
		const rightCode = parseCode(right.code);
		if (leftCode.prefix !== rightCode.prefix) {
			return leftCode.prefix.localeCompare(rightCode.prefix, "zh-Hans-CN");
		}
		return leftCode.no - rightCode.no;
	});
}

function ensureInitialLayoutDetailRows(planId, minCount = 20) {
	const normalizedPlanId = String(planId || "").trim();
	if (!normalizedPlanId) return;
	const aircraftTypeOptions = (Array.isArray(state.aircraftTypes) ? state.aircraftTypes : [])
		.map((item) => String(item?.name || "").trim())
		.filter(Boolean);
	const fallbackAircraftType = aircraftTypeOptions[0] || "歼-35";
	const resolveAircraftType = (indexHint = 0) => {
		if (aircraftTypeOptions.length === 0) return fallbackAircraftType;
		return aircraftTypeOptions[Math.abs(Number(indexHint) || 0) % aircraftTypeOptions.length] || fallbackAircraftType;
	};
	const optionCodes = getInitialLayoutParkingStationCodeOptions().map((item) => item.code);
	const optionCodeSet = new Set(optionCodes);
	const planRows = state.initialLayoutItems.filter((item) => String(item?.layoutPlanId || "").trim() === normalizedPlanId);
	const usedCodes = new Set();
	const fallbackQueue = optionCodes.slice();
	planRows.forEach((row, rowIndex) => {
		if (!String(row?.aircraftType || "").trim()) {
			row.aircraftType = resolveAircraftType(rowIndex);
		}
		const currentCode = String(row?.parkingStation || "").trim();
		const isValidUnique = currentCode && optionCodeSet.has(currentCode) && !usedCodes.has(currentCode);
		if (isValidUnique) {
			usedCodes.add(currentCode);
			return;
		}
		let replacementCode = "";
		while (fallbackQueue.length > 0) {
			const candidate = String(fallbackQueue.shift() || "").trim();
			if (!candidate || usedCodes.has(candidate)) continue;
			replacementCode = candidate;
			break;
		}
		if (replacementCode) {
			row.parkingStation = replacementCode;
			usedCodes.add(replacementCode);
		}
	});
	const safeMinCount = Math.max(0, Number(minCount) || 20);
	const existingRows = state.initialLayoutItems.filter((item) => String(item?.layoutPlanId || "").trim() === normalizedPlanId);
	if (existingRows.length >= safeMinCount) return;
	const usedParkingCodes = new Set(existingRows.map((item) => String(item?.parkingStation || "").trim()).filter(Boolean));
	const candidateCodes = optionCodes.filter((code) => !usedParkingCodes.has(code));
	const needCount = safeMinCount - existingRows.length;
	for (let index = 0; index < needCount && index < candidateCodes.length; index += 1) {
		state.initialLayoutItems.push({
			id: uid("ili"),
			layoutPlanId: normalizedPlanId,
			aircraftType: resolveAircraftType(existingRows.length + index),
			parkingStation: candidateCodes[index]
		});
	}
}

function getProjectShipTypeDisplayName(projectId) {
	const project = state.projects.find((item) => item.id === projectId);
	if (!project) return "未选择";
	const shipTypeId = resolveProjectShipTypeId(project);
	const shipType = state.shipTypes.find((item) => item.id === shipTypeId);
	if (shipType?.name) return shipType.name;
	return String(project.shipType || "").trim() || "未选择";
}

function loadLastLayoutPlan(projectId) {
	const value = localStorage.getItem(getStorageKey(`lastLayoutPlan_${projectId}`));
	const plans = getInitialLayoutPlansByProject(projectId);
	if (value && plans.some((plan) => plan.id === value)) {
		state.currentLayoutPlanId = value;
	} else {
		state.currentLayoutPlanId = plans[0]?.id || "";
	}
}

function saveLastLayoutPlan(projectId, layoutPlanId) {
	localStorage.setItem(getStorageKey(`lastLayoutPlan_${projectId}`), layoutPlanId);
}

function getCurrentPlanContextLabel() {
	const role = getCurrentRole();
	return role === ROLE.USER || role === ROLE.DATA_ADMIN ? "布列方案" : "方案";
}

function getCurrentPlanContextValue() {
	if (getCurrentRole() === ROLE.USER || getCurrentRole() === ROLE.DATA_ADMIN) {
		const plans = getInitialLayoutPlansByShipType(getHomeSelectedShipTypeId());
		const selectedPlan = plans.find((plan) => plan.id === state.currentLayoutPlanId);
		return selectedPlan?.name || "未选择";
	}
	const projectPlans = ensurePlanRecords(state.currentProjectId).map((plan) => plan.name);
	return state.currentPlanId && projectPlans.includes(state.currentPlanId) ? state.currentPlanId : "未选择";
}

function hasCurrentPlanSelection() {
	if (getCurrentRole() === ROLE.USER || getCurrentRole() === ROLE.DATA_ADMIN) {
		const plans = getInitialLayoutPlansByShipType(getHomeSelectedShipTypeId());
		return plans.some((plan) => plan.id === state.currentLayoutPlanId);
	}
	return Boolean(String(state.currentPlanId || "").trim());
}

function isUserShipAndLayoutRequiredRoute(route = "") {
	const normalizedRoute = String(route || "").trim();
	if (!normalizedRoute) return false;
	if (normalizedRoute.startsWith("/simulation/")) return true;
	if (normalizedRoute.startsWith("/optimization/")) return true;
	if (["/plans", "/plans/analysis", "/plans/optimization", "/plans/generation"].includes(normalizedRoute)) return true;
	if (
		[
			"/modeling/shipborne-aircraft",
			"/modeling/organization",
			"/modeling/organization/structure",
			"/modeling/organization/resources",
			"/modeling/activities",
			"/modeling/activities/basic",
			"/modeling/activities/comprehensive",
			"/modeling/tasks"
		].includes(normalizedRoute)
	) {
		return true;
	}
	return false;
}

function hasUserSelectedShipAndLayoutContext() {
	if (getCurrentRole() !== ROLE.USER) return true;
	const selectedShipTypeId = String(getHomeSelectedShipTypeId() || "").trim();
	if (!selectedShipTypeId) return false;
	const plans = getInitialLayoutPlansByShipType(selectedShipTypeId);
	return plans.some((plan) => String(plan?.id || "").trim() === String(state.currentLayoutPlanId || "").trim());
}

function ensureComprehensivePlanState() {
	const defaults = createInitialComprehensivePlanState();
	if (!state.ui.comprehensivePlans || typeof state.ui.comprehensivePlans !== "object") {
		state.ui.comprehensivePlans = defaults.comprehensivePlans;
	}
	const shouldEnsureMultiScheme = state.ui.opsPlanSchemeBootstrapDone !== true;
	ensureOpsPlanSchemesComplete({ ensureAtLeastTwoSchemes: shouldEnsureMultiScheme });
	state.ui.opsPlanSchemeBootstrapDone = true;
	if (!state.ui.comprehensiveActivePlanIds || typeof state.ui.comprehensiveActivePlanIds !== "object") {
		state.ui.comprehensiveActivePlanIds = defaults.comprehensiveActivePlanIds;
	}
	if (!state.ui.comprehensiveSelectedEquipmentNames || typeof state.ui.comprehensiveSelectedEquipmentNames !== "object") {
		state.ui.comprehensiveSelectedEquipmentNames = defaults.comprehensiveSelectedEquipmentNames;
	}
	["ops_plan", "prev_repair", "corr_repair"].forEach((tabKey) => {
		if (!Array.isArray(state.ui.comprehensivePlans[tabKey]) || state.ui.comprehensivePlans[tabKey].length === 0) {
			state.ui.comprehensivePlans[tabKey] = defaults.comprehensivePlans[tabKey];
		}
		const plans = state.ui.comprehensivePlans[tabKey];
		const currentActiveId = state.ui.comprehensiveActivePlanIds[tabKey];
		if (!plans.some((item) => item.id === currentActiveId)) {
			state.ui.comprehensiveActivePlanIds[tabKey] = plans[0]?.id || "";
		}
		const equipmentOptions =
			tabKey === "ops_plan" || tabKey === "prev_repair"
				? getEquipmentAircraftModelNames()
				: Array.from(
					new Set(
						plans
							.map((plan) => getComprehensivePlanEquipmentName(tabKey, plan))
							.filter(Boolean)
					)
				);
		const activePlan = plans.find((item) => item.id === state.ui.comprehensiveActivePlanIds[tabKey]) || plans[0] || null;
		const activeEquipmentName = getComprehensivePlanEquipmentName(tabKey, activePlan);
		const selectedEquipment = String(state.ui.comprehensiveSelectedEquipmentNames[tabKey] || "").trim();
		let nextSelectedEquipment = selectedEquipment;
		if (equipmentOptions.length > 0 && nextSelectedEquipment && !equipmentOptions.includes(nextSelectedEquipment)) {
			nextSelectedEquipment = "";
		}
		if (!nextSelectedEquipment && activeEquipmentName) {
			if (equipmentOptions.length === 0 || equipmentOptions.includes(activeEquipmentName)) {
				nextSelectedEquipment = activeEquipmentName;
			}
		}
		if (!nextSelectedEquipment && equipmentOptions.length > 0) {
			nextSelectedEquipment = equipmentOptions[0];
		}
		if (!nextSelectedEquipment && plans.length > 0) {
			nextSelectedEquipment = getComprehensivePlanEquipmentName(tabKey, plans[0]);
		}
		state.ui.comprehensiveSelectedEquipmentNames[tabKey] = nextSelectedEquipment;
	});
}

function getComprehensivePlansByTab(tabKey) {
	ensureComprehensivePlanState();
	return state.ui.comprehensivePlans[tabKey] || [];
}

function getActiveComprehensivePlan(tabKey) {
	const selectedEquipmentName = state.ui.comprehensiveSelectedEquipmentNames?.[tabKey];
	const plans = getComprehensivePlansByTab(tabKey);
	const activeId = state.ui.comprehensiveActivePlanIds?.[tabKey] || "";
	return plans.find((item) => item.id === activeId) || plans[0] || null;
}

function syncComprehensiveDraftPointers() {
	const opsPlan = getActiveComprehensivePlan("ops_plan");
	const prevPlan = getActiveComprehensivePlan("prev_repair");
	const corrPlan = getActiveComprehensivePlan("corr_repair");
	state.ui.opsPlanDraft = opsPlan?.draft || createDefaultOpsPlanDraft();
	state.ui.prevRepairDraft = prevPlan?.draft || createDefaultPrevRepairDraft();
	state.ui.corrRepairDraft = corrPlan?.draft || createDefaultCorrRepairDraft();
	if (state.ui.corrRepairDraft?.repairObject) {
		state.selectedEquipmentRepairNode = state.ui.corrRepairDraft.repairObject;
	}
	const fallbackRepairNodeId = ensureValidSelectedEquipmentRepairNode();
	if (state.ui.corrRepairDraft) {
		const repairObject = String(state.ui.corrRepairDraft.repairObject || "").trim();
		if (!repairObject || !findNodeById(state.equipmentTree, repairObject)) {
			state.ui.corrRepairDraft.repairObject = fallbackRepairNodeId;
		}
	}
}

function getSingleMissionPhasePlanOptions(modelName, planType) {
	const plans = getComprehensivePlansByTab("ops_plan");
	const normalizedTargetType = normalizeOpsPlanTypeName(planType);
	const filteredPlans = plans.filter((plan) => {
		const draft = plan?.draft || {};
		const isModelMatch = String(draft.model || "").trim() === String(modelName || "").trim();
		const isTypeMatch = normalizeOpsPlanTypeName(draft.planType) === normalizedTargetType;
		return isModelMatch && isTypeMatch;
	});
	return Array.from(
		new Set(
			filteredPlans
				.map((plan) => String(plan?.draft?.activityName || "").trim())
				.filter(Boolean)
		)
	);
}

function getSingleMissionOpsActivityOptionsByModel(modelName) {
	const normalizedModel = String(modelName || "").trim();
	if (!normalizedModel) return [];
	const plans = getComprehensivePlansByTab("ops_plan");
	return Array.from(
		new Set(
			plans
				.filter((plan) => String(plan?.draft?.model || "").trim() === normalizedModel)
				.map((plan) => String(plan?.draft?.activityName || "").trim())
				.filter(Boolean)
		)
	);
}

const SINGLE_MISSION_REQUIRED_PLAN_FIELDS = [
	{ key: "prePlan", type: "直接准备方案", activitySuffix: "直接准备活动", planNameSuffix: "直接准备方案" },
	{ key: "relaunchPlan", type: "再次出动准备方案", activitySuffix: "再次出动准备活动", planNameSuffix: "再次出动准备方案" },
	{ key: "postPlan", type: "飞行后检查方案", activitySuffix: "飞行后检查活动", planNameSuffix: "飞行后检查方案" },
	{ key: "mountPlan", type: "挂载方案", activitySuffix: "挂弹保障活动", planNameSuffix: "挂弹保障方案" },
	{ key: "fuelPlan", type: "加油方案", activitySuffix: "热加油保障活动", planNameSuffix: "热加油保障方案" }
];

function ensureSingleMissionRequiredOpsPlanOptionsByModel(modelName) {
	const normalizedModel = String(modelName || "").trim();
	if (!normalizedModel) return false;
	ensureComprehensivePlanState();
	const opsPlans = getComprehensivePlansByTab("ops_plan");
	let changed = false;
	SINGLE_MISSION_REQUIRED_PLAN_FIELDS.forEach((field) => {
		const options = getSingleMissionPhasePlanOptions(normalizedModel, field.type);
		if (options.length > 0) return;
		const draft = createDefaultOpsPlanDraft();
		draft.model = normalizedModel;
		draft.planType = field.type;
		draft.activityName = buildOpsPlanSchemeDisplayName(normalizedModel, 1);
		opsPlans.push({
			id: uid("ops_plan"),
			name: `${normalizedModel}${field.planNameSuffix}`,
			draft
		});
		changed = true;
	});
	return changed;
}

function parseAmmunitionRequirement(rawValue) {
	const text = String(rawValue || "").trim();
	if (!text || text === "无") return { type: "", count: 0 };
	const matched = text.match(/^(.*?)(?:\s*[xX×*]\s*(\d+))?$/);
	if (!matched) return { type: text, count: 1 };
	const type = String(matched[1] || "").trim();
	const count = matched[2] ? Number(matched[2]) : type ? 1 : 0;
	return { type, count: Number.isFinite(count) && count >= 0 ? count : 0 };
}

function normalizeSingleMissionMountItems(rawItems, fallbackItem) {
	const source = Array.isArray(rawItems)
		? rawItems
		: fallbackItem && typeof fallbackItem === "object"
			? [fallbackItem]
			: [];
	const normalized = source
		.map((item) => {
			const type = String(item?.type || "").trim();
			const count = Number(item?.count);
			return {
				type,
				count: Number.isFinite(count) && count >= 0 ? Math.floor(count) : 0
			};
		})
		.filter((item) => item.type || item.count > 0);
	return normalized;
}

function findOpsPlanByActivityName(activityName) {
	const target = String(activityName || "").trim();
	if (!target) return null;
	return getComprehensivePlansByTab("ops_plan").find((plan) => String(plan?.draft?.activityName || "").trim() === target) || null;
}

function getOpsPlanMaxWorkTimeRef(plan) {
	const draft = plan?.draft || {};
	const explicitValue = Number(draft.maxWorkTimeRef ?? plan?.maxWorkTimeRef);
	if (Number.isFinite(explicitValue) && explicitValue >= 0) {
		return Math.floor(explicitValue);
	}
	const jobDurations = Object.values(draft.jobs || {})
		.map((job) => Number(job?.duration))
		.filter((value) => Number.isFinite(value) && value > 0);
	return jobDurations.length > 0 ? Math.max(...jobDurations.map((value) => Math.floor(value))) : 0;
}

function findOpsPlanForBasicTaskPhase(basicTask, waveIndex = 0) {
	const task = basicTask && typeof basicTask === "object" ? basicTask : {};
	const planType = Number(waveIndex) > 0 ? "再次出动准备方案" : "直接准备方案";
	const normalizedPlanType = normalizeOpsPlanTypeName(planType);
	const modelName = String(task.equipmentType || task.model || "").trim();
	const activityName = String(task.supportActivityName || task.opsActivityName || task.prePlan || "").trim();
	const typedPlans = getComprehensivePlansByTab("ops_plan").filter((plan) => {
		const draft = plan?.draft || {};
		const modelMatches = !modelName || String(draft.model || "").trim() === modelName;
		const typeMatches = normalizeOpsPlanTypeName(draft.planType) === normalizedPlanType;
		return modelMatches && typeMatches;
	});
	if (activityName) {
		const activityMatched = typedPlans.find((plan) => String(plan?.draft?.activityName || "").trim() === activityName);
		if (activityMatched) return activityMatched;
		const anyTypeActivityMatched = getComprehensivePlansByTab("ops_plan").find((plan) => {
			const draft = plan?.draft || {};
			return (
				normalizeOpsPlanTypeName(draft.planType) === normalizedPlanType &&
				String(draft.activityName || "").trim() === activityName
			);
		});
		if (anyTypeActivityMatched) return anyTypeActivityMatched;
	}
	return typedPlans[0] || null;
}

function resolveBasicTaskPreparationMinutes(basicTask, waveIndex = 0) {
	const task = basicTask && typeof basicTask === "object" ? basicTask : {};
	const matchedPlan = findOpsPlanForBasicTaskPhase(task, waveIndex);
	const planMinutes = getOpsPlanMaxWorkTimeRef(matchedPlan);
	if (planMinutes > 0) return planMinutes;
	const fallbackValue = Number(
		Number(waveIndex) > 0
			? task.relaunchPreparationMinutes ?? task.relaunchPrepareMinutes ?? task.preparationMinutes
			: task.preparationMinutes ?? task.prepareMinutes ?? task.prepMinutes
	);
	return Number.isFinite(fallbackValue) && fallbackValue >= 0 ? Math.floor(fallbackValue) : 0;
}

function buildSingleMissionSupplyDraftFromPrePlan(prePlanName, baseItem) {
	const item = baseItem && typeof baseItem === "object" ? baseItem : {};
	const opsPlan = findOpsPlanByActivityName(prePlanName);
	const fuelActivity = BASIC_OPS_ACTIVITIES.find((activity) => String(activity.workName || "").includes("加油")) || null;
	const mountActivity = BASIC_OPS_ACTIVITIES.find((activity) => String(activity.workName || "").includes("挂弹")) || null;
	let fuelDuration = Number(fuelActivity?.duration) > 0 ? Number(fuelActivity.duration) : 0;
	let mountDuration = Number(mountActivity?.duration) > 0 ? Number(mountActivity.duration) : 0;
	const jobEntries = Object.entries(opsPlan?.draft?.jobs || {});
	const fuelJob = jobEntries.find(([jobName]) => String(jobName || "").includes("加油"));
	const mountJob = jobEntries.find(([jobName]) => String(jobName || "").includes("挂弹"));
	if (fuelJob && Number(fuelJob[1]?.duration) > 0) fuelDuration = Number(fuelJob[1].duration);
	if (mountJob && Number(mountJob[1]?.duration) > 0) mountDuration = Number(mountJob[1].duration);

	const parsedAmmunition = parseAmmunitionRequirement(mountActivity?.ammunition || "");
	const legacyMountType = String(item.requiredAmmunitionType || "").trim();
	const legacyMountCount = Number(item.requiredAmmunitionCount);
	const legacyMountItem = legacyMountType
		? {
			type: legacyMountType,
			count: Number.isFinite(legacyMountCount) && legacyMountCount >= 0 ? Math.floor(legacyMountCount) : 0
		}
		: parsedAmmunition.type
			? { type: parsedAmmunition.type, count: parsedAmmunition.count }
			: null;
	const mountItems = normalizeSingleMissionMountItems(item.requiredMountItems, legacyMountItem);
	const requiredFuelAmountT = Number(item.requiredFuelAmountT ?? item.requiredFuelAmount);

	return {
		requiredFuelAmountT: Number.isFinite(requiredFuelAmountT) && requiredFuelAmountT >= 0 ? requiredFuelAmountT : 0,
		requiredMountItems: mountItems,
		reference: {
			phasePlanName: String(prePlanName || "").trim(),
			opsPlanName: opsPlan?.name || "-",
			fuel: {
				workName: fuelActivity?.workName || "加油作业",
				duration: fuelDuration,
				equipment: fuelActivity?.equipment || "-",
				facility: fuelActivity?.facility || "-"
			},
			mount: {
				workName: mountActivity?.workName || "挂弹作业",
				duration: mountDuration,
				ammunition: mountActivity?.ammunition || "-"
			}
		}
	};
}

function setActiveComprehensivePlan(tabKey, planId) {
	const plans = getComprehensivePlansByTab(tabKey);
	if (!plans.some((item) => item.id === planId)) return;
	state.ui.comprehensiveActivePlanIds[tabKey] = planId;
	clearComprehensiveJobSelection(tabKey);
	const activePlan = plans.find((item) => item.id === planId) || null;
	if (activePlan) {
		const equipmentName = getComprehensivePlanEquipmentName(tabKey, activePlan);
		if (!state.ui.comprehensiveSelectedEquipmentNames || typeof state.ui.comprehensiveSelectedEquipmentNames !== "object") {
			state.ui.comprehensiveSelectedEquipmentNames = {};
		}
		state.ui.comprehensiveSelectedEquipmentNames[tabKey] = equipmentName;
	}
	syncComprehensiveDraftPointers();
}

function getComprehensivePlanEquipmentName(tabKey, plan) {
	const draft = plan?.draft || {};
	if (tabKey === "ops_plan") {
		const modelName = normalizeAircraftNodeName(String(draft.model || "").trim());
		return modelName || "未命名装备";
	}
	const equipmentName = tabKey === "prev_repair" ? normalizeAircraftNodeName(String(draft.equipmentName || "").trim()) : String(draft.equipmentName || "").trim();
	return equipmentName || "未命名装备";
}

function getEquipmentAircraftModelNames() {
	const result = [];
	const visited = new Set();
	const walk = (nodes) => {
		if (!Array.isArray(nodes)) return;
		nodes.forEach((node) => {
			if (!node || typeof node !== "object") return;
			if (node.type === "aircraft") {
				const modelName = getEquipmentAircraftModelName(node);
				if (modelName && !visited.has(modelName)) {
					visited.add(modelName);
					result.push(modelName);
				}
			}
			walk(node.children || []);
		});
	};
	walk(state.equipmentTree || []);
	return result;
}

function getEquipmentAircraftNodes() {
	const result = [];
	const walk = (nodes) => {
		if (!Array.isArray(nodes)) return;
		nodes.forEach((node) => {
			if (!node || typeof node !== "object") return;
			if (node.type === "aircraft") {
				result.push(node);
			}
			walk(node.children || []);
		});
	};
	walk(state.equipmentTree || []);
	return result;
}

function getEquipmentAircraftNosByModel(modelName = "") {
	const normalizedModel = inferEquipmentAircraftModelName(modelName);
	if (!normalizedModel) return [];
	const result = [];
	const visited = new Set();
	const walk = (nodes) => {
		if (!Array.isArray(nodes)) return;
		nodes.forEach((node) => {
			if (!node || typeof node !== "object") return;
			if (node.type === "aircraft" && getEquipmentAircraftModelName(node) === normalizedModel) {
				getEquipmentAircraftInfoRows(node).forEach((row) => {
					const aircraftNo = String(row?.aircraftNo || "").trim();
					if (!aircraftNo || visited.has(aircraftNo)) return;
					visited.add(aircraftNo);
					result.push(aircraftNo);
				});
			}
			walk(node.children || []);
		});
	};
	walk(state.equipmentTree || []);
	(state.tasks?.units || []).forEach((unit) => {
		if (inferEquipmentAircraftModelName(unit?.model || "") !== normalizedModel) return;
		const aircraftNo = String(unit?.aircraftNo || "").trim();
		if (!aircraftNo || visited.has(aircraftNo)) return;
		visited.add(aircraftNo);
		result.push(aircraftNo);
	});
	return result;
}

function findAircraftInitialStationNameByModelAndNo(modelName = "", aircraftNo = "") {
	const normalizedModel = inferEquipmentAircraftModelName(modelName);
	const normalizedNo = String(aircraftNo || "").trim();
	if (!normalizedModel || !normalizedNo) return "";
	const aircraftNodes = getEquipmentAircraftNodes();
	for (const node of aircraftNodes) {
		if (getEquipmentAircraftModelName(node) !== normalizedModel) continue;
		const rows = getEquipmentAircraftInfoRows(node);
		const targetRow = rows.find((row) => String(row?.aircraftNo || "").trim() === normalizedNo) || null;
		if (!targetRow) continue;
		return normalizeParkingStationName(targetRow?.initialStationName || targetRow?.initialPosition || "");
	}
	return "";
}

function normalizeAircraftNodeName(name) {
	return String(name || "")
		.replace(/[（(][^）)]*[）)]/g, "")
		.trim();
}

function getEquipmentAircraftModelOptions() {
	return Array.from(
		new Set(
			[
				...((state.aircraftTypes || []).map((item) => String(item?.name || "").trim()).filter(Boolean)),
				...((state.tasks?.units || []).map((unit) => String(unit?.model || "").trim()).filter(Boolean)),
				...((APP_CONFIG.modelTypes || []).map((item) => String(item || "").trim()).filter(Boolean))
			]
		)
	);
}

function formatAircraftDurationValue(totalMinutes) {
	const safeMinutes = Math.max(0, Math.floor(Number(totalMinutes) || 0));
	const hours = Math.floor(safeMinutes / 60);
	const minutes = String(safeMinutes % 60).padStart(2, "0");
	return `${hours}:${minutes}`;
}

function parseAircraftDurationValue(value, fallbackMinutes = 0) {
	const text = String(value || "").trim();
	if (!text) return Math.max(0, Math.floor(Number(fallbackMinutes) || 0));
	const matchedClock = text.match(/^(\d+):(\d{1,2})$/);
	if (matchedClock) {
		return Math.max(0, Number(matchedClock[1]) * 60 + Number(matchedClock[2]));
	}
	const numericValue = Number(text.replace(/[^\d.]/g, ""));
	if (Number.isFinite(numericValue) && numericValue >= 0) return Math.floor(numericValue * 60);
	return Math.max(0, Math.floor(Number(fallbackMinutes) || 0));
	}

function formatAircraftYearsValue(value) {
	const numericValue = Number(value);
	if (Number.isFinite(numericValue) && numericValue >= 0) return `${Math.floor(numericValue)}年`;
	const text = String(value || "").trim();
	return text || "0年";
}

function parseAircraftYearsValue(value, fallbackYears = 0) {
	const text = String(value || "").trim();
	const numericValue = Number(text.replace(/[^\d.]/g, ""));
	if (Number.isFinite(numericValue) && numericValue >= 0) return Math.floor(numericValue);
	return Math.max(0, Math.floor(Number(fallbackYears) || 0));
}

function computeAircraftRemainingLifeValue(postOverhaulRequiredLife, flightTime) {
	const remainingMinutes = Math.max(0, parseAircraftDurationValue(postOverhaulRequiredLife) - parseAircraftDurationValue(flightTime));
	return formatAircraftDurationValue(remainingMinutes);
}

function inferEquipmentAircraftModelName(name) {
	const normalized = normalizeAircraftNodeName(String(name || "").trim());
	if (!normalized) return "";
	const options = getEquipmentAircraftModelOptions();
	return options.find((item) => item === normalized) || normalized;
}

function getBasicUnitModelCountMap() {
	const result = new Map();
	(state.tasks?.units || []).forEach((unit) => {
		const modelName = inferEquipmentAircraftModelName(unit?.model || "");
		if (!modelName) return;
		result.set(modelName, (result.get(modelName) || 0) + 1);
	});
	return result;
}

function getEquipmentAircraftModelName(node) {
	if (!node || node.type !== "aircraft") return "";
	return inferEquipmentAircraftModelName(node.model || node.name || "");
}

function getEquipmentAircraftQuantityByModel(modelName) {
	if (!modelName) return 1;
	return getBasicUnitModelCountMap().get(modelName) || 1;
}

function suggestEquipmentAircraftModelName() {
	const options = getEquipmentAircraftModelOptions();
	if (options.length === 0) return "";
	const usedModels = new Set(
		(Array.isArray(state.equipmentTree) ? state.equipmentTree : [])
			.filter((node) => node?.type === "aircraft")
			.map((node) => getEquipmentAircraftModelName(node))
			.filter(Boolean)
	);
	return options.find((item) => !usedModels.has(item)) || options[0];
}

function suggestEquipmentAircraftNodeName() {
	const usedIndices = new Set(
		(Array.isArray(state.equipmentTree) ? state.equipmentTree : [])
			.filter((node) => node?.type === "aircraft")
			.map((node) => String(node.name || "").trim().match(/^(?:机型|飞机)(\d+)$/))
			.filter(Boolean)
			.map((match) => Number(match[1]))
			.filter((value) => Number.isInteger(value) && value > 0)
	);
	let index = 1;
	while (usedIndices.has(index)) {
		index += 1;
	}
	return `机型${index}`;
}

function createEquipmentAircraftRootNode(modelName = "") {
	const normalizedModel = inferEquipmentAircraftModelName(modelName) || suggestEquipmentAircraftModelName() || suggestEquipmentAircraftNodeName();
	return {
		id: uid("ac"),
		name: normalizedModel,
		type: "aircraft",
		model: normalizedModel,
		quantity: getEquipmentAircraftQuantityByModel(normalizedModel),
		isLru: false,
		isNOutOfK: false,
		kValue: "",
		faultRate: "",
		mtbcf: "",
		children: []
	};
}

function seedEquipmentAircraftRootsFromAircraftTypesIfNeeded() {
	if (!Array.isArray(state.equipmentTree)) {
		state.equipmentTree = [];
	}
	const existingAircraftNodes = getEquipmentAircraftNodes();
	if (existingAircraftNodes.length > 0) return;
	const aircraftTypeNames = (Array.isArray(state.aircraftTypes) ? state.aircraftTypes : [])
		.map((item) => String(item?.name || "").trim())
		.filter(Boolean);
	if (aircraftTypeNames.length === 0) return;
	state.equipmentTree = aircraftTypeNames.map((name) => createEquipmentAircraftRootNode(name));
}

function syncAircraftRootNamesToTypeOnly() {
	(Array.isArray(state.equipmentTree) ? state.equipmentTree : []).forEach((node) => {
		if (!node || node.type !== "aircraft") return;
		const currentName = String(node.name || "").trim();
		node.name = !currentName
			? suggestEquipmentAircraftNodeName()
			: /[（()）]/.test(currentName)
				? normalizeAircraftNodeName(currentName)
				: currentName;
		node.model = getEquipmentAircraftModelName(node) || suggestEquipmentAircraftModelName();
		if (!Number.isInteger(Number(node.quantity)) || Number(node.quantity) <= 0) {
			node.quantity = getEquipmentAircraftQuantityByModel(node.model);
		}
		node.isLru = false;
		node.isNOutOfK = false;
		node.kValue = "";
		node.faultRate = "";
		node.mtbcf = "";
		node.type = "aircraft";
		if (!Array.isArray(node.children)) node.children = [];
	});
}

const EQUIPMENT_FAULT_SAMPLE_DISTRIBUTION_OPTIONS = ["威布尔分布", "指数分布", "均匀分布", "正态分布"];
const EQUIPMENT_LRU_SAFETY_LEVEL_OPTIONS = ["低", "中", "高"];

const EQUIPMENT_FAULT_SAMPLE_DISTRIBUTION_PARAM_CONFIG = {
	"威布尔分布": [
		{ key: "faultSampleDistributionParam1", label: "形状参数(k)", placeholder: "请输入形状参数k" },
		{ key: "faultSampleDistributionParam2", label: "尺度参数(λ)", placeholder: "请输入尺度参数λ" }
	],
	"指数分布": [
		{ key: "faultSampleDistributionParam1", label: "速率参数(λ)", placeholder: "请输入速率参数λ" }
	],
	"均匀分布": [
		{ key: "faultSampleDistributionParam1", label: "最小值", placeholder: "请输入最小值" },
		{ key: "faultSampleDistributionParam2", label: "最大值", placeholder: "请输入最大值" }
	],
	"正态分布": [
		{ key: "faultSampleDistributionParam1", label: "均值(μ)", placeholder: "请输入均值μ" },
		{ key: "faultSampleDistributionParam2", label: "标准差(σ)", placeholder: "请输入标准差σ" }
	]
};

function getEquipmentFaultSampleDistributionParamConfig(distribution) {
	const normalizedDistribution = String(distribution || "").trim();
	return EQUIPMENT_FAULT_SAMPLE_DISTRIBUTION_PARAM_CONFIG[normalizedDistribution] || EQUIPMENT_FAULT_SAMPLE_DISTRIBUTION_PARAM_CONFIG["威布尔分布"];
}

function ensureEquipmentLruNodeDefaults(node) {
	if (!node || node.type !== "lru") return;
	delete node.commonalityCharacteristic;
	if (!EQUIPMENT_FAULT_SAMPLE_DISTRIBUTION_OPTIONS.includes(String(node.faultSampleDistribution || "").trim())) {
		node.faultSampleDistribution = EQUIPMENT_FAULT_SAMPLE_DISTRIBUTION_OPTIONS[0];
	}
	if (typeof node.faultSampleDistributionParam1 !== "string") {
		node.faultSampleDistributionParam1 = "";
	}
	if (typeof node.faultSampleDistributionParam2 !== "string") {
		node.faultSampleDistributionParam2 = "";
	}
	if (typeof node.isTestable !== "boolean") {
		node.isTestable = false;
	}
	if (typeof node.detectionIsolationTime !== "string") {
		node.detectionIsolationTime = "";
	}
	if (typeof node.faultRate !== "string") {
		node.faultRate = "";
	}
	if (typeof node.mtbcf !== "string") {
		node.mtbcf = "";
	}
	if (typeof node.meanRepairTime !== "string") {
		node.meanRepairTime = "";
	}
	if (!EQUIPMENT_FAULT_SAMPLE_DISTRIBUTION_OPTIONS.includes(String(node.repairSampleDistribution || "").trim())) {
		node.repairSampleDistribution = EQUIPMENT_FAULT_SAMPLE_DISTRIBUTION_OPTIONS[0];
	}
	if (typeof node.repairSampleDistributionParam1 !== "string") {
		node.repairSampleDistributionParam1 = "";
	}
	if (typeof node.repairSampleDistributionParam2 !== "string") {
		node.repairSampleDistributionParam2 = "";
	}
	if (typeof node.supportSpareDemand !== "string") {
		node.supportSpareDemand = "";
	}
	if (typeof node.supportToolDemand !== "string") {
		node.supportToolDemand = "";
	}
	if (!EQUIPMENT_LRU_SAFETY_LEVEL_OPTIONS.includes(String(node.safetyRiskLevel || "").trim())) {
		node.safetyRiskLevel = EQUIPMENT_LRU_SAFETY_LEVEL_OPTIONS[0];
	}
	if (typeof node.safetyProtectionRequirement !== "string") {
		node.safetyProtectionRequirement = "";
	}
	if (typeof node.environmentTempRange !== "string") {
		node.environmentTempRange = "";
	}
	if (typeof node.environmentHumidityRange !== "string") {
		node.environmentHumidityRange = "";
	}
}

function getEquipmentNodeMeanRepairTime(node) {
	const value = Number(node?.meanRepairTime);
	return value > 0 ? value : null;
}

function buildActivityDurationProfileFromEquipmentRepairProfile(repairProfile = {}) {
	const meanRepairTime = Number(repairProfile?.meanRepairTime);
	const safeDuration = meanRepairTime > 0 ? meanRepairTime : 10;
	const distribution = String(repairProfile?.repairSampleDistribution || "").trim();
	const param1 = Number(repairProfile?.repairSampleDistributionParam1);
	const param2 = Number(repairProfile?.repairSampleDistributionParam2);
	if (distribution === "正态分布") {
		return cloneActivityDurationProfile({
			distributionType: "正态分布",
			normalMean: Number.isFinite(param1) ? param1 : safeDuration,
			normalStdDev: Number.isFinite(param2) ? param2 : 1
		}, safeDuration);
	}
	if (distribution === "均匀分布") {
		return cloneActivityDurationProfile({
			distributionType: "均匀分布",
			uniformMin: Number.isFinite(param1) ? param1 : safeDuration,
			uniformMax: Number.isFinite(param2) ? param2 : safeDuration
		}, safeDuration);
	}
	return cloneActivityDurationProfile(null, safeDuration);
}

function describeEquipmentRepairDistribution(profile = {}) {
	const distribution = String(profile?.repairSampleDistribution || "").trim();
	if (!distribution) return "";
	const config = getEquipmentFaultSampleDistributionParamConfig(distribution);
	const values = [
		config[0] && String(profile?.repairSampleDistributionParam1 || "").trim()
			? `${config[0].label} ${String(profile.repairSampleDistributionParam1).trim()}`
			: "",
		config[1] && String(profile?.repairSampleDistributionParam2 || "").trim()
			? `${config[1].label} ${String(profile.repairSampleDistributionParam2).trim()}`
			: ""
	].filter(Boolean);
	return values.length > 0 ? `${distribution}（${values.join("，")}）` : distribution;
}

function getEquipmentRepairDistributionDetails(profile = {}) {
	const distributionType = String(profile?.repairSampleDistribution || "").trim();
	if (!distributionType) {
		return { distributionType: "", parameterText: "" };
	}
	const config = getEquipmentFaultSampleDistributionParamConfig(distributionType);
	const parameterText = [
		config[0] && String(profile?.repairSampleDistributionParam1 || "").trim()
			? `${config[0].label}：${String(profile.repairSampleDistributionParam1).trim()}`
			: "",
		config[1] && String(profile?.repairSampleDistributionParam2 || "").trim()
			? `${config[1].label}：${String(profile.repairSampleDistributionParam2).trim()}`
			: ""
	].filter(Boolean).join("；");
	return { distributionType, parameterText };
}

function getEquipmentRepairProfileForRepairTarget(repairObjectName = "", aircraftName = "") {
	const normalizedRepairObjectName = String(repairObjectName || "").trim();
	if (!normalizedRepairObjectName) return null;
	const normalizedAircraftName = String(aircraftName || "").trim();
	const aircraftNodes = getEquipmentAircraftNodes();
	const scopedAircraftNodes = normalizedAircraftName
		? aircraftNodes.filter((node) => {
			const modelName = String(getEquipmentAircraftModelName(node) || "").trim();
			const nodeName = String(node?.name || "").trim();
			return modelName === normalizedAircraftName || nodeName === normalizedAircraftName;
		})
		: aircraftNodes;
	const sourceNodes = scopedAircraftNodes.length > 0 ? scopedAircraftNodes : aircraftNodes;
	const stack = sourceNodes.flatMap((node) => Array.isArray(node?.children) ? node.children : []);
	while (stack.length > 0) {
		const currentNode = stack.shift();
		if (!currentNode || typeof currentNode !== "object") continue;
		if (String(currentNode.name || "").trim() === normalizedRepairObjectName) {
			const repairProfile = {
				meanRepairTime: getEquipmentNodeMeanRepairTime(currentNode),
				repairSampleDistribution: EQUIPMENT_FAULT_SAMPLE_DISTRIBUTION_OPTIONS.includes(String(currentNode.repairSampleDistribution || "").trim())
					? String(currentNode.repairSampleDistribution || "").trim()
					: EQUIPMENT_FAULT_SAMPLE_DISTRIBUTION_OPTIONS[0],
				repairSampleDistributionParam1: String(currentNode.repairSampleDistributionParam1 || "").trim(),
				repairSampleDistributionParam2: String(currentNode.repairSampleDistributionParam2 || "").trim()
			};
			return {
				...repairProfile,
				durationProfile: buildActivityDurationProfileFromEquipmentRepairProfile(repairProfile)
			};
		}
		if (Array.isArray(currentNode.children) && currentNode.children.length > 0) {
			stack.unshift(...currentNode.children);
		}
	}
	return null;
}

function getEquipmentMeanRepairTimeForRepairTarget(repairObjectName = "", aircraftName = "") {
	return getEquipmentRepairProfileForRepairTarget(repairObjectName, aircraftName)?.meanRepairTime ?? null;
}

function ensureEquipmentNodeDefaults(nodes) {
	(Array.isArray(nodes) ? nodes : []).forEach((node) => {
		if (!node || typeof node !== "object") return;
		ensureEquipmentLruNodeDefaults(node);
		if (Array.isArray(node.children) && node.children.length > 0) {
			ensureEquipmentNodeDefaults(node.children);
		}
	});
}

const INDICATOR_CATEGORY_OPTIONS = ["可靠性", "维修性", "测试性"];

function ensureEquipmentAircraftInfoSelectionState() {
	if (!state.ui || typeof state.ui !== "object") {
		state.ui = {};
	}
	if (!state.ui.selectedEquipmentAircraftInfoIds || typeof state.ui.selectedEquipmentAircraftInfoIds !== "object") {
		state.ui.selectedEquipmentAircraftInfoIds = {};
	}
}

function createEquipmentAircraftInfoRow(modelName, serialNumber) {
	const normalizedModelName = String(modelName || "机型").trim() || "机型";
	const serial = Math.max(1, Number(serialNumber) || 1);
	const suffix = String(serial).padStart(3, "0");
	const modelPrefix = normalizedModelName.replace(/[^A-Za-z0-9\u4e00-\u9fa5-]/g, "").slice(0, 6) || "FJ";
	const baseFactoryYearMap = {
		"歼-35": 2019,
		"歼-15T": 2015,
		"直-20F": 2020,
		"KE-600": 2018
	};
	const totalRequiredYearsMap = {
		"歼-35": 30,
		"歼-15T": 30,
		"直-20F": 25,
		"KE-600": 28
	};
	const totalRequiredYears = totalRequiredYearsMap[normalizedModelName] || 30;
	const factoryYear = Math.max(2012, (baseFactoryYearMap[normalizedModelName] || 2016) - ((serial - 1) % 4));
	const totalRequiredLifeMinutes = 120000 + serial * 180;
	const totalFlightTimeMinutes = 16560 + serial * 75;
	const postOverhaulRequiredLifeMinutes = 60000 + serial * 120;
	const flightTimeMinutes = 16560 + serial * 75;
	const totalRequiredTakeoff = 3000 + serial * 12;
	const totalTakeoffCount = 287 + serial * 5;
	const postOverhaulRequiredTakeoff = 1500 + serial * 8;
	const flightTakeoffCount = 287 + serial * 5;
	const totalRequiredYearsDisplay = formatAircraftYearsValue(totalRequiredYears);
	const postOverhaulRequiredYears = formatAircraftYearsValue(8);
	const totalRequiredLife = formatAircraftDurationValue(totalRequiredLifeMinutes);
	const totalFlightTime = formatAircraftDurationValue(totalFlightTimeMinutes);
	const postOverhaulRequiredLife = formatAircraftDurationValue(postOverhaulRequiredLifeMinutes);
	const flightTime = formatAircraftDurationValue(flightTimeMinutes);
	const remainingLife = computeAircraftRemainingLifeValue(postOverhaulRequiredLife, flightTime);
	const currentStatus = serial % 5 === 0 ? "停用" : serial % 3 === 0 ? "在册待修" : "在册完好";
	return {
		id: uid("acf"),
		model: normalizedModelName,
		aircraftNo: `${normalizedModelName}-${suffix}`,
		initialFactoryNo: `${modelPrefix}-FAC-${String(1200 + serial).padStart(4, "0")}`,
		engineCount: normalizedModelName.includes("直") || normalizedModelName.includes("KE") ? 2 : 2,
		unitName: `舰载机第${((serial - 1) % 3) + 1}分队`,
		supportOrganizationName: getDefaultAircraftSupportOrganizationName(normalizedModelName),
		periodicUnitAssignments: {},
		factoryDate: `${factoryYear}-${String(((serial - 1) % 12) + 1).padStart(2, "0")}-15`,
		overhaulCount: Math.floor((serial - 1) / 4),
		currentStatus,
		totalRequiredYears,
		totalRequiredYearsDisplay,
		totalRequiredLife,
		totalRequiredTakeoff,
		totalFlightTime,
		totalTakeoffCount,
		overhaulFactoryDate: `202${serial % 6}-0${((serial + 2) % 9) + 1}-20`,
		postOverhaulRequiredYears,
		postOverhaulRequiredLife,
		postOverhaulRequiredTakeoff,
		flightTime,
		remainingLife,
		flightTakeoffCount,
		isOnboard: serial % 5 !== 0,
		initialStationName: "",

		// Compatibility fields used by existing logic.
		lifeLimit: Math.floor(parseAircraftDurationValue(postOverhaulRequiredLife) / 60),
		flightHours: Math.floor(parseAircraftDurationValue(flightTime) / 60),
		takeoffLimit: postOverhaulRequiredTakeoff,
		takeoffCount: flightTakeoffCount,
		totalServiceLifeYears: totalRequiredYears,
		maintenanceCount: Math.floor((serial - 1) / 4),
		postMaintenanceRunHours: Math.max(0, Math.floor(parseAircraftDurationValue(flightTime) / 150)),
		leftEngineWorkHours: Math.max(0, Math.floor(parseAircraftDurationValue(flightTime) / 75)),
		rightEngineWorkHours: Math.max(0, Math.floor(parseAircraftDurationValue(flightTime) / 78)),
		totalWorkHours: Math.floor(parseAircraftDurationValue(totalFlightTime) / 60),
		commissionedHours: Math.max(0, Math.floor(parseAircraftDurationValue(totalFlightTime) / 80))
	};
}

function ensureUniqueAircraftInitialStationRows(rows = []) {
	const parkingNames = getInitialStationOptionsBySingleMissionName("").map((item) => String(item?.name || "").trim()).filter(Boolean);
	if (parkingNames.length === 0) return rows;
	const used = new Set();
	let fallbackCursor = 0;
	return rows.map((row) => {
		const current = normalizeParkingStationName(row?.initialStationName || row?.initialPosition || "");
		let nextStationName = "";
		if (current && parkingNames.includes(current) && !used.has(current)) {
			nextStationName = current;
		} else {
			while (fallbackCursor < parkingNames.length && used.has(parkingNames[fallbackCursor])) {
				fallbackCursor += 1;
			}
			nextStationName = parkingNames[fallbackCursor] || current || "";
			fallbackCursor += 1;
		}
		if (nextStationName) used.add(nextStationName);
		return {
			...row,
			initialStationName: nextStationName
		};
	});
}

function getEquipmentAircraftInfoRows(node) {
	if (!node || node.type !== "aircraft") return [];
	if (Array.isArray(node.aircraftInfos)) {
		const modelName = getEquipmentAircraftModelName(node) || normalizeAircraftNodeName(node.name || "") || "机型";
		node.aircraftInfos = ensureUniqueAircraftInitialStationRows(
			node.aircraftInfos.map((row, index) => {
				const draft = createEquipmentAircraftInfoRow(modelName, index + 1);
				const currentStatus = String(row?.currentStatus || "").trim() || (typeof row?.isOnboard === "boolean" ? (row.isOnboard ? "在册完好" : "停用") : draft.currentStatus);
				const totalRequiredYearsDisplay = String(row?.totalRequiredYearsDisplay || row?.totalRequiredYears || "").trim() || draft.totalRequiredYearsDisplay;
				const totalRequiredLife = String(row?.totalRequiredLife || "").trim() || draft.totalRequiredLife;
				const totalRequiredTakeoff = Number.isFinite(Number(row?.totalRequiredTakeoff)) ? Math.floor(Number(row.totalRequiredTakeoff)) : draft.totalRequiredTakeoff;
				const totalFlightTime = String(row?.totalFlightTime || "").trim() || draft.totalFlightTime;
				const totalTakeoffCount = Number.isFinite(Number(row?.totalTakeoffCount)) ? Math.floor(Number(row.totalTakeoffCount)) : draft.totalTakeoffCount;
				const postOverhaulRequiredYears = String(row?.postOverhaulRequiredYears || "").trim() || draft.postOverhaulRequiredYears;
				const postOverhaulRequiredLife = String(row?.postOverhaulRequiredLife || "").trim() || draft.postOverhaulRequiredLife;
				const postOverhaulRequiredTakeoff = Number.isFinite(Number(row?.postOverhaulRequiredTakeoff)) ? Math.floor(Number(row.postOverhaulRequiredTakeoff)) : draft.postOverhaulRequiredTakeoff;
				const flightTime = String(row?.flightTime || "").trim() || draft.flightTime;
				const remainingLife = String(row?.remainingLife || "").trim() || computeAircraftRemainingLifeValue(postOverhaulRequiredLife, flightTime);
				const flightTakeoffCount = Number.isFinite(Number(row?.flightTakeoffCount)) ? Math.floor(Number(row.flightTakeoffCount)) : (Number.isFinite(Number(row?.takeoffCount)) ? Math.floor(Number(row.takeoffCount)) : draft.flightTakeoffCount);
				return {
					...draft,
					...row,
					model: String(row?.model || modelName).trim() || modelName,
					supportOrganizationName: normalizeAircraftSupportOrganizationName(row?.supportOrganizationName || row?.supportOrgName || row?.maintenanceOrganization || row?.department || "", modelName),
					periodicUnitAssignments: normalizeShipborneAircraftPeriodicAssignments(row?.periodicUnitAssignments),
					currentStatus,
					totalRequiredYears: parseAircraftYearsValue(totalRequiredYearsDisplay, draft.totalRequiredYears),
					totalRequiredYearsDisplay,
					totalRequiredLife,
					totalRequiredTakeoff,
					totalFlightTime,
					totalTakeoffCount,
					postOverhaulRequiredYears,
					postOverhaulRequiredLife,
					postOverhaulRequiredTakeoff,
					flightTime,
					remainingLife,
					flightTakeoffCount,
					isOnboard: currentStatus !== "停用",
					lifeLimit: Math.floor(parseAircraftDurationValue(postOverhaulRequiredLife) / 60),
					flightHours: Math.floor(parseAircraftDurationValue(flightTime) / 60),
					takeoffLimit: postOverhaulRequiredTakeoff,
					takeoffCount: flightTakeoffCount,
					totalServiceLifeYears: parseAircraftYearsValue(totalRequiredYearsDisplay, 30),
					totalWorkHours: Math.floor(parseAircraftDurationValue(totalFlightTime) / 60)
				};
			})
		);
		node.quantity = node.aircraftInfos.length;
		return node.aircraftInfos;
	}

	const modelName = getEquipmentAircraftModelName(node) || normalizeAircraftNodeName(node.name || "") || "机型";
	const unitRows = (state.tasks?.units || [])
		.filter((unit) => inferEquipmentAircraftModelName(unit?.model || "") === modelName)
		.map((unit, index) => {
			const draft = createEquipmentAircraftInfoRow(modelName, index + 1);
			const hasCustomizedAircraftInfo = Boolean(unit?.aircraftInfoCustomized);
			const currentStatus = String(unit?.currentStatus || "").trim() || (typeof unit?.isOnboard === "boolean" ? (unit.isOnboard ? "在册完好" : "停用") : draft.currentStatus);
			const totalRequiredYearsDisplay = hasCustomizedAircraftInfo ? (String(unit?.totalRequiredYearsDisplay || unit?.totalRequiredYears || "").trim() || draft.totalRequiredYearsDisplay) : draft.totalRequiredYearsDisplay;
			const totalRequiredLife = hasCustomizedAircraftInfo ? (String(unit?.totalRequiredLife || "").trim() || draft.totalRequiredLife) : draft.totalRequiredLife;
			const totalRequiredTakeoff = hasCustomizedAircraftInfo && Number.isFinite(Number(unit?.totalRequiredTakeoff)) ? Math.floor(Number(unit.totalRequiredTakeoff)) : draft.totalRequiredTakeoff;
			const totalFlightTime = hasCustomizedAircraftInfo ? (String(unit?.totalFlightTime || "").trim() || draft.totalFlightTime) : draft.totalFlightTime;
			const totalTakeoffCount = hasCustomizedAircraftInfo && Number.isFinite(Number(unit?.totalTakeoffCount)) ? Math.floor(Number(unit.totalTakeoffCount)) : draft.totalTakeoffCount;
			const postOverhaulRequiredYears = hasCustomizedAircraftInfo ? (String(unit?.postOverhaulRequiredYears || "").trim() || draft.postOverhaulRequiredYears) : draft.postOverhaulRequiredYears;
			const postOverhaulRequiredLife = hasCustomizedAircraftInfo ? (String(unit?.postOverhaulRequiredLife || "").trim() || draft.postOverhaulRequiredLife) : draft.postOverhaulRequiredLife;
			const postOverhaulRequiredTakeoff = hasCustomizedAircraftInfo && Number.isFinite(Number(unit?.postOverhaulRequiredTakeoff)) ? Math.floor(Number(unit.postOverhaulRequiredTakeoff)) : draft.postOverhaulRequiredTakeoff;
			const flightTime = hasCustomizedAircraftInfo ? (String(unit?.flightTime || "").trim() || draft.flightTime) : draft.flightTime;
			const remainingLife = String(unit?.remainingLife || "").trim() || computeAircraftRemainingLifeValue(postOverhaulRequiredLife, flightTime);
			const flightTakeoffCount = hasCustomizedAircraftInfo && Number.isFinite(Number(unit?.flightTakeoffCount)) ? Math.floor(Number(unit.flightTakeoffCount)) : draft.flightTakeoffCount;
			return {
				id: String(unit?.id || uid("acf")).trim() || uid("acf"),
				model: modelName,
				aircraftNo: String(unit?.aircraftNo || `${modelName}-${String(index + 1).padStart(3, "0")}`),
				initialFactoryNo: String(unit?.initialFactoryNo || `${modelName}-FAC-${String(2000 + index + 1).padStart(4, "0")}`),
				engineCount: Number(unit?.engineCount || (modelName.includes("直") || modelName.includes("KE") ? 2 : 2)),
				unitName: String(unit?.unitName || unit?.groupName || `舰载机第${(index % 3) + 1}分队`),
				supportOrganizationName: normalizeAircraftSupportOrganizationName(unit?.supportOrganizationName || unit?.supportOrgName || unit?.maintenanceOrganization || unit?.department || "", modelName),
				periodicUnitAssignments: normalizeShipborneAircraftPeriodicAssignments(unit?.periodicUnitAssignments),
				factoryDate: hasCustomizedAircraftInfo ? String(unit?.factoryDate || draft.factoryDate) : draft.factoryDate,
				overhaulCount: Number(unit?.overhaulCount || unit?.maintenanceCount || Math.floor(index / 4)),
				currentStatus,
				totalRequiredYears: parseAircraftYearsValue(totalRequiredYearsDisplay, 30),
				totalRequiredYearsDisplay,
				totalRequiredLife,
				totalRequiredTakeoff,
				totalFlightTime,
				totalTakeoffCount,
				overhaulFactoryDate: String(unit?.overhaulFactoryDate || draft.overhaulFactoryDate),
				postOverhaulRequiredYears,
				postOverhaulRequiredLife,
				postOverhaulRequiredTakeoff,
				flightTime,
				remainingLife,
				flightTakeoffCount,
				isOnboard: typeof unit?.isOnboard === "boolean" ? Boolean(unit.isOnboard) : currentStatus !== "停用",
				initialStationName: normalizeParkingStationName(unit?.initialStationName || unit?.initialPosition || ""),

				// Compatibility fields used by existing logic.
				lifeLimit: Math.floor(parseAircraftDurationValue(postOverhaulRequiredLife, parseAircraftDurationValue(draft.postOverhaulRequiredLife)) / 60),
				flightHours: Math.floor(parseAircraftDurationValue(flightTime, parseAircraftDurationValue(draft.flightTime)) / 60),
				takeoffLimit: postOverhaulRequiredTakeoff,
				takeoffCount: flightTakeoffCount,
				totalServiceLifeYears: parseAircraftYearsValue(totalRequiredYearsDisplay, 30),
				maintenanceCount: Number(unit?.maintenanceCount || 0),
				postMaintenanceRunHours: Number(unit?.postMaintenanceRunHours || 0),
				leftEngineWorkHours: Number(unit?.leftEngineWorkHours || 0),
				rightEngineWorkHours: Number(unit?.rightEngineWorkHours || 0),
				totalWorkHours: Math.floor(parseAircraftDurationValue(totalFlightTime, parseAircraftDurationValue(draft.totalFlightTime)) / 60),
				commissionedHours: Number(unit?.commissionedHours || 0)
			};
		});

	const fallbackCount = Math.max(1, Number(node.quantity) || 1);
	const rawRows = unitRows.length > 0 ? unitRows : Array.from({ length: fallbackCount }, (_, index) => createEquipmentAircraftInfoRow(modelName, index + 1));
	node.aircraftInfos = ensureUniqueAircraftInitialStationRows(rawRows);
	node.quantity = node.aircraftInfos.length;
	return node.aircraftInfos;
}

function getComprehensivePlanEquipmentOptions(tabKey) {
	if (tabKey === "ops_plan" || tabKey === "prev_repair") {
		return getEquipmentAircraftModelNames();
	}
	const plans = getComprehensivePlansByTab(tabKey);
	return Array.from(
		new Set(
			plans
				.map((plan) => getComprehensivePlanEquipmentName(tabKey, plan))
				.filter(Boolean)
		)
	);
}

function buildOpsPlanSchemesByModel(modelName, plans = []) {
	const normalizedModelName = String(modelName || "").trim();
	const modelPlans = (Array.isArray(plans) ? plans : []).filter(
		(plan) => String(getComprehensivePlanEquipmentName("ops_plan", plan) || "").trim() === normalizedModelName
	);
	const typedBuckets = Object.fromEntries(OPS_PLAN_TYPE_OPTIONS.map((type) => [type, []]));
	modelPlans.forEach((plan) => {
		const planType = String(plan?.draft?.planType || "").trim();
		if (!OPS_PLAN_TYPE_OPTIONS.includes(planType)) return;
		typedBuckets[planType].push(plan);
	});
	const schemeCount = OPS_PLAN_TYPE_OPTIONS.reduce((maxCount, type) => Math.max(maxCount, typedBuckets[type].length), 0);
	return Array.from({ length: schemeCount }, (_, index) => {
		const plansByType = Object.fromEntries(
			OPS_PLAN_TYPE_OPTIONS.map((type) => [type, typedBuckets[type][index] || null])
		);
		const allPlans = OPS_PLAN_TYPE_OPTIONS.map((type) => plansByType[type]).filter(Boolean);
		return {
			schemeNo: index + 1,
			schemeId: `${normalizedModelName}::scheme_${index + 1}`,
			plansByType,
			allPlans
		};
	}).filter((scheme) => scheme.allPlans.length > 0);
}

function appendOpsPlanSchemePlans(plans, modelName, schemeNo) {
	OPS_PLAN_TYPE_OPTIONS.forEach((planType) => {
		const nextDraft = createDefaultOpsPlanDraft();
		nextDraft.model = modelName;
		nextDraft.planType = planType;
		nextDraft.activityName = buildOpsPlanActivityNameByScheme(modelName, schemeNo, planType);
		plans.push({
			id: uid("ops_plan"),
			name: buildOpsPlanPlanNameByScheme(modelName, schemeNo, planType),
			draft: nextDraft
		});
	});
}

function ensureOpsPlanSchemesComplete(options = {}) {
	const ensureAtLeastTwoSchemes = options.ensureAtLeastTwoSchemes === true;
	const plans = state.ui?.comprehensivePlans?.ops_plan;
	if (!Array.isArray(plans) || plans.length === 0) return;
	const modelNames = Array.from(
		new Set(
			plans
				.map((plan) => String(getComprehensivePlanEquipmentName("ops_plan", plan) || "").trim())
				.filter(Boolean)
		)
	);
	modelNames.forEach((modelName) => {
		const schemes = buildOpsPlanSchemesByModel(modelName, plans);
		if (ensureAtLeastTwoSchemes && schemes.length < 2) {
			for (let schemeNo = schemes.length + 1; schemeNo <= 2; schemeNo += 1) {
				appendOpsPlanSchemePlans(plans, modelName, schemeNo);
			}
		}
		const latestSchemes = buildOpsPlanSchemesByModel(modelName, plans);
		latestSchemes.forEach((scheme) => {
			const schemeActivityName = resolveOpsPlanSchemeActivityName(scheme, modelName, scheme.schemeNo);
			(scheme.allPlans || []).forEach((plan) => {
				const planType = String(plan?.draft?.planType || "").trim();
				if (!OPS_PLAN_TYPE_OPTIONS.includes(planType)) return;
				plan.name = buildOpsPlanPlanNameByScheme(modelName, scheme.schemeNo, planType);
				if (plan?.draft && typeof plan.draft === "object") {
					plan.draft.model = modelName;
					plan.draft.planType = planType;
					plan.draft.activityName = schemeActivityName;
				}
			});
		});

		const refreshedSchemes = buildOpsPlanSchemesByModel(modelName, plans);
		refreshedSchemes.forEach((scheme) => {
			const schemeActivityName = resolveOpsPlanSchemeActivityName(scheme, modelName, scheme.schemeNo);
			OPS_PLAN_TYPE_OPTIONS.forEach((planType) => {
				if (scheme.plansByType?.[planType]) return;
				const nextDraft = createDefaultOpsPlanDraft();
				nextDraft.model = modelName;
				nextDraft.planType = planType;
				nextDraft.activityName = schemeActivityName;
				plans.push({
					id: uid("ops_plan"),
					name: buildOpsPlanPlanNameByScheme(modelName, scheme.schemeNo, planType),
					draft: nextDraft
				});
			});
		});
	});
}

function getOpsPlanSchemeByPlanId(planId) {
	const targetPlanId = String(planId || "").trim();
	if (!targetPlanId) return null;
	const allPlans = getComprehensivePlansByTab("ops_plan");
	const equipmentNames = Array.from(
		new Set(
			allPlans
				.map((plan) => String(getComprehensivePlanEquipmentName("ops_plan", plan) || "").trim())
				.filter(Boolean)
		)
	);
	for (const equipmentName of equipmentNames) {
		const schemes = buildOpsPlanSchemesByModel(equipmentName, allPlans);
		for (const scheme of schemes) {
			if (scheme.allPlans.some((plan) => String(plan?.id || "").trim() === targetPlanId)) {
				return { equipmentName, scheme };
			}
		}
	}
	return null;
}

function getOpsPlanPlanByTypeInScheme(scheme, planType) {
	if (!scheme || typeof scheme !== "object") return null;
	const normalizedType = String(planType || "").trim();
	if (normalizedType && OPS_PLAN_TYPE_OPTIONS.includes(normalizedType) && scheme.plansByType?.[normalizedType]) {
		return scheme.plansByType[normalizedType];
	}
	return Array.isArray(scheme.allPlans) && scheme.allPlans.length > 0 ? scheme.allPlans[0] : null;
}

function buildComprehensivePlanEquipmentGroups(tabKey) {
	const plans = getComprehensivePlansByTab(tabKey);
	if (tabKey === "ops_plan") {
		const equipmentNames = Array.from(
			new Set([
				...getEquipmentAircraftModelNames(),
				...plans
					.map((plan) => String(getComprehensivePlanEquipmentName(tabKey, plan) || "").trim())
					.filter(Boolean)
			])
		);
		return equipmentNames.map((equipmentName) => ({
			equipmentName,
			schemes: buildOpsPlanSchemesByModel(equipmentName, plans),
			plans: plans.filter((plan) => getComprehensivePlanEquipmentName(tabKey, plan) === equipmentName)
		}));
	}
	if (tabKey === "prev_repair") {
		return getEquipmentAircraftModelNames().map((equipmentName) => ({
			equipmentName,
			plans: plans.filter((plan) => getComprehensivePlanEquipmentName(tabKey, plan) === equipmentName)
		}));
	}
	const groupedPlans = new Map();
	const equipmentOptions = getComprehensivePlanEquipmentOptions(tabKey);
	equipmentOptions.forEach((equipmentName) => {
		groupedPlans.set(equipmentName, []);
	});
	plans.forEach((plan) => {
		const equipmentName = getComprehensivePlanEquipmentName(tabKey, plan);
		if (!groupedPlans.has(equipmentName)) {
			groupedPlans.set(equipmentName, []);
		}
		groupedPlans.get(equipmentName).push(plan);
	});
	return Array.from(groupedPlans.entries()).map(([equipmentName, children]) => ({
		equipmentName,
		plans: children
	}));
}

function createComprehensiveDraftByTab(tabKey, equipmentName) {
	if (tabKey === "ops_plan") {
		const draft = createDefaultOpsPlanDraft();
		draft.model = equipmentName || APP_CONFIG.modelTypes[0] || "";
		return draft;
	}
	if (tabKey === "prev_repair") {
		const draft = createDefaultPrevRepairDraft();
		draft.equipmentName = equipmentName || draft.equipmentName;
		return draft;
	}
	const draft = createDefaultCorrRepairDraft();
	draft.equipmentName = equipmentName || draft.equipmentName;
	return draft;
}

function suggestComprehensiveEquipmentName(tabKey, plans) {
	const usedNames = new Set(plans.map((plan) => getComprehensivePlanEquipmentName(tabKey, plan)));
	if (tabKey === "ops_plan") {
		const nextModel = APP_CONFIG.modelTypes.find((item) => !usedNames.has(item));
		return nextModel || APP_CONFIG.modelTypes[0] || "歼-35";
	}
	let index = 1;
	let candidate = `新增装备${index}`;
	while (usedNames.has(candidate)) {
		index += 1;
		candidate = `新增装备${index}`;
	}
	return candidate;
}

function buildComprehensivePlanName(tabKey, equipmentName, plans) {
	const namePrefixMap = {
		ops_plan: `${equipmentName}保障方案`,
		prev_repair: `${equipmentName}预防维修方案`,
		corr_repair: `${equipmentName}修复维修方案`
	};
	const prefix = namePrefixMap[tabKey] || `${equipmentName}保障方案`;
	const usedNames = new Set(plans.map((item) => String(item?.name || "").trim()));
	if (!usedNames.has(prefix)) return prefix;
	let index = 2;
	let candidate = `${prefix}-${index}`;
	while (usedNames.has(candidate)) {
		index += 1;
		candidate = `${prefix}-${index}`;
	}
	return candidate;
}

function addComprehensiveEquipment(tabKey) {
	const plans = getComprehensivePlansByTab(tabKey);
	const equipmentName = suggestComprehensiveEquipmentName(tabKey, plans);
	const nextDraft = createComprehensiveDraftByTab(tabKey, equipmentName);
	const nextPlanName = buildComprehensivePlanName(tabKey, equipmentName, plans);
	const nextPlan = {
		id: uid(`${tabKey}_plan`),
		name: nextPlanName,
		draft: nextDraft
	};
	plans.push(nextPlan);
	state.ui.comprehensiveActivePlanIds[tabKey] = nextPlan.id;
	clearComprehensiveJobSelection(tabKey);
	syncComprehensiveDraftPointers();
	return equipmentName;
}

function addComprehensivePlan(tabKey) {
	const plans = getComprehensivePlansByTab(tabKey);
	const availableEquipmentNames =
		tabKey === "ops_plan" || tabKey === "prev_repair"
			? getEquipmentAircraftModelNames()
			: getComprehensivePlanEquipmentOptions(tabKey);
	let equipmentName = String(state.ui.comprehensiveSelectedEquipmentNames?.[tabKey] || "").trim();
	if (!equipmentName) {
		equipmentName = availableEquipmentNames[0] || "";
	}
	if ((tabKey === "ops_plan" || tabKey === "prev_repair") && (!equipmentName || !availableEquipmentNames.includes(equipmentName))) {
		return { planName: "", equipmentName: "", error: "请先在左侧选择飞机机型名称" };
	}
	if (!equipmentName && plans.length) {
		const activePlan = getActiveComprehensivePlan(tabKey) || plans[0];
		equipmentName = getComprehensivePlanEquipmentName(tabKey, activePlan);
	}
	if (!equipmentName) {
		equipmentName = suggestComprehensiveEquipmentName(tabKey, plans);
	}
	if (tabKey === "ops_plan") {
		const schemes = buildOpsPlanSchemesByModel(equipmentName, plans);
		const nextSchemeNo = schemes.length + 1;
		const currentPlanType = String(state.ui.opsPlanDraft?.planType || OPS_PLAN_TYPE_OPTIONS[0]).trim();
		let nextActivePlanId = "";
		OPS_PLAN_TYPE_OPTIONS.forEach((planType) => {
			const nextDraft = createDefaultOpsPlanDraft();
			nextDraft.model = equipmentName;
			nextDraft.planType = planType;
			nextDraft.activityName = buildOpsPlanActivityNameByScheme(equipmentName, nextSchemeNo, planType);
			const nextPlan = {
				id: uid(`${tabKey}_plan`),
				name: buildOpsPlanPlanNameByScheme(equipmentName, nextSchemeNo, planType),
				draft: nextDraft
			};
			plans.push(nextPlan);
			if (!nextActivePlanId || planType === currentPlanType) {
				nextActivePlanId = nextPlan.id;
			}
		});
		state.ui.comprehensiveActivePlanIds[tabKey] = nextActivePlanId;
		clearComprehensiveJobSelection(tabKey);
		if (!state.ui.comprehensiveSelectedEquipmentNames || typeof state.ui.comprehensiveSelectedEquipmentNames !== "object") {
			state.ui.comprehensiveSelectedEquipmentNames = {};
		}
		state.ui.comprehensiveSelectedEquipmentNames[tabKey] = equipmentName;
		syncComprehensiveDraftPointers();
		return { planName: buildOpsPlanSchemeDisplayName(equipmentName, nextSchemeNo), equipmentName };
	}
	const nextDraft = createComprehensiveDraftByTab(tabKey, equipmentName);
	const nextPlanName = buildComprehensivePlanName(tabKey, equipmentName, plans);
	const nextPlan = {
		id: uid(`${tabKey}_plan`),
		name: nextPlanName,
		draft: nextDraft
	};
	plans.push(nextPlan);
	state.ui.comprehensiveActivePlanIds[tabKey] = nextPlan.id;
	clearComprehensiveJobSelection(tabKey);
	if (!state.ui.comprehensiveSelectedEquipmentNames || typeof state.ui.comprehensiveSelectedEquipmentNames !== "object") {
		state.ui.comprehensiveSelectedEquipmentNames = {};
	}
	state.ui.comprehensiveSelectedEquipmentNames[tabKey] = equipmentName;
	syncComprehensiveDraftPointers();
	return { planName: nextPlanName, equipmentName };
}

function removeComprehensiveEquipment(tabKey) {
	const plans = getComprehensivePlansByTab(tabKey);
	if (plans.length === 0) {
		return { removedCount: 0, equipmentName: "" };
	}
	const activePlan = getActiveComprehensivePlan(tabKey) || plans[0];
	const equipmentName = getComprehensivePlanEquipmentName(tabKey, activePlan);
	const nextPlans = plans.filter((item) => getComprehensivePlanEquipmentName(tabKey, item) !== equipmentName);
	const removedCount = plans.length - nextPlans.length;
	if (removedCount <= 0 || nextPlans.length === 0) {
		return { removedCount: 0, equipmentName };
	}
	state.ui.comprehensivePlans[tabKey] = nextPlans;
	state.ui.comprehensiveActivePlanIds[tabKey] = nextPlans[0]?.id || "";
	clearComprehensiveJobSelection(tabKey);
	syncComprehensiveDraftPointers();
	return { removedCount, equipmentName };
}

function removeComprehensivePlan(tabKey) {
	const plans = getComprehensivePlansByTab(tabKey);
	if (plans.length <= 1) {
		return { removed: false, planName: "", reason: "at-least-one" };
	}
	if (tabKey === "ops_plan") {
		const allGroups = buildComprehensivePlanEquipmentGroups("ops_plan");
		const allSchemes = allGroups.flatMap((group) => group.schemes || []);
		if (allSchemes.length <= 1) {
			return { removed: false, planName: "", reason: "at-least-one" };
		}
		const activePlan = getActiveComprehensivePlan(tabKey) || plans[0] || null;
		const activeSchemeInfo = getOpsPlanSchemeByPlanId(activePlan?.id || "");
		if (!activeSchemeInfo?.scheme) {
			return { removed: false, planName: "", reason: "not-found" };
		}
		const removePlanIdSet = new Set((activeSchemeInfo.scheme.allPlans || []).map((plan) => plan.id));
		const nextPlans = plans.filter((plan) => !removePlanIdSet.has(plan.id));
		if (nextPlans.length === 0) {
			return { removed: false, planName: "", reason: "at-least-one" };
		}
		state.ui.comprehensivePlans[tabKey] = nextPlans;
		const nextGroups = buildComprehensivePlanEquipmentGroups("ops_plan");
		const targetGroup = nextGroups.find((group) => group.equipmentName === activeSchemeInfo.equipmentName && (group.schemes || []).length > 0)
			|| nextGroups.find((group) => (group.schemes || []).length > 0)
			|| null;
		const nextScheme = targetGroup?.schemes?.[0] || null;
		const preferredType = String(state.ui.opsPlanDraft?.planType || OPS_PLAN_TYPE_OPTIONS[0]).trim();
		const nextActivePlan = getOpsPlanPlanByTypeInScheme(nextScheme, preferredType) || nextPlans[0] || null;
		state.ui.comprehensiveActivePlanIds[tabKey] = nextActivePlan?.id || "";
		if (!state.ui.comprehensiveSelectedEquipmentNames || typeof state.ui.comprehensiveSelectedEquipmentNames !== "object") {
			state.ui.comprehensiveSelectedEquipmentNames = {};
		}
		state.ui.comprehensiveSelectedEquipmentNames[tabKey] = String(targetGroup?.equipmentName || getComprehensivePlanEquipmentName(tabKey, nextActivePlan) || "").trim();
		clearComprehensiveJobSelection(tabKey);
		syncComprehensiveDraftPointers();
		return {
			removed: true,
			planName: buildOpsPlanSchemeDisplayName(activeSchemeInfo.equipmentName, activeSchemeInfo.scheme.schemeNo),
			reason: ""
		};
	}
	const activePlan = getActiveComprehensivePlan(tabKey) || plans[0];
	if (!activePlan) {
		return { removed: false, planName: "", reason: "not-found" };
	}
	const nextPlans = plans.filter((item) => item.id !== activePlan.id);
	if (!nextPlans.length) {
		return { removed: false, planName: activePlan.name || "", reason: "at-least-one" };
	}
	state.ui.comprehensivePlans[tabKey] = nextPlans;
	state.ui.comprehensiveActivePlanIds[tabKey] = nextPlans[0]?.id || "";
	clearComprehensiveJobSelection(tabKey);
	syncComprehensiveDraftPointers();
	return { removed: true, planName: activePlan.name || "", reason: "" };
}

function ensureComprehensiveJobSelectedState() {
	if (!state.ui.comprehensiveSelectedJobNames || typeof state.ui.comprehensiveSelectedJobNames !== "object") {
		state.ui.comprehensiveSelectedJobNames = {
			ops_plan: [],
			prev_repair: [],
			corr_repair: []
		};
	}
	["ops_plan", "prev_repair", "corr_repair"].forEach((tabKey) => {
		if (!Array.isArray(state.ui.comprehensiveSelectedJobNames[tabKey])) {
			state.ui.comprehensiveSelectedJobNames[tabKey] = [];
		}
		const draft = getComprehensiveDraftByTab(tabKey);
		const validNames = new Set((draft.selectedJobs || []).map((name) => String(name || "").trim()).filter(Boolean));
		state.ui.comprehensiveSelectedJobNames[tabKey] = state.ui.comprehensiveSelectedJobNames[tabKey].filter((name) => validNames.has(String(name || "").trim()));
	});
	return state.ui.comprehensiveSelectedJobNames;
}

function clearComprehensiveJobSelection(tabKey) {
	ensureComprehensiveJobSelectedState();
	if (["ops_plan", "prev_repair", "corr_repair"].includes(tabKey)) {
		state.ui.comprehensiveSelectedJobNames[tabKey] = [];
		return;
	}
	state.ui.comprehensiveSelectedJobNames = {
		ops_plan: [],
		prev_repair: [],
		corr_repair: []
	};
}

function removeComprehensiveJobs(tabKey, jobNamesSet) {
	if (!jobNamesSet || jobNamesSet.size === 0) return 0;
	const draft = getComprehensiveDraftByTab(tabKey);
	const removedJobNames = draft.selectedJobs.filter((name) => jobNamesSet.has(name));
	if (removedJobNames.length === 0) return 0;
	const { codeByJobName } = getComprehensiveJobCodeMaps(tabKey, draft);
	const removedCodes = new Set(removedJobNames.map((name) => codeByJobName.get(name)).filter(Boolean));
	draft.selectedJobs = draft.selectedJobs.filter((name) => !jobNamesSet.has(name));
	Object.keys(draft.jobs || {}).forEach((name) => {
		if (jobNamesSet.has(name)) {
			delete draft.jobs[name];
			return;
		}
		draft.jobs[name].predecessors = (draft.jobs[name].predecessors || []).filter((prev) => !jobNamesSet.has(prev));
		draft.jobs[name].predecessorCodes = (draft.jobs[name].predecessorCodes || []).filter((code) => !removedCodes.has(code));
	});
	ensureComprehensiveJobSelectedState();
	state.ui.comprehensiveSelectedJobNames[tabKey] = (state.ui.comprehensiveSelectedJobNames[tabKey] || []).filter((name) => !jobNamesSet.has(name));
	return removedJobNames.length;
}

function buildComprehensiveGroupCollapseKey(tabKey, equipmentName) {
	return `${String(tabKey || "").trim()}::${String(equipmentName || "").trim()}`;
}

function ensureComprehensivePlanTreeUiState(tabKey, groups = []) {
	if (!state.ui || typeof state.ui !== "object") {
		state.ui = {};
	}
	if (!Array.isArray(state.ui.collapsedComprehensiveRootTabs)) {
		state.ui.collapsedComprehensiveRootTabs = [];
	}
	if (!Array.isArray(state.ui.collapsedComprehensiveGroupKeys)) {
		state.ui.collapsedComprehensiveGroupKeys = [];
	}
	const tabPrefix = `${String(tabKey || "").trim()}::`;
	const validKeys = new Set(groups.map((group) => buildComprehensiveGroupCollapseKey(tabKey, group.equipmentName)));
	state.ui.collapsedComprehensiveGroupKeys = state.ui.collapsedComprehensiveGroupKeys.filter((key) => {
		if (!String(key || "").startsWith(tabPrefix)) return true;
		return validKeys.has(String(key || ""));
	});
}

function getComprehensivePlanTreeChildLabel(tabKey, plan) {
	const draft = plan?.draft || {};
	if (tabKey === "prev_repair") {
		return String(draft.preventiveMaintenanceName || "").trim() || String(plan?.name || "").trim() || "未命名预防性维修活动";
	}
	return String(plan?.name || "").trim() || "未命名方案";
}

function renderComprehensivePlanTree(tabKey, activePlan) {
	const groups = buildComprehensivePlanEquipmentGroups(tabKey);
	ensureComprehensivePlanTreeUiState(tabKey, groups);
	const collapsedSet = new Set(state.ui.collapsedComprehensiveGroupKeys || []);
	const selectedEquipmentName = String(state.ui.comprehensiveSelectedEquipmentNames?.[tabKey] === undefined ? (getComprehensivePlanEquipmentName(tabKey, activePlan) || "") : state.ui.comprehensiveSelectedEquipmentNames[tabKey]).trim();
	const rootSelected = selectedEquipmentName === "";
	const rootCollapsedTabs = new Set((state.ui.collapsedComprehensiveRootTabs || []).map((item) => String(item || "").trim()).filter(Boolean));
	const isRootCollapsed = rootCollapsedTabs.has(String(tabKey || "").trim());
	if (groups.length === 0) {
		return "<div class='muted'>暂无保障方案</div>";
	}
	const activeSchemeInfo = tabKey === "ops_plan" ? getOpsPlanSchemeByPlanId(activePlan?.id || "") : null;
	const groupNodes = groups
		.map((group) => {
			const childItems = tabKey === "ops_plan" ? (group.schemes || []) : (group.plans || []);
			const hasChildren = Array.isArray(childItems) && childItems.length > 0;
			const isGroupSelected = !rootSelected && (selectedEquipmentName === group.equipmentName || childItems.some((item) => (tabKey === "ops_plan" ? (item.allPlans || []).some((plan) => plan.id === activePlan?.id) : item.id === activePlan?.id)));
			const collapseKey = buildComprehensiveGroupCollapseKey(tabKey, group.equipmentName);
			const isCollapsed = hasChildren ? collapsedSet.has(collapseKey) : false;
			const toggleSymbol = hasChildren ? (isCollapsed ? "▶" : "▼") : "•";
			const childrenHtml = tabKey === "ops_plan"
				? childItems
					.map((scheme) => {
						const isSchemeSelected = !rootSelected
							&& activeSchemeInfo?.equipmentName === group.equipmentName
							&& Number(activeSchemeInfo?.scheme?.schemeNo || 0) === Number(scheme.schemeNo || 0);
						const schemeDisplayName = resolveOpsPlanSchemeDisplayName(
							scheme,
							group.equipmentName,
							Number(scheme.schemeNo || 1),
							state.ui.opsPlanDraft?.planType
						);
						return `
							<div class="tree-node-item">
								<div class="tree-node-label ${isSchemeSelected ? "selected" : ""}" data-action="select-ops-plan-scheme" data-tab="${tabKey}" data-equipment="${htmlEscape(group.equipmentName)}" data-scheme-no="${Number(scheme.schemeNo || 1)}">
									<span class="tree-node-toggle">•</span>
									<span class="tree-node-text">${htmlEscape(schemeDisplayName)}</span>
								</div>
							</div>
						`;
					})
					.join("")
				: childItems
					.map(
						(item, index) => `
							<div class="tree-node-item">
								<div class="tree-node-label ${!rootSelected && activePlan?.id === item.id ? "selected" : ""}" data-action="select-comprehensive-plan" data-tab="${tabKey}" data-plan-id="${item.id}">
									<span class="tree-node-toggle">•</span>
									<span class="tree-node-text">${htmlEscape(tabKey === "ops_plan" ? `保障方案${index + 1}` : getComprehensivePlanTreeChildLabel(tabKey, item))}</span>
								</div>
							</div>
						`
					)
					.join("");
			return `
				<div class="tree-node-item">
					<div class="tree-node-label ${isGroupSelected ? "selected" : ""}" data-action="select-comprehensive-equipment" data-tab="${tabKey}" data-equipment="${htmlEscape(group.equipmentName)}">
						<span class="tree-node-toggle" ${hasChildren ? `data-action="toggle-comprehensive-group" data-tab="${tabKey}" data-equipment="${htmlEscape(group.equipmentName)}"` : ""}>${toggleSymbol}</span>
						<span class="tree-node-text">${htmlEscape(group.equipmentName)}</span>
					</div>
					${
						hasChildren && !isCollapsed
							? `<div class="tree-node-children">
						${childrenHtml}
					</div>`
							: ""
					}
				</div>
			`;
		})
		.join("");

	return `
		<div class="tree-node-item">
			<div class="tree-node-label ${rootSelected ? "selected" : ""}" data-action="select-comprehensive-root" data-tab="${tabKey}">
				<span class="tree-node-toggle" data-action="toggle-comprehensive-root" data-tab="${tabKey}">${isRootCollapsed ? "▶" : "▼"}</span>
				<span class="tree-node-text">${tabKey === "ops_plan" ? "使用保障活动列表" : "飞机列表"}</span>
			</div>
			${isRootCollapsed ? "" : `<div class="tree-node-children">${groupNodes}</div>`}
		</div>
	`;
}

function syncBasicOpsDerivedCache() {
	BASIC_OPS_WORK_NAMES.length = 0;
	BASIC_OPS_ACTIVITIES.forEach((item) => {
		BASIC_OPS_WORK_NAMES.push(item.workName);
	});
	Object.keys(BASIC_OPS_DURATION_MAP).forEach((workName) => {
		delete BASIC_OPS_DURATION_MAP[workName];
	});
	BASIC_OPS_ACTIVITIES.forEach((item) => {
		BASIC_OPS_DURATION_MAP[item.workName] = Number(item.duration) > 0 ? Number(item.duration) : 10;
	});
}

function syncBasicOpsBaselineFromCurrent() {
	BASIC_OPS_BASELINE_ACTIVITIES.length = 0;
	BASIC_OPS_ACTIVITIES.forEach((item) => {
		BASIC_OPS_BASELINE_ACTIVITIES.push(cloneBasicActivityItem("basic_ops", item));
	});
}

function syncBasicRepairDerivedCache() {
	BASIC_REPAIR_WORK_NAMES.length = 0;
	BASIC_REPAIR_ACTIVITIES.forEach((item) => {
		BASIC_REPAIR_WORK_NAMES.push(item.workName);
	});
	Object.keys(BASIC_REPAIR_DURATION_MAP).forEach((workName) => {
		delete BASIC_REPAIR_DURATION_MAP[workName];
	});
	BASIC_REPAIR_ACTIVITIES.forEach((item) => {
		BASIC_REPAIR_DURATION_MAP[item.workName] = Number(item.duration) > 0 ? Number(item.duration) : 10;
	});
}

function getBasicOpsActivityOptions() {
	return Array.from(
		new Set(
			BASIC_OPS_ACTIVITIES
				.map((item) => String(item.workName || "").trim())
				.filter(Boolean)
		)
	);
}

function isRepairTargetMatched(target, query) {
	const targetText = String(target || "").trim().toLowerCase();
	const queryText = String(query || "").trim().toLowerCase();
	if (!targetText || !queryText) return false;
	return targetText === queryText || targetText.includes(queryText) || queryText.includes(targetText);
}

function getBasicRepairActivityOptionsByTarget(target) {
	const queryText = String(target || "").trim();
	const scoped = queryText
		? BASIC_REPAIR_ACTIVITIES.filter((item) => isRepairTargetMatched(item.target, queryText))
		: BASIC_REPAIR_ACTIVITIES;
	const source = scoped.length > 0 ? scoped : BASIC_REPAIR_ACTIVITIES;
	return Array.from(
		new Set(
			source
				.map((item) => String(item.workName || "").trim())
				.filter(Boolean)
		)
	);
}

function createComprehensiveJobConfig(duration = 10, predecessors = [], durationProfile = null, predecessorCodes = []) {
	const safeDuration = Number(duration) > 0 ? Number(duration) : 10;
	return {
		duration: safeDuration,
		predecessors: Array.isArray(predecessors) ? predecessors.filter(Boolean) : [],
		predecessorCodes: Array.isArray(predecessorCodes) ? predecessorCodes.filter(Boolean) : [],
		durationProfile: cloneActivityDurationProfile(durationProfile, safeDuration),
		supportOrganizations: []
	};
}

const BASIC_ACTIVITY_LIBRARY_TYPE_OPTIONS = [
	{ key: "ops_plan", label: "使用保障活动", activityType: "basic_ops" },
	{ key: "prev_repair", label: "预防性维修活动", activityType: "basic_repair" },
	{ key: "corr_repair", label: "修复性维修活动", activityType: "basic_repair" }
];

function getBasicActivityLibraryTypeMeta(typeKey, fallbackActivityType = "basic_ops") {
	const normalizedKey = String(typeKey || "").trim();
	const matched = BASIC_ACTIVITY_LIBRARY_TYPE_OPTIONS.find((item) => item.key === normalizedKey);
	if (matched) return matched;
	if (fallbackActivityType === "basic_repair") {
		return BASIC_ACTIVITY_LIBRARY_TYPE_OPTIONS.find((item) => item.key === "prev_repair") || BASIC_ACTIVITY_LIBRARY_TYPE_OPTIONS[1];
	}
	return BASIC_ACTIVITY_LIBRARY_TYPE_OPTIONS.find((item) => item.key === "ops_plan") || BASIC_ACTIVITY_LIBRARY_TYPE_OPTIONS[0];
}

function parsePredecessorCodesString(value) {
	return Array.from(
		new Set(
			String(value || "")
				.split(/[，,、;；\s]+/)
				.map((item) => String(item || "").trim())
				.filter(Boolean)
		)
	);
}

function getComprehensiveJobCodeMaps(tabKey, draft) {
	const jobNameByCode = new Map();
	const codeByJobName = new Map();
	(draft?.selectedJobs || []).forEach((jobName) => {
		const sourceActivity = getComprehensiveJobSourceActivity(tabKey, jobName, draft) || {};
		const activityType = getComprehensiveJobActivityType(tabKey);
		const scopedItem = createBasicActivityDraft(activityType, sourceActivity);
		const activityCode = String(scopedItem.activityCode || "").trim();
		if (!activityCode) return;
		jobNameByCode.set(activityCode, jobName);
		codeByJobName.set(jobName, activityCode);
	});
	return { jobNameByCode, codeByJobName };
}

function resolveComprehensiveJobPredecessorCodes(tabKey, draft, jobName, rowConfig = {}) {
	const explicitCodes = parsePredecessorCodesString((rowConfig.predecessorCodes || []).join("，"));
	if (explicitCodes.length > 0) {
		const { jobNameByCode } = getComprehensiveJobCodeMaps(tabKey, draft);
		return explicitCodes.filter((code) => {
			const mappedJobName = jobNameByCode.get(code);
			return Boolean(mappedJobName && mappedJobName !== jobName);
		});
	}
	const { codeByJobName } = getComprehensiveJobCodeMaps(tabKey, draft);
	return Array.from(
		new Set(
			(rowConfig.predecessors || [])
				.map((name) => codeByJobName.get(name))
				.filter((code) => Boolean(code))
		)
	);
}

function resolveComprehensiveJobPredecessorNames(tabKey, draft, jobName, predecessorCodes = [], rowConfig = {}) {
	const { jobNameByCode } = getComprehensiveJobCodeMaps(tabKey, draft);
	const resolvedNames = predecessorCodes
		.map((code) => jobNameByCode.get(code))
		.filter((name) => Boolean(name) && name !== jobName);
	if (resolvedNames.length > 0) {
		return Array.from(new Set(resolvedNames));
	}
	return Array.from(new Set((rowConfig.predecessors || []).filter((name) => Boolean(name) && name !== jobName && (draft.selectedJobs || []).includes(name))));
}

function getComprehensiveJobPredecessorCodes(tabKey, draft, jobName) {
	const rowConfig = draft?.jobs?.[jobName] || {};
	return resolveComprehensiveJobPredecessorCodes(tabKey, draft, jobName, rowConfig);
}

function renderComprehensiveJobPredecessorCell(tabKey, draft, jobName, rowConfig) {
	const predecessorCodes = getComprehensiveJobPredecessorCodes(tabKey, draft, jobName);
	const badges = predecessorCodes.length > 0
		? predecessorCodes.map((code) => `<span class="badge" style="margin-right:4px;">${htmlEscape(code)}</span>`).join("")
		: "-";
	return `<div style="display:flex;align-items:center;justify-content:space-between;gap:8px;"><div style="flex:1;min-width:0;">${badges}</div><button type="button" class="inline-edit-btn btn-primary" data-action="open-predecessor-edit" data-tab="${tabKey}" data-job="${htmlEscape(jobName)}">编辑紧前作业</button></div>`;
}

function normalizeComprehensiveSupportOrganizations(values = []) {
	if (!Array.isArray(values)) return [];
	const visited = new Set();
	return values
		.map((item) => String(item || "").trim())
		.filter((name) => {
			if (!name || visited.has(name)) return false;
			visited.add(name);
			return true;
		});
}

function parseResourceNeedCount(rawValue) {
	const normalized = Number(String(rawValue || "").trim());
	if (Number.isFinite(normalized) && normalized > 0) return normalized;
	return 1;
}

function getOrganizationResourceRowsByKey(tableKey) {
	if (tableKey === "personnel") return Array.isArray(state.organizationResources?.personnel) ? state.organizationResources.personnel : ORG_PERSONNEL_MODELS;
	if (tableKey === "equipment") return Array.isArray(state.organizationResources?.equipment) ? state.organizationResources.equipment : ORG_EQUIPMENT_MODELS;
	if (tableKey === "ammunition") return Array.isArray(state.organizationResources?.ammunition) ? state.organizationResources.ammunition : ORG_AMMUNITION_MODELS;
	if (tableKey === "spare") return Array.isArray(state.organizationResources?.spare) ? state.organizationResources.spare : ORG_SPARE_MODELS;
	return [];
}

function getAllSupportOrganizationDepartments() {
	const names = new Set();
	["personnel", "equipment", "ammunition", "spare"].forEach((tableKey) => {
		getOrganizationResourceRowsByKey(tableKey).forEach((row) => {
			const departmentName = String(row?.department || "").trim();
			if (departmentName) names.add(departmentName);
		});
	});
	return Array.from(names);
}

function doesDepartmentMatchResourceNeed(departmentName, need, tableKey) {
	const normalizedDepartment = String(departmentName || "").trim();
	if (!normalizedDepartment) return false;
	const needName = String(need?.name || "").trim();
	const needModel = String(need?.model || "").trim();
	const requiredCount = parseResourceNeedCount(need?.count);
	if (!needName && !needModel) return true;
	const matchedRows = getOrganizationResourceRowsByKey(tableKey).filter((row) => {
		const rowDepartment = String(row?.department || "").trim();
		if (rowDepartment !== normalizedDepartment) return false;
		const rowName = String(row?.name || "").trim();
		const rowModel = String(row?.model || "").trim();
		if (needName && rowName === needName) return true;
		if (needModel && rowModel === needModel) return true;
		return false;
	});
	if (matchedRows.length === 0) return false;
	const totalCount = matchedRows.reduce((sum, row) => {
		const count = Number(row?.count ?? row?.demandCount ?? 0);
		return sum + (Number.isFinite(count) && count >= 0 ? count : 0);
	}, 0);
	return totalCount >= requiredCount;
}

function getDepartmentResourceAvailableCount(departmentName, need, tableKey) {
	const normalizedDepartment = String(departmentName || "").trim();
	if (!normalizedDepartment) return 0;
	const needName = String(need?.name || "").trim();
	const needModel = String(need?.model || "").trim();
	if (!needName && !needModel) return 0;
	return getOrganizationResourceRowsByKey(tableKey)
		.filter((row) => {
			const rowDepartment = String(row?.department || "").trim();
			if (rowDepartment !== normalizedDepartment) return false;
			const rowName = String(row?.name || "").trim();
			const rowModel = String(row?.model || "").trim();
			if (needName && rowName === needName) return true;
			if (needModel && rowModel === needModel) return true;
			return false;
		})
		.reduce((sum, row) => {
			const count = Number(row?.count ?? row?.demandCount ?? 0);
			return sum + (Number.isFinite(count) && count >= 0 ? count : 0);
		}, 0);
}

function getDepartmentPersonnelNeedDetails(departmentName, personnelRows) {
	const normalizedDepartment = String(departmentName || "").trim();
	if (!normalizedDepartment) return ["组织名称为空"];
	if (!Array.isArray(personnelRows) || personnelRows.length === 0) return [];
	const needMap = new Map();
	personnelRows.forEach((row) => {
		const major = String(row?.major || "").trim();
		const level = String(row?.level || "L1").trim() || "L1";
		if (!major || !level) return;
		const key = `${major}__${level}`;
		needMap.set(key, (needMap.get(key) || 0) + parseResourceNeedCount(row?.count));
	});
	return Array.from(needMap.entries())
		.map(([key, requiredCount]) => {
			const [major, level] = key.split("__");
			const availableCount = getPersonnelAvailableCount(normalizedDepartment, major, level);
			return availableCount >= requiredCount ? "" : `人员 ${major}/${level} 需 ${requiredCount}，现有 ${availableCount}`;
		})
		.filter(Boolean);
}

function getDepartmentResourceNeedDetails(departmentName, needs, tableKey, label) {
	const normalizedDepartment = String(departmentName || "").trim();
	if (!normalizedDepartment) return ["组织名称为空"];
	if (!Array.isArray(needs) || needs.length === 0) return [];
	return needs
		.map((need) => {
			const requiredCount = parseResourceNeedCount(need?.count);
			const availableCount = getDepartmentResourceAvailableCount(normalizedDepartment, need, tableKey);
			if (availableCount >= requiredCount) return "";
			const needLabel = String(need?.name || need?.model || "未命名").trim();
			return `${label} ${needLabel} 需 ${requiredCount}，现有 ${availableCount}`;
		})
		.filter(Boolean);
}

function doesDepartmentMatchPersonnelNeed(departmentName, personnelRows) {
	const normalizedDepartment = String(departmentName || "").trim();
	if (!normalizedDepartment) return false;
	if (!Array.isArray(personnelRows) || personnelRows.length === 0) return true;
	const fixedDepartmentRows = personnelRows.filter((row) => String(row?.department || "").trim());
	if (fixedDepartmentRows.length > 0 && !fixedDepartmentRows.every((row) => String(row?.department || "").trim() === normalizedDepartment)) {
		return false;
	}
	const needMap = new Map();
	personnelRows.forEach((row) => {
		const major = String(row?.major || "").trim();
		const level = String(row?.level || "L1").trim() || "L1";
		if (!major || !level) return;
		const key = `${major}__${level}`;
		needMap.set(key, (needMap.get(key) || 0) + parseResourceNeedCount(row?.count));
	});
	for (const [key, requiredCount] of needMap.entries()) {
		const [major, level] = key.split("__");
		const availableCount = getOrganizationResourceRowsByKey("personnel")
			.filter((row) => {
				const rowDepartment = String(row?.department || "").trim();
				const rowMajor = String(row?.major || "").trim();
				const rowLevel = String(row?.level || "").trim();
				return rowDepartment === normalizedDepartment && rowMajor === major && rowLevel === level;
			})
			.reduce((sum, row) => {
				const count = Number(row?.count || 0);
				return sum + (Number.isFinite(count) && count >= 0 ? count : 0);
			}, 0);
		if (availableCount < requiredCount) return false;
	}
	return true;
}

function getAvailableSupportOrganizationsByOpsJobName(jobName) {
	ensureOrgResourceModelState();
	const matchedActivity = getBasicOpsActivityByJobName(jobName);
	if (!matchedActivity) {
		return { organizations: [], reason: "未找到该作业对应的基本保障活动。" };
	}
	const personnelNeeds = parsePersonnelString(matchedActivity.personnel || "");
	const equipmentNeeds = parseEquipmentString(matchedActivity.equipment || "");
	const ammunitionNeeds = parseAmmunitionString(matchedActivity.ammunition || "");
	const spareNeeds = parseSpareString(matchedActivity.spare || "");
	const departments = getAllSupportOrganizationDepartments();
	const available = departments.filter((departmentName) => {
		if (!doesDepartmentMatchPersonnelNeed(departmentName, personnelNeeds)) return false;
		if (!equipmentNeeds.every((need) => doesDepartmentMatchResourceNeed(departmentName, need, "equipment"))) return false;
		if (!ammunitionNeeds.every((need) => doesDepartmentMatchResourceNeed(departmentName, need, "ammunition"))) return false;
		if (!spareNeeds.every((need) => doesDepartmentMatchResourceNeed(departmentName, need, "spare"))) return false;
		return true;
	});
	const reason = available.length === 0 ? "未筛选到同时满足保障人员、保障设备、弹药和备件需求的组织。" : "";
	return { organizations: available, reason };
}

function renderOpsJobSupportOrganizationOptions(options = [], selectedValues = []) {
	const normalizedOptions = normalizeComprehensiveSupportOrganizations(options);
	const selectedSet = new Set(normalizeComprehensiveSupportOrganizations(selectedValues));
	if (normalizedOptions.length === 0) {
		return `<span class="muted">暂无可选保障组织，请点击“筛选可用保障组织”。</span>`;
	}
	return normalizedOptions
		.map((name) => `<label style="display:inline-flex;align-items:center;gap:6px;padding:6px 10px;border:1px solid var(--line);border-radius:8px;background:#fff;"><input type="checkbox" style="width:auto;" data-role="ops-job-support-org" value="${htmlEscape(name)}" ${selectedSet.has(name) ? "checked" : ""}/><span>${htmlEscape(name)}</span></label>`)
		.join("");
}

function aggregateResourceNeedRows(rows = []) {
	const map = new Map();
	(rows || []).forEach((row) => {
		const name = String(row?.name || "").trim();
		const model = String(row?.model || "").trim();
		const key = `${name}__${model}`;
		if (!name && !model) return;
		const previous = map.get(key) || { name, model, count: 0 };
		previous.count += parseResourceNeedCount(row?.count);
		map.set(key, previous);
	});
	return Array.from(map.values());
}

function getAvailableSupportOrganizationsByOpsPlanDraft(draft) {
	ensureOrgResourceModelState();
	const selectedJobs = Array.isArray(draft?.selectedJobs) ? draft.selectedJobs.map((item) => String(item || "").trim()).filter(Boolean) : [];
	if (selectedJobs.length === 0) {
		return { organizations: [], reason: "当前无工作项目清单作业项。" };
	}
	const allPersonnelNeeds = [];
	const allEquipmentNeeds = [];
	const allAmmunitionNeeds = [];
	const allSpareNeeds = [];
	const missingJobs = [];
	selectedJobs.forEach((jobName) => {
		const matchedActivity = getBasicOpsActivityByJobName(jobName);
		if (!matchedActivity) {
			missingJobs.push(jobName);
			return;
		}
		allPersonnelNeeds.push(...parsePersonnelString(matchedActivity.personnel || ""));
		allEquipmentNeeds.push(...parseEquipmentString(matchedActivity.equipment || ""));
		allAmmunitionNeeds.push(...parseAmmunitionString(matchedActivity.ammunition || ""));
		allSpareNeeds.push(...parseSpareString(matchedActivity.spare || ""));
	});
	if (allPersonnelNeeds.length === 0 && allEquipmentNeeds.length === 0 && allAmmunitionNeeds.length === 0 && allSpareNeeds.length === 0) {
		return { organizations: [], reason: missingJobs.length > 0 ? `以下作业未匹配到基本保障活动：${missingJobs.join("、")}` : "当前作业未产生保障资源需求。" };
	}
	const aggregatedEquipmentNeeds = aggregateResourceNeedRows(allEquipmentNeeds);
	const aggregatedAmmunitionNeeds = aggregateResourceNeedRows(allAmmunitionNeeds);
	const aggregatedSpareNeeds = aggregateResourceNeedRows(allSpareNeeds);
	const candidateDepartments = getAirWingSupportCandidateDepartments();
	const diagnostics = candidateDepartments.map((departmentName) => {
		const failures = [
			...getDepartmentPersonnelNeedDetails(departmentName, allPersonnelNeeds).map((text) => `人员不足：${text}`),
			...getDepartmentResourceNeedDetails(departmentName, aggregatedEquipmentNeeds, "equipment", "设备").map((text) => `设备不足：${text}`),
			...getDepartmentResourceNeedDetails(departmentName, aggregatedAmmunitionNeeds, "ammunition", "弹药").map((text) => `弹药不足：${text}`),
			...getDepartmentResourceNeedDetails(departmentName, aggregatedSpareNeeds, "spare", "备件").map((text) => `备件不足：${text}`)
		];
		return {
			departmentName,
			passed: failures.length === 0,
			failures
		};
	});
	const organizations = diagnostics.filter((item) => item.passed).map((item) => item.departmentName);
	const baseReason = organizations.length === 0 ? "未筛选到可同时满足当前全部工作项目清单资源需求的保障组织。" : "";
	const reason = missingJobs.length > 0
		? [baseReason, `以下作业未匹配到基本保障活动：${missingJobs.join("、")}`].filter(Boolean).join(" ")
		: baseReason;
	const debugLines = [
		`候选组织数：${candidateDepartments.length}`,
		`通过组织数：${organizations.length}`,
		...diagnostics.map((item) => `${item.passed ? "[通过]" : "[不通过]"} ${item.departmentName}${item.failures.length > 0 ? ` -> ${item.failures.join("；")}` : ""}`)
	];
	return { organizations, reason, diagnostics, debugText: debugLines.join("\n") };
}

function getBasicOpsActivityByJobName(jobName) {
	const queryText = String(jobName || "").trim();
	if (!queryText) return null;
	return (
		BASIC_OPS_ACTIVITIES.find((item) => String(item.workName || "").trim() === queryText) ||
		BASIC_OPS_ACTIVITIES.find((item) => {
			const workName = String(item.workName || "").trim();
			return workName && (workName.includes(queryText) || queryText.includes(workName));
		}) ||
		BASIC_OPS_ACTIVITIES.find((item) => String(item.supportActivity || "").trim() === queryText) ||
		null
	);
}

function getBasicRepairActivityByJobName(jobName, target) {
	const queryText = String(jobName || "").trim();
	if (!queryText) return null;
	const targetText = String(target || "").trim();
	const scopedSource = targetText
		? BASIC_REPAIR_ACTIVITIES.filter((item) => isRepairTargetMatched(item.target, targetText))
		: BASIC_REPAIR_ACTIVITIES;
	const source = scopedSource.length > 0 ? scopedSource : BASIC_REPAIR_ACTIVITIES;
	return (
		source.find((item) => String(item.workName || "").trim() === queryText) ||
		source.find((item) => {
			const workName = String(item.workName || "").trim();
			return workName && (workName.includes(queryText) || queryText.includes(workName));
		}) ||
		BASIC_REPAIR_ACTIVITIES.find((item) => String(item.workName || "").trim() === queryText) ||
		BASIC_REPAIR_ACTIVITIES.find((item) => String(item.supportActivity || "").trim() === queryText) ||
		null
	);
}

function createComprehensiveJobDefaultConfigFromActivity(activity, fallbackDuration = 10) {
	const duration = Number(activity?.duration) > 0 ? Number(activity.duration) : fallbackDuration;
	return createComprehensiveJobConfig(duration, [], activity?.durationProfile || null);
}

function getOpsJobSourceConfig(jobName) {
	const matchedRow = getBasicOpsActivityByJobName(jobName);
	if (matchedRow) {
		return createComprehensiveJobDefaultConfigFromActivity(matchedRow, 10);
	}
	const duration = Number(BASIC_OPS_DURATION_MAP[String(jobName || "").trim()]) > 0 ? Number(BASIC_OPS_DURATION_MAP[String(jobName || "").trim()]) : 10;
	return createComprehensiveJobConfig(duration, [], null);
}

function getRepairJobSourceConfig(jobName, target) {
	const matchedRow = getBasicRepairActivityByJobName(jobName, target);
	if (matchedRow) {
		return createComprehensiveJobDefaultConfigFromActivity(matchedRow, 10);
	}
	const duration = Number(BASIC_REPAIR_DURATION_MAP[String(jobName || "").trim()]) > 0 ? Number(BASIC_REPAIR_DURATION_MAP[String(jobName || "").trim()]) : 10;
	return createComprehensiveJobConfig(duration, [], null);
}

function getComprehensiveJobDefaultConfig(tabKey, jobName, draft) {
	if (tabKey === "ops_plan") {
		return getOpsJobSourceConfig(jobName);
	}
	const corrRepairTargetName = (() => {
		const equipmentName = String(draft?.equipmentName || "").trim();
		if (equipmentName) return equipmentName;
		const repairNodeId = String(draft?.repairObject || state.selectedEquipmentRepairNode || "").trim();
		if (!repairNodeId) return "";
		const aircraftNode = findEquipmentAircraftAncestorByNodeId(state.equipmentTree, repairNodeId);
		return String(aircraftNode?.name || "").trim();
	})();
	const targetHint = tabKey === "corr_repair" ? corrRepairTargetName : draft?.equipmentName;
	return getRepairJobSourceConfig(jobName, targetHint);
}

function getComprehensiveJobDefaultDuration(tabKey, jobName, draft) {
	return getComprehensiveJobDefaultConfig(tabKey, jobName, draft).duration;
}

function normalizeComprehensiveDraft(tabKey, draft) {
	if (!draft || typeof draft !== "object") return;
	if (!Array.isArray(draft.selectedJobs)) draft.selectedJobs = [];
	if (!draft.jobs || typeof draft.jobs !== "object") draft.jobs = {};
	if (tabKey === "ops_plan") {
		normalizeOpsPlanDraft(draft);
		draft.supportOrganizations = normalizeComprehensiveSupportOrganizations(draft.supportOrganizations || []);
		draft.availableSupportOrganizations = normalizeComprehensiveSupportOrganizations(draft.availableSupportOrganizations || []);
	}
	if (tabKey === "prev_repair") {
		draft.triggerModes = normalizePrevRepairTriggerModes(draft.triggerModes || []);
		const plannedDowntimeHours = Number(draft.plannedDowntimeHours);
		const legacyRepairHours = Number(draft.repairHours);
		const inferredDowntimeHours = parsePreventiveMaintenanceHours(draft.preventiveMaintenanceName);
		draft.plannedDowntimeHours = Number.isFinite(plannedDowntimeHours) && plannedDowntimeHours > 0
			? plannedDowntimeHours
			: Number.isFinite(legacyRepairHours) && legacyRepairHours > 0
				? legacyRepairHours
				: inferredDowntimeHours > 0
					? inferredDowntimeHours
					: 8;
		draft.repairHours = draft.plannedDowntimeHours;
	}
	Object.keys(draft.jobs).forEach((jobName) => {
		const rowConfig = draft.jobs[jobName] || {};
		const defaultConfig = getComprehensiveJobDefaultConfig(tabKey, jobName, draft);
		const predecessorCodes = resolveComprehensiveJobPredecessorCodes(tabKey, draft, jobName, rowConfig);
		const predecessors = resolveComprehensiveJobPredecessorNames(tabKey, draft, jobName, predecessorCodes, rowConfig);
		draft.jobs[jobName] = createComprehensiveJobConfig(
			Number(rowConfig.duration) > 0 ? Number(rowConfig.duration) : defaultConfig.duration,
			predecessors,
			rowConfig.durationProfile || defaultConfig.durationProfile,
			predecessorCodes
		);
		draft.jobs[jobName].supportOrganizations = normalizeComprehensiveSupportOrganizations(rowConfig.supportOrganizations || []);
	});
}

function getComprehensiveDraftByTab(tabKey) {
	ensureComprehensivePlanState();
	const activePlan = getActiveComprehensivePlan(tabKey);
	let draft = null;
	if (tabKey === "ops_plan") {
		draft = activePlan?.draft || state.ui.opsPlanDraft || createDefaultOpsPlanDraft();
		state.ui.opsPlanDraft = draft;
	} else if (tabKey === "prev_repair") {
		draft = activePlan?.draft || state.ui.prevRepairDraft || createDefaultPrevRepairDraft();
		state.ui.prevRepairDraft = draft;
	} else {
		draft = activePlan?.draft || state.ui.corrRepairDraft || createDefaultCorrRepairDraft();
		state.ui.corrRepairDraft = draft;
	}
	if (activePlan) {
		activePlan.draft = draft;
	}
	normalizeComprehensiveDraft(tabKey, draft);
	return draft;
}

function ensureComprehensiveJobEntry(tabKey, draft, jobName) {
	if (!jobName) return createComprehensiveJobConfig();
	normalizeComprehensiveDraft(tabKey, draft);
	const defaultConfig = getComprehensiveJobDefaultConfig(tabKey, jobName, draft);
	if (!draft.jobs[jobName]) {
		draft.jobs[jobName] = createComprehensiveJobConfig(defaultConfig.duration, [], defaultConfig.durationProfile);
	}
	const rowConfig = draft.jobs[jobName] || {};
	const predecessorCodes = resolveComprehensiveJobPredecessorCodes(tabKey, draft, jobName, rowConfig);
	const normalizedConfig = createComprehensiveJobConfig(
		Number(rowConfig.duration) > 0 ? Number(rowConfig.duration) : defaultConfig.duration,
		resolveComprehensiveJobPredecessorNames(tabKey, draft, jobName, predecessorCodes, rowConfig),
		rowConfig.durationProfile || defaultConfig.durationProfile,
		predecessorCodes
	);
	normalizedConfig.supportOrganizations = normalizeComprehensiveSupportOrganizations(rowConfig.supportOrganizations || []);
	draft.jobs[jobName] = normalizedConfig;
	return normalizedConfig;
}

function resolveOpsDurationByJobName(jobName) {
	return getOpsJobSourceConfig(jobName).duration;
}

function resolveRepairDurationByJobName(jobName, target) {
	return getRepairJobSourceConfig(jobName, target).duration;
}

function restoreBasicOpsActivitiesToBaseline() {
	BASIC_OPS_ACTIVITIES.length = 0;
	BASIC_OPS_BASELINE_ACTIVITIES.forEach((item) => {
		BASIC_OPS_ACTIVITIES.push(cloneBasicActivityItem("basic_ops", item));
	});
	syncBasicOpsDerivedCache();
}

function ensureBasicOpsActivityByKeyword(keyword, fallbackRow) {
	let row = BASIC_OPS_ACTIVITIES.find((item) => String(item.workName || "").includes(keyword));
	if (row) return row;
	if (fallbackRow) {
		row = { ...fallbackRow };
		BASIC_OPS_ACTIVITIES.push(row);
		syncBasicOpsDerivedCache();
		return row;
	}
	return null;
}

function normalizeOpsPlanDraft(draft) {
	if (!draft || typeof draft !== "object") return;
	const normalizedModel = normalizeAircraftNodeName(draft.model || "");
	const candidateOptions = Array.from(
		new Set(
			[
				...getEquipmentAircraftModelNames(),
				...(Array.isArray(APP_CONFIG.modelTypes) ? APP_CONFIG.modelTypes.map((item) => normalizeAircraftNodeName(item)) : [])
			]
				.map((item) => String(item || "").trim())
				.filter(Boolean)
		)
	);
	draft.model = normalizedModel || candidateOptions[0] || "";
	draft.planType = normalizeOpsPlanTypeName(draft.planType);
	if (!draft.planType || !OPS_PLAN_TYPE_OPTIONS.includes(draft.planType)) {
		draft.planType = OPS_PLAN_TYPE_OPTIONS[0];
	}
	draft.simulationRunRule = OPS_SIMULATION_RUN_RULE_OPTIONS.includes(String(draft.simulationRunRule || "").trim())
		? String(draft.simulationRunRule || "").trim()
		: OPS_SIMULATION_RUN_RULE_OPTIONS[0];
	if (!Array.isArray(draft.selectedJobs)) draft.selectedJobs = [];
	if (!draft.jobs || typeof draft.jobs !== "object") draft.jobs = {};
}

function applyDurationOverrideToOpsDraft(draft, keyword, duration, fallbackWorkName) {
	if (!draft.planType || !OPS_PLAN_TYPE_OPTIONS.includes(draft.planType)) {
		draft.planType = OPS_PLAN_TYPE_OPTIONS[0];
	}
	const candidateJobs = [...new Set([...(draft.selectedJobs || []), ...Object.keys(draft.jobs || {})])];
	let targetJobName = candidateJobs.find((jobName) => String(jobName || "").includes(keyword));
	if (!targetJobName) {
		targetJobName = fallbackWorkName;
	}
	if (!targetJobName) return;

	if (!draft.selectedJobs.includes(targetJobName)) {
		draft.selectedJobs.push(targetJobName);
	}
	if (!draft.jobs[targetJobName]) {
		draft.jobs[targetJobName] = { duration: Number(duration), predecessors: [] };
	}
	draft.jobs[targetJobName].duration = Number(duration);
	draft.jobs[targetJobName].predecessors = Array.isArray(draft.jobs[targetJobName].predecessors)
		? draft.jobs[targetJobName].predecessors.filter((prev) => prev !== targetJobName)
		: [];

	const orderedKnownJobs = BASIC_OPS_WORK_NAMES.filter((name) => draft.selectedJobs.includes(name));
	const extraJobs = draft.selectedJobs.filter((name) => !BASIC_OPS_WORK_NAMES.includes(name));
	draft.selectedJobs = [...orderedKnownJobs, ...extraJobs];
}

function findOpsPlanByPhase(plans, keywords, fallbackIndex) {
	if (!Array.isArray(plans) || plans.length === 0) return null;
	const matchedPlan = plans.find((plan) => {
		const text = `${plan?.name || ""} ${plan?.draft?.activityName || ""}`;
		return keywords.some((keyword) => text.includes(keyword));
	});
	return matchedPlan || plans[fallbackIndex] || null;
}

function getMissionForSchemeOverride(preferredMission) {
	if (!state.ui || !state.tasks) return null;
	const missions = Array.isArray(state.tasks.singleMissions) ? state.tasks.singleMissions : [];
	if (preferredMission?.id) {
		state.ui.activeSingleMissionId = preferredMission.id;
		return preferredMission;
	}
	if (missions.length === 0) {
		state.ui.activeSingleMissionId = "";
		return null;
	}
	const activeMission = missions.find((item) => item.id === state.ui.activeSingleMissionId) || missions[0];
	state.ui.activeSingleMissionId = activeMission.id;
	return activeMission;
}

function syncSingleMissionSchemeOverrides(preferredMission) {
	restoreBasicOpsActivitiesToBaseline();
	ensureComprehensivePlanState();

	const mission = getMissionForSchemeOverride(preferredMission);
	if (!mission) {
		syncComprehensiveDraftPointers();
		return;
	}

	const mountRule = MOUNT_PLAN_RULES[mission.mountPlan];
	const fuelRule = mission.fuelPlan ? FUEL_PLAN_RULES[mission.fuelPlan] : null;
	const defaultFuelRow = BASIC_OPS_BASELINE_ACTIVITIES.find((item) => String(item.workName || "").includes("加油"));
	const defaultMountRow = BASIC_OPS_BASELINE_ACTIVITIES.find((item) => String(item.workName || "").includes("挂弹"));
	const fuelRow = ensureBasicOpsActivityByKeyword("加油", defaultFuelRow);
	const mountRow = ensureBasicOpsActivityByKeyword("挂弹", defaultMountRow);

	if (mountRule && mountRow) {
		mountRow.ammunition = mountRule.ammunition;
		mountRow.duration = mountRule.duration;
	}
	if (fuelRule && fuelRow) {
		fuelRow.duration = fuelRule.duration;
	}
	syncBasicOpsDerivedCache();

	const opsPlans = getComprehensivePlansByTab("ops_plan");
	const prePlan = findOpsPlanByPhase(opsPlans, ["飞行前", "起飞前"], 0);
	const relaunchPlan = findOpsPlanByPhase(opsPlans, ["再次出动", "再次"], 1);
	const postPlan = findOpsPlanByPhase(opsPlans, ["飞行后", "降落后", "回收"], 2);
	const applyToPhasePlan = (plan) => {
		if (!plan?.draft) return;
		if (mountRule) {
			applyDurationOverrideToOpsDraft(plan.draft, "挂弹", mountRule.duration, mountRow?.supportActivity || mountRow?.workName || "使用保障");
		}
		if (fuelRule) {
			applyDurationOverrideToOpsDraft(plan.draft, "加油", fuelRule.duration, fuelRow?.supportActivity || fuelRow?.workName || "使用保障");
		}
	};

	if (mission.prePlan) applyToPhasePlan(prePlan);
	if (mission.relaunchPlan) applyToPhasePlan(relaunchPlan);
	if (mission.postPlan) applyToPhasePlan(postPlan);

	syncComprehensiveDraftPointers();
}

function createNextProjectId() {
	const maxSuffix = state.projects.reduce((max, project) => {
		const match = String(project.id || "").match(/(\d+)$/);
		if (!match) return max;
		return Math.max(max, Number(match[1]));
	}, 0);
	return `project_${maxSuffix + 1}`;
}

function ensureDeckModelingState() {
	if (!state.deckModeling) {
		state.deckModeling = {
			stations: DECK_INITIAL_STATIONS.map((item) => ({ ...item })),
			facilities: DECK_INITIAL_FACILITIES.map((item) => ({ ...item })),
			matrix: DECK_INITIAL_MATRIX.map((item) => ({ ...item, values: cloneDeckMatrixValues(item.values) }))
		};
	}
	if (!Array.isArray(state.deckModeling.stations)) state.deckModeling.stations = [];
	if (!Array.isArray(state.deckModeling.facilities)) state.deckModeling.facilities = [];
	if (!Array.isArray(state.deckModeling.matrix)) state.deckModeling.matrix = [];
	const defaultShipTypeId = getDefaultDeckShipTypeId();
	state.deckModeling.stations = state.deckModeling.stations.map((item, index) => {
		const stationNo = getDeckParkingStationNo(item, index + 1);
		const parkingCaseFields = isDeckParkingStation(item)
			? buildDeckParkingCaseFields(stationNo, String(item?.type || "停机位"))
			: { area: "", description: "" };
		return {
			...item,
			shipTypeId: normalizeDeckShipTypeId(item?.shipTypeId, defaultShipTypeId),
			name: String(item?.name || item?.code || "").trim(),
			area: String(item?.area || parkingCaseFields.area || "").trim(),
			description: String(item?.description || parkingCaseFields.description || "").trim(),
			canTrialRun: normalizeDeckTrialRunValue(item?.canTrialRun, "否")
		};
	});
	state.deckModeling.facilities = state.deckModeling.facilities.map((item) => ({
		...item,
		shipTypeId: normalizeDeckShipTypeId(item?.shipTypeId, defaultShipTypeId)
	}));
	state.deckModeling.matrix = state.deckModeling.matrix.map((item) => ({
		...item,
		shipTypeId: normalizeDeckShipTypeId(item?.shipTypeId, defaultShipTypeId),
		values: cloneDeckMatrixValues(item.values)
	}));
	return state.deckModeling;
}

function isDeckParkingStation(item) {
	const typeText = String(item?.type || "").trim();
	return typeText.includes("停机位") || typeText.includes("停机站位");
}
function ensureDeckModelingUiState() {
	if (!state.ui.deckPanel || !["stations", "parking", "facilities", "matrix"].includes(state.ui.deckPanel)) {
		state.ui.deckPanel = "stations";
	}
	if (!state.ui.deckSearchDraft || typeof state.ui.deckSearchDraft !== "object") {
		state.ui.deckSearchDraft = { stations: "", parking: "", facilities: "", matrix: "" };
	}
	if (!state.ui.deckSearchApplied || typeof state.ui.deckSearchApplied !== "object") {
		state.ui.deckSearchApplied = { stations: "", parking: "", facilities: "", matrix: "" };
	}
	if (!state.ui.deckPage || typeof state.ui.deckPage !== "object") {
		state.ui.deckPage = { stations: 1, parking: 1, facilities: 1, matrix: 1 };
	}
	if (!state.ui.deckSearchComposing || typeof state.ui.deckSearchComposing !== "object") {
		state.ui.deckSearchComposing = { stations: false, parking: false, facilities: false, matrix: false };
	}
	if (typeof state.ui.deckShipTypeFilter !== "string") {
		state.ui.deckShipTypeFilter = "all";
	}
	["stations", "parking", "facilities", "matrix"].forEach((tableKey) => {
		if (typeof state.ui.deckSearchDraft[tableKey] !== "string") state.ui.deckSearchDraft[tableKey] = "";
		if (typeof state.ui.deckSearchApplied[tableKey] !== "string") state.ui.deckSearchApplied[tableKey] = "";
		if (typeof state.ui.deckSearchComposing[tableKey] !== "boolean") state.ui.deckSearchComposing[tableKey] = false;
	});
	const shipTypeIdSet = new Set(getDeckShipTypeOptions().map((item) => item.id));
	if (state.ui.deckShipTypeFilter !== "all" && !shipTypeIdSet.has(state.ui.deckShipTypeFilter)) {
		state.ui.deckShipTypeFilter = "all";
	}
	["stations", "parking", "facilities", "matrix"].forEach((tableKey) => {
		const pageValue = Number(state.ui.deckPage[tableKey]);
		state.ui.deckPage[tableKey] = Number.isFinite(pageValue) && pageValue > 0 ? Math.floor(pageValue) : 1;
	});
	return state.ui;
}

function normalizeSearchText(value) {
	return String(value ?? "").trim().toLowerCase();
}

function buildFuzzySearchTokens(keyword) {
	const normalizedKeyword = normalizeSearchText(keyword);
	if (!normalizedKeyword) return [];
	const tokens = normalizedKeyword
		.split(/[\s,，;；|]+/)
		.map((item) => item.trim())
		.filter(Boolean);
	return tokens.length ? tokens : [normalizedKeyword];
}

function getKeywordMatchRankFromValues(valueList, keywordTokens) {
	if (!Array.isArray(keywordTokens) || keywordTokens.length === 0) return 0;
	const normalizedValues = (Array.isArray(valueList) ? valueList : [valueList]).map((value) => normalizeSearchText(value)).filter(Boolean);
	if (normalizedValues.length === 0) return null;
	let totalRank = 0;
	for (const token of keywordTokens) {
		let tokenRank = Number.POSITIVE_INFINITY;
		normalizedValues.forEach((valueText) => {
			if (valueText.startsWith(token)) {
				tokenRank = Math.min(tokenRank, 0);
				return;
			}
			if (valueText.includes(token)) {
				tokenRank = Math.min(tokenRank, 1);
			}
		});
		if (!Number.isFinite(tokenRank)) return null;
		totalRank += tokenRank;
	}
	return totalRank;
}

function getRowsByKeywordPriority(rows, getValueList, keyword) {
	const keywordTokens = buildFuzzySearchTokens(keyword);
	if (keywordTokens.length === 0) return Array.isArray(rows) ? [...rows] : [];
	return (Array.isArray(rows) ? rows : [])
		.map((row, index) => {
			const rank = getKeywordMatchRankFromValues(getValueList(row), keywordTokens);
			return { row, index, rank };
		})
		.filter((item) => item.rank !== null)
		.sort((left, right) => {
			if (left.rank !== right.rank) return left.rank - right.rank;
			return left.index - right.index;
		})
		.map((item) => item.row);
}

function matchDeckKeyword(valueList, keyword) {
	const keywordTokens = buildFuzzySearchTokens(keyword);
	if (keywordTokens.length === 0) return true;
	return getKeywordMatchRankFromValues(valueList, keywordTokens) !== null;
}

function buildDeckPaginationMeta(rows, currentPage, pageSize = 20) {
	const safePageSize = Number(pageSize) > 0 ? Number(pageSize) : 20;
	const totalRows = rows.length;
	const totalPages = Math.max(1, Math.ceil(totalRows / safePageSize));
	const safeCurrentPage = Math.min(Math.max(1, Number(currentPage) || 1), totalPages);
	const start = (safeCurrentPage - 1) * safePageSize;
	const pagedRows = rows.slice(start, start + safePageSize);
	return {
		totalRows,
		totalPages,
		currentPage: safeCurrentPage,
		pageSize: safePageSize,
		pagedRows
	};
}

function ensureOrgResourceModelState() {
	if (!state.organizationResources || typeof state.organizationResources !== "object") {
		state.organizationResources = createInitialOrgResourceState();
	}
	Object.entries(ORG_RESOURCE_TABLE_CONFIG).forEach(([tableKey, config]) => {
		if (!Array.isArray(state.organizationResources[tableKey])) {
			state.organizationResources[tableKey] = [];
		}
		state.organizationResources[tableKey] = state.organizationResources[tableKey].map((row) => {
			const normalized = { id: row.id || uid(config.prefix) };
			config.fields.forEach((field) => {
				const departmentName = String(row?.department ?? row?.crew ?? "").trim();
				const isServicePersonnelDepartment = tableKey === "personnel" && isServiceDepartmentName(departmentName);
				if (field.type === "number") {
					const nextValue = Number(row[field.key]);
					normalized[field.key] = Number.isFinite(nextValue) ? nextValue : 0;
					return;
				}
				if (field.type === "checkbox-group") {
					normalized[field.key] = normalizeOrgResourceAircraftTypeSelection(row[field.key]);
					return;
				}
				if (tableKey === "personnel" && field.key === "department") {
					normalized[field.key] = departmentName;
					return;
				}
				if (tableKey === "personnel" && field.key === "major") {
					if (isServicePersonnelDepartment) {
						normalized[field.key] = "勤务组";
						return;
					}
					normalized[field.key] = String(row[field.key] ?? "").trim();
					return;
				}
				if (tableKey === "personnel" && field.key === "level") {
					const rawLevel = String(row[field.key] ?? "").trim();
					const levelOptions = getPersonnelLevelDictionaryOptions(departmentName);
					normalized[field.key] = levelOptions.includes(rawLevel) ? rawLevel : (levelOptions[0] || "L1");
					return;
				}
				normalized[field.key] = String(row[field.key] ?? "").trim();
			});
			return normalized;
		});
		if (tableKey === "personnel") {
			state.organizationResources[tableKey] = state.organizationResources[tableKey].filter(
				(row) => !ORG_PERSONNEL_CLEARED_DEPARTMENTS.has(String(row?.department || "").trim())
			);
		}
		if (ORG_RESOURCE_AIR_WING_TABS.includes(tableKey)) {
			const serviceDepartments = new Set(getServiceDepartmentOptions().map((name) => String(name || "").trim()).filter(Boolean));
			state.organizationResources[tableKey] = state.organizationResources[tableKey].filter((row) => {
				const departmentName = String(row?.department || "").trim();
				return !serviceDepartments.has(departmentName);
			});
			const scopedDepartments = tableKey === "equipment"
				? getAirWingSupportCandidateDepartments().filter(Boolean)
				: getAirWingDepartmentOptions().filter(Boolean);
			if (scopedDepartments.length > 0) {
				state.organizationResources[tableKey] = state.organizationResources[tableKey].map((row, rowIndex) => {
					const currentDepartment = String(row?.department || "").trim();
					if (scopedDepartments.includes(currentDepartment)) return row;
					return {
						...row,
						department: scopedDepartments[rowIndex % scopedDepartments.length]
					};
				});
			}
		}
		const allowedDepartments = getOrgResourceAllowedDepartmentOptions(tableKey).filter(Boolean);
		if (allowedDepartments.length > 0) {
			state.organizationResources[tableKey] = state.organizationResources[tableKey].map((row, rowIndex) => {
				const currentDepartment = String(row?.department || "").trim();
				if (allowedDepartments.includes(currentDepartment)) return row;
				const fallbackDepartment = allowedDepartments[rowIndex % allowedDepartments.length] || "";
				return {
					...row,
					department: fallbackDepartment
				};
			});
		}
	});


	["equipment", "spare", "ammunition"].forEach((tableKey) => {
		const catalogItems = getBasicOpsResourceCatalogItems(tableKey);
		if (catalogItems.length === 0) return;
		const rows = Array.isArray(state.organizationResources[tableKey]) ? state.organizationResources[tableKey] : [];
		const config = ORG_RESOURCE_TABLE_CONFIG[tableKey];
		const quantityFieldKey = getOrgResourceQuantityFieldKey(tableKey);
		const designatedDepartments = tableKey === "equipment"
			? getAirWingSupportCandidateDepartments()
			: getAirWingDepartmentOptions();
		const seedQuantityTemplate = [12, 12, 12, 12, 12, 12, 12, 12];
		catalogItems.forEach((item) => {
			const catalogKey = `${String(item.model || "").trim()}__${String(item.name || "").trim()}`;
			if (!catalogKey) return;
			const existingRows = rows.filter((row) => `${String(row?.model || "").trim()}__${String(row?.name || "").trim()}` === catalogKey);
			designatedDepartments.forEach((departmentName, departmentIndex) => {
				const minQuantity = seedQuantityTemplate[departmentIndex % seedQuantityTemplate.length];
				const matchedRows = existingRows.filter((row) => String(row?.department || "").trim() === departmentName);
				if (matchedRows.length === 0) {
					const seedRow = {
						id: uid(config?.prefix || "org_resource"),
						name: String(item.name || "").trim(),
						model: String(item.model || "").trim(),
						department: departmentName,
						[quantityFieldKey]: minQuantity
					};
					if (tableKey === "equipment") {
						seedRow.unit = "套";
					}
					rows.push(seedRow);
					return;
				}
				const currentQuantity = matchedRows.reduce((sum, row) => {
					const quantity = Number(row?.[quantityFieldKey] || 0);
					return sum + (Number.isFinite(quantity) && quantity >= 0 ? quantity : 0);
				}, 0);
				if (currentQuantity >= minQuantity) return;
				const firstRow = matchedRows[0];
				firstRow[quantityFieldKey] = Number(firstRow[quantityFieldKey] || 0) + (minQuantity - currentQuantity);
			});
		});
		state.organizationResources[tableKey] = rows;
	});

	const basicOpsSpareNeedMap = new Map();
	BASIC_OPS_ACTIVITIES.forEach((activity) => {
		parseSpareString(activity?.spare || "").forEach((row) => {
			const name = String(row?.name || "").trim();
			const model = String(row?.model || "").trim();
			if (!name && !model) return;
			const key = `${name}__${model}`;
			basicOpsSpareNeedMap.set(key, (basicOpsSpareNeedMap.get(key) || 0) + parseResourceNeedCount(row?.count));
		});
	});
	const spareRows = Array.isArray(state.organizationResources.spare) ? state.organizationResources.spare : [];
	const spareTargetDepartments = getAirWingDepartmentOptions().slice(0, 3);
	spareTargetDepartments.forEach((departmentName) => {
		basicOpsSpareNeedMap.forEach((requiredCount, key) => {
			const [name, model] = key.split("__");
			const minCount = requiredCount + 2;
			const matchedRows = spareRows.filter((row) =>
				String(row?.department || "").trim() === departmentName &&
				String(row?.name || "").trim() === name &&
				String(row?.model || "").trim() === model
			);
			if (matchedRows.length === 0) {
				spareRows.push({
					id: uid("org_spare"),
					name,
					model,
					demandCount: minCount,
					department: departmentName
				});
				return;
			}
			const currentCount = matchedRows.reduce((sum, row) => {
				const value = Number(row?.demandCount || 0);
				return sum + (Number.isFinite(value) && value >= 0 ? value : 0);
			}, 0);
			if (currentCount >= minCount) return;
			matchedRows[0].demandCount = Number(matchedRows[0].demandCount || 0) + (minCount - currentCount);
		});
	});
	state.organizationResources.spare = spareRows;

	const personnelRows = Array.isArray(state.organizationResources.personnel) ? state.organizationResources.personnel : [];
	const personnelTargetDepartments = getAirWingDepartmentOptions();
	const personnelNeedMap = new Map();
	BASIC_OPS_ACTIVITIES.forEach((activity) => {
		parsePersonnelString(activity?.personnel || "").forEach((row) => {
			const major = String(row?.major || "").trim();
			const level = String(row?.level || "L1").trim() || "L1";
			if (!major) return;
			const key = `${major}__${level}`;
			personnelNeedMap.set(key, (personnelNeedMap.get(key) || 0) + parseResourceNeedCount(row?.count));
		});
	});
	personnelTargetDepartments.forEach((departmentName) => {
		personnelNeedMap.forEach((requiredCount, key) => {
			const [major, level] = key.split("__");
			const minCount = Math.max(10, requiredCount + 4);
			const matchedRows = personnelRows.filter((row) =>
				String(row?.department || "").trim() === departmentName &&
				String(row?.major || "").trim() === major &&
				String(row?.level || "").trim() === level
			);
			if (matchedRows.length === 0) {
				personnelRows.push({
					id: uid("org_personnel"),
					department: departmentName,
					major,
					level,
					count: minCount
				});
				return;
			}
			const currentCount = matchedRows.reduce((sum, row) => {
				const value = Number(row?.count || 0);
				return sum + (Number.isFinite(value) && value >= 0 ? value : 0);
			}, 0);
			if (currentCount >= minCount) return;
			matchedRows[0].count = Number(matchedRows[0].count || 0) + (minCount - currentCount);
		});
	});
	state.organizationResources.personnel = personnelRows;

	return state.organizationResources;
}

function getSpareResourceNameOptions() {
	ensureOrgResourceModelState();
	const spareNames = [
		...(state.organizationResources.spare || []).map((row) => String(row?.name || "").trim()),
		...getEquipmentConfigSpareNameOptions().map((name) => String(name || "").trim())
	].filter(Boolean);
	return Array.from(
		new Set(spareNames)
	);
}

function ensureOrgResourceSelectedState() {
	if (!state.ui.selectedOrgResourceIds || typeof state.ui.selectedOrgResourceIds !== "object") {
		state.ui.selectedOrgResourceIds = {
			personnel: [],
			equipment: [],
			spare: [],
			ammunition: []
		};
	}
	Object.keys(ORG_RESOURCE_TABLE_CONFIG).forEach((tableKey) => {
		if (!Array.isArray(state.ui.selectedOrgResourceIds[tableKey])) {
			state.ui.selectedOrgResourceIds[tableKey] = [];
		}
	});
	return state.ui.selectedOrgResourceIds;
}

function ensureOrgResourceViewState() {
	if (!state.ui.orgResourceView || typeof state.ui.orgResourceView !== "object") {
		state.ui.orgResourceView = createInitialOrgResourceViewState();
	}
	if (!state.ui.orgResourceSearchComposing || typeof state.ui.orgResourceSearchComposing !== "object") {
		state.ui.orgResourceSearchComposing = {
			personnel: false,
			equipment: false,
			spare: false,
			ammunition: false
		};
	}
	Object.keys(ORG_RESOURCE_TABLE_CONFIG).forEach((tableKey) => {
		const fallback = createInitialOrgResourceViewState()[tableKey];
		if (!state.ui.orgResourceView[tableKey] || typeof state.ui.orgResourceView[tableKey] !== "object") {
			state.ui.orgResourceView[tableKey] = { ...fallback };
		}
		if (typeof state.ui.orgResourceSearchComposing[tableKey] !== "boolean") {
			state.ui.orgResourceSearchComposing[tableKey] = false;
		}
		const rowView = state.ui.orgResourceView[tableKey];
		const nextPage = Number(rowView.page);
		rowView.page = Number.isFinite(nextPage) && nextPage > 0 ? Math.floor(nextPage) : 1;
		rowView.keyword = String(rowView.keyword || "");
	});
	return state.ui.orgResourceView;
}

function matchOrgResourceKeyword(tableKey, row, keyword) {
	const config = ORG_RESOURCE_TABLE_CONFIG[tableKey];
	if (!config) return true;
	const keywordTokens = buildFuzzySearchTokens(keyword);
	if (keywordTokens.length === 0) return true;
	const valueList = config.fields.map((field) => row?.[field.key]);
	return getKeywordMatchRankFromValues(valueList, keywordTokens) !== null;
}

function buildOrgResourceViewMeta(tableKey, selectedNode) {
	const viewState = ensureOrgResourceViewState()[tableKey] || { page: 1, keyword: "" };
	const scopedRows = isOrgResourceEquipmentTreeScopedTable(tableKey)
		? getOrgResourceRowsByEquipmentNode(tableKey, getOrgResourceEquipmentScopeNode(tableKey))
		: getOrgResourceRowsByNode(tableKey, getOrgResourceScopeNode(tableKey, selectedNode));
	const config = ORG_RESOURCE_TABLE_CONFIG[tableKey];
	const filteredRows = config
		? getRowsByKeywordPriority(scopedRows, (row) => config.fields.map((field) => row?.[field.key]), viewState.keyword)
		: scopedRows.filter((row) => matchOrgResourceKeyword(tableKey, row, viewState.keyword));
	const paginationMeta = buildDeckPaginationMeta(filteredRows, viewState.page, ORG_RESOURCE_PAGE_SIZE);
	viewState.page = paginationMeta.currentPage;
	return {
		...paginationMeta,
		scopedRows,
		filteredRows,
		searchKeyword: String(viewState.keyword || "")
	};
}

function getOrgResourceRowsByDepartment(tableKey, departmentName) {
	const resources = ensureOrgResourceModelState();
	const rows = Array.isArray(resources[tableKey]) ? resources[tableKey] : [];
	const department = String(departmentName || "").trim();
	if (!department) return [];
	return rows.filter((item) => String(item?.department || "").trim() === department);
}

function collectOrgNodeNames(node, names = new Set()) {
	if (!node || typeof node !== "object") return names;
	const nodeName = String(node.name || "").trim();
	if (nodeName) {
		names.add(nodeName);
	}
	(node.children || []).forEach((child) => {
		collectOrgNodeNames(child, names);
	});
	return names;
}

function getAllOrganizationDepartmentOptions() {
	const names = new Set();
	(state.organizationTree || []).forEach((node) => collectOrgNodeNames(node, names));
	return Array.from(names);
}

function getOrgResourceRowsByNode(tableKey, node) {
	const resources = ensureOrgResourceModelState();
	const rows = Array.isArray(resources[tableKey]) ? resources[tableKey] : [];
	if (!node || typeof node !== "object") return rows;
	const scopedNames = collectOrgNodeNames(node);
	if (scopedNames.size === 0) return rows;
	return rows.filter((item) => scopedNames.has(String(item?.department || "").trim()));
}

function getOrgResourceRowsByEquipmentNode(tableKey, node) {
	const resources = ensureOrgResourceModelState();
	const rows = Array.isArray(resources[tableKey]) ? resources[tableKey] : [];
	if (!node || typeof node !== "object") return rows;
	const scopedNodeIds = collectEquipmentNodeIds(node, new Set());
	if (scopedNodeIds.size === 0) return rows;
	return rows.filter((item) => {
		const equipmentNodeId = String(item?.equipmentNodeId || "").trim();
		if (!equipmentNodeId) return true;
		return scopedNodeIds.has(equipmentNodeId);
	});
}

function getOrgResourceQuantityFieldKey(tableKey) {
	return tableKey === "equipment" ? "count" : "demandCount";
}

function getEquipmentConfigSpareCatalogItems() {
	const itemMap = new Map();
	const walk = (nodes) => {
		if (!Array.isArray(nodes)) return;
		nodes.forEach((node) => {
			if (!node || typeof node !== "object") return;
			const nodeType = String(node.type || "").trim();
			if (nodeType !== "aircraft") {
				const name = String(node.name || "").trim();
				const model = String(node.model || "").trim();
				if (name && model && name !== "无" && name !== "-") {
					const key = `${model}__${name}`;
					if (!itemMap.has(key)) {
						itemMap.set(key, { key, name, model });
					}
				}
			}
			walk(node.children || []);
		});
	};
	walk(state.equipmentTree || []);
	return Array.from(itemMap.values()).sort((left, right) => {
		const modelCompare = String(left.model || "").localeCompare(String(right.model || ""), "zh-Hans-CN");
		if (modelCompare !== 0) return modelCompare;
		return String(left.name || "").localeCompare(String(right.name || ""), "zh-Hans-CN");
	});
}

function getBasicOpsResourceCatalogItems(tableKey) {
	const normalizedTableKey = String(tableKey || "").trim();
	if (["equipment", "spare", "ammunition"].includes(normalizedTableKey)) {
		const resourceRows = Array.isArray(state.organizationResources?.[normalizedTableKey]) ? state.organizationResources[normalizedTableKey] : [];
		const itemMap = new Map();
		resourceRows.forEach((row) => {
			const name = String(row?.name || "").trim();
			const model = String(row?.model || "").trim() || "未设置型号";
			if (!name || name === "无" || name === "-") return;
			const key = `${model}__${name}`;
			if (!itemMap.has(key)) {
				itemMap.set(key, { key, name, model });
			}
		});
		if (itemMap.size > 0) {
			return Array.from(itemMap.values()).sort((left, right) => {
				const modelCompare = String(left.model || "").localeCompare(String(right.model || ""), "zh-Hans-CN");
				if (modelCompare !== 0) return modelCompare;
				return String(left.name || "").localeCompare(String(right.name || ""), "zh-Hans-CN");
			});
		}
	}
	if (normalizedTableKey === "spare") {
		return getEquipmentConfigSpareCatalogItems();
	}
	const parser = normalizedTableKey === "equipment" ? parseEquipmentString : normalizedTableKey === "ammunition" ? parseAmmunitionString : null;
	if (!parser) return [];
	const itemMap = new Map();
	(BASIC_OPS_ACTIVITIES || []).forEach((activity) => {
		parser(String(activity?.[normalizedTableKey] || "")).forEach((entry) => {
			const name = String(entry?.name || "").trim();
			const model = String(entry?.model || "").trim() || "未设置型号";
			if (!name || name === "无" || name === "-") return;
			const key = `${model}__${name}`;
			if (!itemMap.has(key)) {
				itemMap.set(key, { key, name, model });
			}
		});
	});
	return Array.from(itemMap.values()).sort((left, right) => {
		const modelCompare = String(left.model || "").localeCompare(String(right.model || ""), "zh-Hans-CN");
		if (modelCompare !== 0) return modelCompare;
		return String(left.name || "").localeCompare(String(right.name || ""), "zh-Hans-CN");
	});
}

function ensureOrgResourceCatalogSelectionState() {
	if (!state.ui.orgResourceCatalogSelection || typeof state.ui.orgResourceCatalogSelection !== "object") {
		state.ui.orgResourceCatalogSelection = {
			equipment: "",
			spare: "",
			ammunition: ""
		};
	}
	["equipment", "spare", "ammunition"].forEach((tableKey) => {
		if (typeof state.ui.orgResourceCatalogSelection[tableKey] !== "string") {
			state.ui.orgResourceCatalogSelection[tableKey] = "";
		}
	});
	return state.ui.orgResourceCatalogSelection;
}

function createOrgResourceDefaultItem(tableKey, selectedDepartmentName = "", selectedEquipmentNode = null) {
	const config = ORG_RESOURCE_TABLE_CONFIG[tableKey];
	const item = { id: uid(config?.prefix || "org_resource") };
	const isServicePersonnelDepartment = tableKey === "personnel" && isServiceDepartmentName(selectedDepartmentName);
	(config?.fields || []).forEach((field) => {
		if (field.type === "number") {
			item[field.key] = 0;
			return;
		}
		if (field.type === "checkbox-group") {
			item[field.key] = [];
			return;
		}
		if (field.key === "department" && isOrgResourceTreeScopedTable(tableKey) && selectedDepartmentName && selectedDepartmentName !== "-") {
			item[field.key] = selectedDepartmentName;
			return;
		}
		if (field.key === "major" && tableKey === "personnel") {
			item[field.key] = isServicePersonnelDepartment ? "勤务组" : getPersonnelMajorDictionaryOptions()[0] || "";
			return;
		}
		if (field.key === "level" && tableKey === "personnel") {
			item[field.key] = getPersonnelLevelDictionaryOptions(selectedDepartmentName)[0] || "L1";
			return;
		}
		item[field.key] = "";
	});
	if (tableKey === "spare" && selectedEquipmentNode && typeof selectedEquipmentNode === "object") {
		item.equipmentNodeId = String(selectedEquipmentNode.id || "").trim();
		item.equipmentNodeName = String(selectedEquipmentNode.name || "").trim();
	}
	return item;
}

function validateOrgResourceItem(tableKey, item) {
	const config = ORG_RESOURCE_TABLE_CONFIG[tableKey];
	if (!config) return "数据表类型不合法。";
	const allowedAircraftTypeNames = new Set(getAircraftTypeNameOptions());
	const skipPersonnelMajorValidation = tableKey === "personnel" && isServiceDepartmentName(item?.department);
	if (tableKey === "personnel") {
		const majorValue = String(item.major || "").trim();
		if (skipPersonnelMajorValidation && majorValue && majorValue !== "勤务组") {
			return "勤务部门专业名称必须为勤务组。";
		}
		if (!skipPersonnelMajorValidation && majorValue && !getPersonnelMajorDictionaryOptions().includes(majorValue)) {
			return "专业名称必须从字典中选择。";
		}
		const levelValue = String(item.level || "").trim();
		if (levelValue && !getPersonnelLevelDictionaryOptions(item?.department).includes(levelValue)) {
			return "专业等级必须从字典中选择。";
		}
	}
	for (const field of config.fields) {
		if (skipPersonnelMajorValidation && field.key === "major") {
			continue;
		}
		const rawValue = item[field.key];
		if (field.type === "checkbox-group") {
			const selectedValues = normalizeOrgResourceAircraftTypeSelection(rawValue);
			if (selectedValues.some((value) => !allowedAircraftTypeNames.has(value))) {
				return `${field.label}包含未定义的机型。`;
			}
			continue;
		}
		if (field.required && String(rawValue ?? "").trim() === "") {
			return `${field.label}为必填项。`;
		}
		if (field.type === "number") {
			const numberValue = Number(rawValue);
			if (!Number.isFinite(numberValue)) {
				return `${field.label}必须为数字。`;
			}
			if (typeof field.min === "number" && numberValue < field.min) {
				return `${field.label}不能小于 ${field.min}。`;
			}
		}
	}
	return "";
}

function normalizeImportHeader(value) {
	return String(value ?? "").replace(/\s+/g, "").toLowerCase();
}

function readImportCellByAliases(normalizedRow, aliases) {
	for (const alias of aliases) {
		const key = normalizeImportHeader(alias);
		if (key && Object.prototype.hasOwnProperty.call(normalizedRow, key)) {
			return normalizedRow[key];
		}
	}
	return "";
}

async function importOrgResourceByExcel(tableKey, file) {
	if (!window.XLSX || typeof window.XLSX.read !== "function") {
		throw new Error("未加载 Excel 解析库，请检查网络后重试。");
	}
	const config = ORG_RESOURCE_TABLE_CONFIG[tableKey];
	if (!config) {
		throw new Error("未知的数据表类型，无法导入。");
	}

	const workbook = window.XLSX.read(await file.arrayBuffer(), { type: "array" });
	const firstSheetName = workbook.SheetNames?.[0];
	if (!firstSheetName) {
		throw new Error("Excel 文件没有可读取的工作表。");
	}
	const sheet = workbook.Sheets[firstSheetName];
	const rows = window.XLSX.utils.sheet_to_json(sheet, { defval: "" });
	if (!rows.length) {
		throw new Error("Excel 文件为空，未读取到任何数据行。");
	}

	const headerKeys = Object.keys(rows[0]).map((key) => normalizeImportHeader(key));
	const missingFields = config.fields
		.filter((field) => field.required && ![field.key, field.label, ...(field.aliases || [])].some((alias) => headerKeys.includes(normalizeImportHeader(alias))))
		.map((field) => field.label);
	if (missingFields.length) {
		throw new Error(`导入失败，缺少字段：${missingFields.join("、")}`);
	}

	const importedItems = [];
	const rowErrors = [];
	rows.forEach((row, index) => {
		const normalizedRow = {};
		Object.entries(row).forEach(([key, value]) => {
			normalizedRow[normalizeImportHeader(key)] = value;
		});
		const item = { id: uid(config.prefix) };
		config.fields.forEach((field) => {
			const rawValue = readImportCellByAliases(normalizedRow, [field.key, field.label, ...(field.aliases || [])]);
			if (field.type === "number") {
				const numberValue = Number(rawValue);
				item[field.key] = Number.isFinite(numberValue) ? numberValue : rawValue;
				return;
			}
			if (field.type === "checkbox-group") {
				item[field.key] = normalizeOrgResourceAircraftTypeSelection(rawValue);
				return;
			}
			item[field.key] = String(rawValue ?? "").trim();
		});
		const validationError = validateOrgResourceItem(tableKey, item);
		if (validationError) {
			rowErrors.push(`第 ${index + 2} 行：${validationError}`);
			return;
		}
		importedItems.push(item);
	});

	if (!importedItems.length) {
		throw new Error(rowErrors[0] || "导入失败：未读取到合法数据。");
	}
	return { importedItems, rowErrors };
}

async function importDeckRowsByExcel(tableKey, file) {
	if (!window.XLSX || typeof window.XLSX.read !== "function") {
		throw new Error("未加载 Excel 解析库，请检查网络后重试。");
	}
	if (!["stations", "facilities", "matrix"].includes(tableKey)) {
		throw new Error("仅支持导入保障站位列表、保障设施列表和保障站位-设施关联矩阵。");
	}

	const workbook = window.XLSX.read(await file.arrayBuffer(), { type: "array" });
	const firstSheetName = workbook.SheetNames?.[0];
	if (!firstSheetName) {
		throw new Error("Excel 文件没有可读取的工作表。");
	}
	const sheet = workbook.Sheets[firstSheetName];
	const rows = window.XLSX.utils.sheet_to_json(sheet, { defval: "" });
	if (!rows.length) {
		throw new Error("Excel 文件为空，未读取到任何数据行。");
	}

	const importedItems = [];
	const rowErrors = [];
	rows.forEach((row, index) => {
		const normalizedRow = {};
		Object.entries(row || {}).forEach(([key, value]) => {
			normalizedRow[normalizeImportHeader(key)] = value;
		});
		const shipTypeRaw = readImportCellByAliases(normalizedRow, ["船型", "船型名称", "shiptype", "shiptypename"]);
		const shipTypeId = resolveDeckShipTypeIdFromInput(shipTypeRaw, getDefaultDeckShipTypeId());

		if (tableKey === "stations") {
			const code = String(readImportCellByAliases(normalizedRow, ["站位编号", "编号", "code", "stationcode"]) || "").trim();
			const name = String(readImportCellByAliases(normalizedRow, ["站位名称", "名称", "name", "stationname"]) || "").trim();
			const type = String(readImportCellByAliases(normalizedRow, ["站位类型", "类型", "type"]) || "").trim() || "未分类";
			const canTrialRun = normalizeDeckTrialRunValue(readImportCellByAliases(normalizedRow, ["是否可以试车", "是否试车", "可试车", "cantrialrun"]), "否");
			if (!code || !name) {
				rowErrors.push(`第 ${index + 2} 行：站位编号和站位名称不能为空`);
				return;
			}
			importedItems.push({ id: uid("station"), code, name, type, canTrialRun, shipTypeId });
			return;
		}

		if (tableKey === "facilities") {
			const code = String(readImportCellByAliases(normalizedRow, ["设施编号", "设备编号", "编号", "code", "facilitycode"]) || "").trim();
			const fn = String(readImportCellByAliases(normalizedRow, ["设备功能", "功能", "fn", "function"]) || "").trim();
			const name = String(readImportCellByAliases(normalizedRow, ["设施名称", "设备名称", "名称", "name", "facilityname"]) || "").trim();
			if (!code || !name) {
				rowErrors.push(`第 ${index + 2} 行：设施编号和设施名称不能为空`);
				return;
			}
			if (!DECK_SUPPORT_FUNCTIONS.includes(fn)) {
				rowErrors.push(`第 ${index + 2} 行：设备功能不合法（需为：${DECK_SUPPORT_FUNCTIONS.join("/")}）`);
				return;
			}
			importedItems.push({ id: uid("facility"), code, fn, name, shipTypeId });
			return;
		}

		const stationName = String(readImportCellByAliases(normalizedRow, ["保障站位", "站位设施", "站位名称", "stationname"]) || "").trim();
		if (!stationName) {
			rowErrors.push(`第 ${index + 2} 行：保障站位不能为空`);
			return;
		}
		const values = createDeckMatrixEmptyValues();
		DECK_SUPPORT_FUNCTIONS.forEach((fnName) => {
			values[fnName] = normalizeDeckMatrixSelection(readImportCellByAliases(normalizedRow, [fnName]));
		});
		importedItems.push({ id: uid("matrix"), stationName, shipTypeId, values });
	});

	if (!importedItems.length) {
		throw new Error(rowErrors[0] || "导入失败：未读取到合法数据。");
	}
	return { importedItems, rowErrors };
}

