function buildMissionSustainabilityResultData() {
	const config = ensureMetricConfigState("analysis", "aircraft-min-demand");
	const { selectedSchemeName, rows, selectedBasicTasks } = buildSelectedSchemeDemandRows();
	const experimentConfig = ensureExperimentManagerConfig();
	const globalMinimumEquipmentQuantity = Math.max(0, Math.floor(Number(experimentConfig.minimumEquipmentQuantity || 0)));
	const cycleHours = 7 * 24;
	const maxCycles = 8;
	const explanationText = "说明: 任务剖面按 7 天为一个周期重复，记录首个中断任务，并继续统计各机型首次无法出动前的最大持续时间与最大出动架次。";
	const candidateRows = rows.filter((item) => item.minimumDemand > 0);
	const failureCandidate = candidateRows.length > 0
		? candidateRows.reduce((worst, item) => {
			const worstScore = worst ? (worst.availableCount / Math.max(1, worst.minimumDemand)) : Number.POSITIVE_INFINITY;
			const currentScore = item.availableCount / Math.max(1, item.minimumDemand);
			return currentScore < worstScore ? item : worst;
		}, null)
		: null;
	const sustainableCycles = failureCandidate
		? Math.max(0, Math.min(maxCycles, Math.floor(failureCandidate.availableCount / Math.max(1, failureCandidate.minimumDemand))))
		: maxCycles;
	const interrupted = sustainableCycles < maxCycles;
	const maxDurationHours = (interrupted ? sustainableCycles : maxCycles) * cycleHours;
	const maxDurationDays = Number((maxDurationHours / 24).toFixed(2));
	const failureCycle = interrupted ? Math.max(1, sustainableCycles + 1) : "-";
	const totalSortiesPerCycle = selectedBasicTasks.reduce((sum, task) => {
		const draft = createBasicTaskDraft(task);
		return sum + Math.max(0, Number(draft.equipmentQuantity || 0));
	}, 0);
	const sortiesPerCycleByModel = selectedBasicTasks.reduce((map, task) => {
		const draft = createBasicTaskDraft(task);
		const modelName = String(draft?.equipmentType || "").trim();
		if (!modelName) return map;
		const quantity = Math.max(0, Number(draft.equipmentQuantity || 0));
		map.set(modelName, (map.get(modelName) || 0) + quantity);
		return map;
	}, new Map());
	const totalSorties = totalSortiesPerCycle * Math.max(1, interrupted ? failureCycle : maxCycles);
	const totalRepairs = totalSorties;
	const failureDrafts = selectedBasicTasks
		.map((task) => createBasicTaskDraft(task))
		.filter((task) => String(task?.equipmentType || "").trim() === String(failureCandidate?.modelName || "").trim())
		.map((task) => {
			const start = parseDate(task.startTime);
			const end = parseDate(task.endTime);
			return {
				id: String(task.id || task.taskNo || "-").trim() || "-",
				name: String(task.name || task.supportActivityName || "-").trim() || "-",
				modelName: String(task.equipmentType || "-").trim() || "-",
				start,
				end,
				equipmentQuantity: Math.max(0, Number(task.equipmentQuantity || 0)),
				minimumEquipmentQuantity: globalMinimumEquipmentQuantity > 0
					? globalMinimumEquipmentQuantity
					: Math.max(0, Number(task.minimumEquipmentQuantity || 0))
			};
		})
		.filter((task) => task.start && task.end && !Number.isNaN(task.start.valueOf()) && !Number.isNaN(task.end.valueOf()) && task.end > task.start)
		.sort((left, right) => left.start - right.start);
	const baseStart = failureDrafts.length > 0 ? failureDrafts[0].start : null;
	const failureTask = interrupted && failureCandidate && failureDrafts.length > 0
		? (() => {
			const cycleOffset = (failureCycle - 1) * cycleHours;
			return failureDrafts.reduce((picked, task) => {
				const startHour = baseStart ? ((task.start.getTime() - baseStart.getTime()) / (1000 * 60 * 60)) : 0;
				const absoluteStartHour = cycleOffset + startHour;
				const durationHours = (task.end.getTime() - task.start.getTime()) / (1000 * 60 * 60);
				const activeDemand = failureDrafts.reduce((sum, current) => {
					const currentStartHour = baseStart ? ((current.start.getTime() - baseStart.getTime()) / (1000 * 60 * 60)) : 0;
					const currentEndHour = currentStartHour + ((current.end.getTime() - current.start.getTime()) / (1000 * 60 * 60));
					return currentStartHour <= startHour && currentEndHour > startHour ? sum + Math.max(1, current.minimumEquipmentQuantity || current.equipmentQuantity || 0) : sum;
				}, 0);
				const assignedAircraftCount = Math.min(activeDemand, failureCandidate.availableCount);
				const idleCount = Math.max(0, failureCandidate.availableCount - assignedAircraftCount);
				const shortageCount = Math.max(0, activeDemand - failureCandidate.availableCount);
				const statusDistribution = `任务中 ${assignedAircraftCount} / 空闲 ${idleCount} / 缺口 ${shortageCount}`;
				const nextTask = {
					failureTaskId: task.id,
					failureTaskName: task.name,
					failureModelName: task.modelName,
					planStartHour: Number.isInteger(absoluteStartHour) ? String(absoluteStartHour) : absoluteStartHour.toFixed(2),
					durationHours: Number.isInteger(durationHours) ? String(durationHours) : durationHours.toFixed(2),
					availableCount: `${failureCandidate.availableCount}`,
					assignedAircraftCount: `${assignedAircraftCount}`,
					statusDistribution,
					bottleneckDemandCount: `${failureCandidate.minimumDemand}`
				};
				if (!picked) return nextTask;
				return Number(nextTask.planStartHour) < Number(picked.planStartHour) ? nextTask : picked;
			}, null);
		})()
		: null;
	const allTypesUnavailable = candidateRows.length > 0 && candidateRows.every((item) => item.availableCount <= 0);
	const allTypesUnavailableHours = allTypesUnavailable ? 0 : maxCycles * cycleHours;
	const allTypesUnavailableDays = Number((allTypesUnavailableHours / 24).toFixed(2));
	const byTypeRows = rows.length > 0
		? rows.map((item) => {
			const typeDemand = Math.max(1, item.minimumDemand || item.scheduledDemand || 0);
			const sustainableCyclesByType = item.minimumDemand > 0
				? Math.max(0, Math.min(maxCycles, Math.floor(item.availableCount / typeDemand)))
				: maxCycles;
			const typeFailed = item.minimumDemand > 0 && sustainableCyclesByType < maxCycles;
			const maxSustainHoursByType = (typeFailed ? sustainableCyclesByType : maxCycles) * cycleHours;
			const maxSustainDaysByType = Number((maxSustainHoursByType / 24).toFixed(2));
			const maxSortiesByType = (sortiesPerCycleByModel.get(item.modelName) || item.scheduledDemand || item.minimumDemand || 0)
				* Math.max(1, typeFailed ? sustainableCyclesByType + 1 : maxCycles);
			const isFailureType = String(item.modelName) === String(failureCandidate?.modelName || "");
			const failureTime = isFailureType && failureTask ? failureTask.planStartHour : (typeFailed ? `${maxSustainHoursByType}` : "-");
			const bottleneckType = isFailureType && failureTask
				? "飞机数量瓶颈"
				: (typeFailed ? "飞机数量瓶颈" : "未在测试周期内发生出动失败");
			const bottleneckDetail = isFailureType && failureTask
				? `现有 ${item.availableCount} 架，最低需求 ${item.minimumDemand} 架`
				: (typeFailed ? `现有 ${item.availableCount} 架，最低需求 ${item.minimumDemand} 架` : "");
			const statusDistribution = isFailureType && failureTask
				? failureTask.statusDistribution
				: (typeFailed ? `任务中 ${Math.min(item.availableCount, item.minimumDemand)} / 空闲 0 / 缺口 ${Math.max(0, item.minimumDemand - item.availableCount)}` : "{}");
			return [
				item.modelName,
				`${item.availableCount}`,
				`${maxSortiesByType}`,
				`${maxSustainHoursByType}`,
				`${maxSustainDaysByType}`,
				typeFailed ? "是" : "否",
				isFailureType && failureTask ? failureTask.failureTaskName : (typeFailed ? "未识别失败任务" : "-"),
				failureTime,
				bottleneckType,
				bottleneckDetail || "-",
				statusDistribution
			];
		})
		: [["暂无任务机型", "0", "0", "0", "0", "否", "-", "-", "-", "-", "{}"]];

	return {
		hideTargetCard: true,
		hideSummaryNote: false,
		hideChart: true,
		hideDetailsTable: true,
		summaryNote: `${explanationText}${selectedSchemeName ? ` 当前仿真实验：${selectedSchemeName}。` : ""}`,
		details: [],
		sections: [
			{
				title: "最大任务持续能力汇总",
				description: explanationText,
				headers: ["任务剖面周期(小时)", "测试周期数", "最大持续时间(小时)", "最大持续时间(天)", "完成整周期数", "是否发生中断", "总出动架次", "总维修次数", "中断瓶颈机型需求数"],
				rows: [[
					`${cycleHours}`,
					`${maxCycles}`,
					`${maxDurationHours}`,
					`${maxDurationDays}`,
					`${interrupted ? sustainableCycles : maxCycles}`,
					interrupted ? "是" : "否",
					`${totalSorties}`,
					`${totalRepairs}`,
					failureTask?.bottleneckDemandCount || (failureCandidate ? `${failureCandidate.minimumDemand}` : "-")
				]]
			},
			{
				title: "全部机型持续能力概览",
				headers: ["全部机型均无法出动", "全部机型均无法出动时间(小时)", "全部机型均无法出动时间(天)"],
				rows: [[allTypesUnavailable ? "是" : "否", `${allTypesUnavailableHours}`, `${allTypesUnavailableDays}`]]
			},
			{
				title: "各机型持续能力明细",
				headers: ["机型", "现有数量", "最大出动架次", "最大持续时间(小时)", "最大持续时间(天)", "是否发生出动失败", "首次失败任务", "首次失败时间(小时)", "资源短板类型", "资源短板明细", "失败时状态分布"],
				rows: byTypeRows
			},
			{
				title: "首个失败任务明细",
				headers: ["失败任务ID", "失败任务名称", "失败机型", "任务计划开始小时", "任务时长(小时)", "该机型现有数量", "失败时已编入任务的飞机数", "失败时该机型状态分布"],
				rows: failureTask
					? [[
						failureTask.failureTaskId,
						failureTask.failureTaskName,
						failureTask.failureModelName,
						failureTask.planStartHour,
						failureTask.durationHours,
						failureTask.availableCount,
						failureTask.assignedAircraftCount,
						failureTask.statusDistribution
					]]
					: [["-", interrupted ? "未识别失败任务" : "在测试周期范围内未出现任务中断", failureCandidate?.modelName || "-", "-", "-", failureCandidate ? `${failureCandidate.availableCount}` : "-", "-", interrupted ? "无可用失败任务明细" : "无中断"]]
			}
		]
	};
}

function buildResourceSupplyAnalysisResultData() {
	ensureMetricConfigState("analysis", "resource-supply");
	ensureOrgResourceModelState();
	const resources = state.organizationResources || createInitialOrgResourceState();
	const { selectedBasicTasks } = buildSelectedSchemeDemandRows();
	const consumableRows = [];
	const analysisCycleCount = 8;
	const cycleHours = 7 * 24;
	(resources.spare || []).forEach((row) => {
		const baseCount = Math.max(0, Number(row?.demandCount || 0));
		const initialInventory = Math.max(1, Math.round(baseCount * 1.15));
		const cumulativeConsumption = initialInventory + Math.max(1, Math.ceil(baseCount * 0.35));
		const remainingInventory = Math.max(0, initialInventory - cumulativeConsumption);
		const shortageCount = Math.max(0, cumulativeConsumption - initialInventory);
		const supportModel = String(row?.supportModel || "").trim();
		const avgConsumptionPerCycle = Number((cumulativeConsumption / analysisCycleCount).toFixed(2));
		const firstDepletionCycle = shortageCount > 0 ? Math.max(1, Math.min(analysisCycleCount, Math.ceil(initialInventory / Math.max(avgConsumptionPerCycle, 0.01)))) : null;
		const firstDepletionHours = firstDepletionCycle ? firstDepletionCycle * cycleHours : null;
		const firstDepletionDays = firstDepletionHours ? Number((firstDepletionHours / 24).toFixed(2)) : null;
		consumableRows.push({
			resourceType: "备件",
			resourceName: String(row?.name || row?.model || "-").trim() || "-",
			resourceId: String(row?.id || row?.code || row?.model || row?.name || "-").trim() || "-",
			initialInventory,
			cumulativeConsumption,
			remainingInventory,
			shortageCount,
			avgConsumptionPerCycle,
			firstDepletionHours,
			firstDepletionDays,
			sourceSheetCount: 1,
			supportModel,
			department: String(row?.department || "-").trim() || "-"
		});
	});
	(resources.ammunition || []).forEach((row) => {
		const baseCount = Math.max(0, Number(row?.demandCount || 0));
		const initialInventory = Math.max(1, Math.round(baseCount * 1.2));
		const cumulativeConsumption = initialInventory + Math.max(1, Math.ceil(baseCount * 0.28));
		const remainingInventory = Math.max(0, initialInventory - cumulativeConsumption);
		const shortageCount = Math.max(0, cumulativeConsumption - initialInventory);
		const supportModel = String(row?.supportModel || "").trim();
		const avgConsumptionPerCycle = Number((cumulativeConsumption / analysisCycleCount).toFixed(2));
		const firstDepletionCycle = shortageCount > 0 ? Math.max(1, Math.min(analysisCycleCount, Math.ceil(initialInventory / Math.max(avgConsumptionPerCycle, 0.01)))) : null;
		const firstDepletionHours = firstDepletionCycle ? firstDepletionCycle * cycleHours : null;
		const firstDepletionDays = firstDepletionHours ? Number((firstDepletionHours / 24).toFixed(2)) : null;
		consumableRows.push({
			resourceType: "消耗品",
			resourceName: String(row?.name || row?.model || "-").trim() || "-",
			resourceId: String(row?.id || row?.code || row?.model || row?.name || "-").trim() || "-",
			initialInventory,
			cumulativeConsumption,
			remainingInventory,
			shortageCount,
			avgConsumptionPerCycle,
			firstDepletionHours,
			firstDepletionDays,
			sourceSheetCount: 1,
			supportModel,
			department: String(row?.department || "-").trim() || "-"
		});
	});

	const personnelRows = Array.isArray(resources.personnel) ? resources.personnel : [];
	const equipmentRows = Array.isArray(resources.equipment) ? resources.equipment : [];
	const totalPersonnel = personnelRows.reduce((sum, row) => sum + Math.max(0, Number(row?.count || 0)), 0);
	const totalEquipment = equipmentRows.reduce((sum, row) => sum + Math.max(0, Number(row?.count || 0)), 0);
	const personnelWorkHours = totalPersonnel * 5.6;
	const equipmentUseHours = totalEquipment * 6.2;
	const personnelSatisfaction = Math.min(100, 76 + totalPersonnel * 0.42);
	const personnelUtilizationRaw = Math.min(100, 58 + totalPersonnel * 0.31);
	const personnelUtilization = personnelSatisfaction >= 100 ? Math.min(personnelUtilizationRaw, 93.5) : personnelUtilizationRaw;
	const equipmentSatisfaction = Math.min(100, 74 + totalEquipment * 0.46);
	const equipmentUtilizationRaw = Math.min(100, 56 + totalEquipment * 0.35);
	const equipmentUtilization = equipmentSatisfaction >= 100 ? Math.min(equipmentUtilizationRaw, 92.8) : equipmentUtilizationRaw;
	const totalShortage = consumableRows.reduce((sum, item) => sum + item.shortageCount, 0);
	const depletedCount = consumableRows.filter((item) => item.shortageCount > 0).length;
	const totalSortiesPerCycle = selectedBasicTasks.reduce((sum, task) => {
		const draft = createBasicTaskDraft(task);
		return sum + Math.max(0, Number(draft.equipmentQuantity || 0));
	}, 0);
	const totalSorties = totalSortiesPerCycle * analysisCycleCount;
	const totalRepairs = totalSorties;
	const initialSpareTotal = consumableRows
		.filter((item) => item.resourceType === "备件")
		.reduce((sum, item) => sum + item.initialInventory, 0);
	const initialConsumableTotal = consumableRows
		.filter((item) => item.resourceType !== "备件")
		.reduce((sum, item) => sum + item.initialInventory, 0);
	const cumulativeConsumptionTotal = consumableRows.reduce((sum, item) => sum + item.cumulativeConsumption, 0);

	const personnelByMajorLevel = new Map();
	personnelRows.forEach((row, index) => {
		const major = String(row?.major || "未分类专业").trim() || "未分类专业";
		const level = String(row?.level || "L-").trim() || "L-";
		const key = `${major}__${level}`;
		const count = Math.max(0, Number(row?.count || 0));
		const prev = personnelByMajorLevel.get(key) || { major, level, totalCount: 0, totalWorkHours: 0, totalWorkCount: 0 };
		prev.totalCount += count;
		prev.totalWorkHours += count * (4.2 + (index % 3) * 0.6);
		prev.totalWorkCount += Math.max(1, Math.round(count * (2.5 + (index % 2) * 0.8)));
		personnelByMajorLevel.set(key, prev);
	});
	const personnelMajorPalette = ["#2563eb", "#16a34a", "#f59e0b", "#dc2626", "#0f766e", "#7c3aed", "#ea580c", "#0891b2"];
	const personnelMajorOptions = Array.from(new Set(Array.from(personnelByMajorLevel.values()).map((item) => item.major)))
		.sort((left, right) => left.localeCompare(right, "zh-Hans-CN"));
	const rawPersonnelMajorFilter = String(state.ui.resourceSupplyPersonnelMajorFilter || "all").trim() || "all";
	const personnelMajorFilter = rawPersonnelMajorFilter === "all" || personnelMajorOptions.includes(rawPersonnelMajorFilter)
		? rawPersonnelMajorFilter
		: "all";
	state.ui.resourceSupplyPersonnelMajorFilter = personnelMajorFilter;
	const personnelMajorColorMap = new Map(
		personnelMajorOptions.map((major, index) => [major, personnelMajorPalette[index % personnelMajorPalette.length]])
	);
	const personnelDetailEntries = Array.from(personnelByMajorLevel.values())
		.map((item) => {
			const satisfaction = Math.min(100, 74 + item.totalCount * 1.8);
			const utilizationRaw = Math.min(100, 58 + item.totalWorkCount * 0.7);
			const utilization = satisfaction >= 100 ? Math.min(utilizationRaw, 94.2) : utilizationRaw;
			return {
				major: item.major,
				level: item.level,
				label: `${item.major} / ${item.level}`,
				totalWorkHours: item.totalWorkHours,
				totalWorkCount: item.totalWorkCount,
				satisfaction,
				utilization,
				color: personnelMajorColorMap.get(item.major) || personnelMajorPalette[0]
			};
		})
		.sort((left, right) => {
			const majorCompare = left.major.localeCompare(right.major, "zh-Hans-CN");
			if (majorCompare !== 0) return majorCompare;
			return left.level.localeCompare(right.level, "zh-Hans-CN", { numeric: true });
		});
	const filteredPersonnelDetailEntries = personnelMajorFilter === "all"
		? personnelDetailEntries
		: personnelDetailEntries.filter((item) => item.major === personnelMajorFilter);
	const personnelDetailRows = filteredPersonnelDetailEntries.map((item) => ({
		item: item.label,
		value: `总工作时长 ${item.totalWorkHours.toFixed(1)}h；总工作次数 ${item.totalWorkCount}`,
		note: `满足率 ${item.satisfaction.toFixed(1)}%；利用率 ${item.utilization.toFixed(1)}%`
	}));
	const personnelDetailPies = filteredPersonnelDetailEntries.flatMap((item) => [
		{ label: `${item.label} 满足率`, value: Number(item.satisfaction.toFixed(1)), color: item.color },
		{ label: `${item.label} 利用率`, value: Number(item.utilization.toFixed(1)), color: item.color }
	]);
	const personnelFilterControlHtml = `
		<div style="display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;">
			<label style="display:flex;align-items:center;gap:8px;font-size:12px;color:#334155;">
				<span>按专业筛选</span>
				<select data-action="filter-resource-supply-major" style="min-width:180px;">
					<option value="all" ${personnelMajorFilter === "all" ? "selected" : ""}>全部专业</option>
					${personnelMajorOptions.map((major) => `<option value="${htmlEscape(major)}" ${personnelMajorFilter === major ? "selected" : ""}>${htmlEscape(major)}</option>`).join("")}
				</select>
			</label>
			<span class="muted" style="font-size:12px;">当前显示 ${filteredPersonnelDetailEntries.length} 项</span>
		</div>
	`;

	const equipmentByType = new Map();
	equipmentRows.forEach((row, index) => {
		const typeName = String(row?.name || row?.model || "设备类型").trim() || "设备类型";
		const count = Math.max(0, Number(row?.count || 0));
		const prev = equipmentByType.get(typeName) || { typeName, totalCount: 0, totalUseHours: 0 };
		prev.totalCount += count;
		prev.totalUseHours += count * (3.8 + (index % 4) * 0.5);
		equipmentByType.set(typeName, prev);
	});
	const equipmentDetailRows = Array.from(equipmentByType.values()).map((item) => {
		const satisfaction = Math.min(100, 70 + item.totalCount * 2.2);
		const utilizationRaw = Math.min(100, 55 + item.totalCount * 1.8);
		const utilization = satisfaction >= 100 ? Math.min(utilizationRaw, 93.6) : utilizationRaw;
		return {
			item: item.typeName,
			value: `满足率 ${satisfaction.toFixed(1)}%；利用率 ${utilization.toFixed(1)}%`,
			note: `使用时长 ${item.totalUseHours.toFixed(1)}h`
		};
	});

	return {
		hideTargetCard: true,
		hideSummaryNote: true,
		hideDetailsTable: true,
		hideChart: true,
		target: `${totalShortage}`,
		targetLabel: "补给缺口总数",
		details: [],
		sections: [
			{
				title: "保障人员统计（按专业、专业等级）",
				chartType: "pie-multi",
				pies: personnelDetailPies,
				controlsHtml: personnelFilterControlHtml,
				headers: { item: "专业 / 专业等级", value: "总工作时长 / 总工作次数", note: "满足率 / 利用率" },
				rows: personnelDetailRows.length > 0 ? personnelDetailRows : [{ item: "暂无人员数据", value: "-", note: personnelMajorFilter === "all" ? "请先维护保障人员" : "当前专业暂无统计数据" }]
			},
			{
				title: "保障设备统计（按类型）",
				headers: { item: "设备类型", value: "满足率 / 利用率", note: "使用时长" },
				rows: equipmentDetailRows.length > 0 ? equipmentDetailRows : [{ item: "暂无设备数据", value: "-", note: "请先维护保障设备" }]
			},
			{
				title: "保障资源补给需求汇总",
				headers: ["分析周期数", "任务剖面周期(小时)", "总飞行架次", "总维修次数", "初始备件总数", "初始消耗品总数", "累计消耗总数", "补给缺口总数", "发生耗尽的资源数"],
				rows: [[
					`${analysisCycleCount}`,
					`${cycleHours}`,
					`${totalSorties}`,
					`${totalRepairs}`,
					`${initialSpareTotal}`,
					`${initialConsumableTotal}`,
					`${cumulativeConsumptionTotal}`,
					`${totalShortage}`,
					`${depletedCount}`
				]]
			},
			{
				title: "资源补给需求明细",
				headers: ["资源名称", "资源ID", "资源类型", "初始库存", "累计消耗", "剩余库存", "补给缺口", "平均每周期消耗", "首次耗尽时间(小时)", "首次耗尽时间(天)", "来源工作表数量"],
				rows: consumableRows.length > 0
					? consumableRows.map((item) => [
						item.resourceName,
						item.resourceId,
						item.resourceType,
						`${item.initialInventory}`,
						`${item.cumulativeConsumption}`,
						`${item.remainingInventory}`,
						`${item.shortageCount}`,
						`${item.avgConsumptionPerCycle}`,
						item.firstDepletionHours === null ? "-" : `${item.firstDepletionHours}`,
						item.firstDepletionDays === null ? "-" : `${item.firstDepletionDays}`,
						`${item.sourceSheetCount}`
					])
					: [["暂无消耗类资源", "-", "-", "0", "0", "0", "0", "0", "-", "-", "0"]]
			}
		]
	};
}

function parseNumericRangeFromText(valueText) {
	const text = String(valueText || "").trim();
	const rangeMatch = text.match(/(-?\d+(?:\.\d+)?)\s*->\s*(-?\d+(?:\.\d+)?)/);
	if (rangeMatch) {
		return {
			base: Number(rangeMatch[1]),
			current: Number(rangeMatch[2]),
			unit: text.replace(rangeMatch[0], "").trim()
		};
	}
	const numberMatch = text.match(/-?\d+(?:\.\d+)?/);
	return {
		base: Number.isFinite(Number(numberMatch?.[0])) ? Number(numberMatch[0]) : 0,
		current: Number.isFinite(Number(numberMatch?.[0])) ? Number(numberMatch[0]) : 0,
		unit: text.replace(numberMatch?.[0] || "", "").trim()
	};
}

function renderRangeComparisonChart(title, rows, fallbackUnit = "", legendLabels = { base: "原方案", current: "辅助优化" }) {
	const safeRows = Array.isArray(rows) ? rows.filter((item) => item && item.label) : [];
	if (safeRows.length === 0) {
		return `<div class="muted" style="margin-bottom:10px;">暂无可用于图表展示的数据。</div>`;
	}
	const maxValue = Math.max(
		1,
		...safeRows.map((item) => Math.max(Number(item.base || 0), Number(item.current || 0)))
	);
	const unitText = String(fallbackUnit || "").trim();
	return `
		<div style="margin-bottom:14px;border:1px solid #e2e8f0;border-radius:10px;background:#fff;padding:12px;">
			<div style="display:flex;align-items:center;justify-content:space-between;gap:8px;margin-bottom:10px;">
				<strong style="font-size:14px;color:#1e293b;">${htmlEscape(title)}</strong>
				<span class="muted" style="font-size:12px;">蓝色：${htmlEscape(legendLabels.base || "原方案")} / 绿色：${htmlEscape(legendLabels.current || "辅助优化")}</span>
			</div>
			<div style="display:flex;flex-direction:column;gap:10px;">
				${safeRows
					.map((item) => {
						const base = Math.max(0, Number(item.base || 0));
						const current = Math.max(0, Number(item.current || 0));
						const baseWidth = Math.max(4, (base / maxValue) * 100);
						const currentWidth = Math.max(4, (current / maxValue) * 100);
						const rowUnit = String(item.unit || unitText).trim();
						return `
							<div>
								<div style="display:flex;align-items:center;justify-content:space-between;gap:8px;margin-bottom:4px;">
									<span style="font-size:12px;color:#334155;max-width:180px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">${htmlEscape(item.label)}</span>
									<span style="font-size:12px;color:#0f172a;font-weight:600;">${base} -> ${current}${rowUnit ? ` ${htmlEscape(rowUnit)}` : ""}</span>
								</div>
								<div style="position:relative;height:10px;border-radius:999px;background:#eef2f7;overflow:hidden;">
									<span style="position:absolute;left:0;top:0;height:100%;width:${baseWidth}%;background:#60a5fa;opacity:.55;"></span>
									<span style="position:absolute;left:0;top:0;height:100%;width:${currentWidth}%;background:#16a34a;opacity:.9;"></span>
								</div>
							</div>
						`;
					})
					.join("")}
			</div>
		</div>
	`;
}

function renderValueBarChart(title, rows, valueLabel = "最优推荐值") {
	const safeRows = Array.isArray(rows) ? rows.filter((row) => Array.isArray(row) && row.length >= 2) : [];
	if (safeRows.length === 0) {
		return `<div class="muted" style="margin-bottom:10px;">暂无可用于图表展示的数据。</div>`;
	}
	const parsedRows = safeRows.map((row) => {
		const label = String(row[0] || "-").trim() || "-";
		const parsed = parseNumericRangeFromText(row[1]);
		return {
			label,
			value: Math.max(0, Number(parsed.current || 0)),
			raw: String(row[1] || "-").trim() || "-"
		};
	});
	const maxValue = Math.max(1, ...parsedRows.map((item) => item.value));
	return `
		<div style="margin-bottom:14px;border:1px solid #e2e8f0;border-radius:10px;background:#fff;padding:12px;">
			<div style="display:flex;align-items:center;justify-content:space-between;gap:8px;margin-bottom:10px;">
				<strong style="font-size:14px;color:#1e293b;">${htmlEscape(title)}</strong>
				<span class="muted" style="font-size:12px;">${htmlEscape(valueLabel)}</span>
			</div>
			<div style="display:flex;flex-direction:column;gap:10px;">
				${parsedRows
					.map((item) => {
						const width = Math.max(6, (item.value / maxValue) * 100);
						return `
							<div>
								<div style="display:flex;align-items:center;justify-content:space-between;gap:8px;margin-bottom:4px;">
									<span style="font-size:12px;color:#334155;max-width:220px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">${htmlEscape(item.label)}</span>
									<span style="font-size:12px;color:#0f172a;font-weight:600;">${htmlEscape(item.raw)}</span>
								</div>
								<div style="position:relative;height:10px;border-radius:999px;background:#eef2f7;overflow:hidden;">
									<span style="position:absolute;left:0;top:0;height:100%;width:${width}%;background:linear-gradient(90deg,#22c55e,#16a34a);"></span>
								</div>
							</div>
						`;
					})
					.join("")}
			</div>
		</div>
	`;
}

function parseMinuteRangeText(text) {
	const match = String(text || "").match(/(\d+)\s*-\s*(\d+)\s*min/i);
	if (!match) return null;
	const start = Number(match[1]);
	const end = Number(match[2]);
	if (!Number.isFinite(start) || !Number.isFinite(end) || end <= start) return null;
	return { start, end };
}

function parseHHmmToMinutes(text) {
	const match = String(text || "").match(/^(\d{1,2}):(\d{2})$/);
	if (!match) return null;
	const hour = Number(match[1]);
	const minute = Number(match[2]);
	if (!Number.isFinite(hour) || !Number.isFinite(minute)) return null;
	return hour * 60 + minute;
}

function renderPhaseTimelineChart(title, phases, phaseColors) {
	const rows = Array.isArray(phases) ? phases : [];
	if (rows.length === 0) {
		return `<div class="muted" style="margin-bottom:10px;">暂无可用于图表展示的数据。</div>`;
	}
	const allRanges = rows.flatMap((row) => row.ranges || []);
	const minStart = Math.min(...allRanges.map((range) => range.start));
	const maxEnd = Math.max(...allRanges.map((range) => range.end));
	const span = Math.max(1, maxEnd - minStart);
	const legendHtml = phaseColors
		.map((item) => `<span style="display:inline-flex;align-items:center;gap:6px;font-size:12px;color:#475569;"><span style="display:inline-block;width:10px;height:10px;border-radius:999px;background:${item.color};"></span>${htmlEscape(item.label)}</span>`)
		.join("<span class='muted' style='font-size:12px;'>|</span>");
	return `
		<div style="margin-bottom:14px;border:1px solid #e2e8f0;border-radius:10px;background:#fff;padding:12px;">
			<div style="display:flex;align-items:center;justify-content:space-between;gap:8px;margin-bottom:10px;">
				<strong style="font-size:14px;color:#1e293b;">${htmlEscape(title)}</strong>
				<span>${legendHtml}</span>
			</div>
			<div style="display:flex;flex-direction:column;gap:10px;">
				${rows
					.map((row) => {
						const segments = (row.ranges || [])
							.map((range, index) => {
								const left = ((range.start - minStart) / span) * 100;
								const width = Math.max(2, ((range.end - range.start) / span) * 100);
								const color = phaseColors[index % phaseColors.length]?.color || "#60a5fa";
								return `<span title="${htmlEscape(range.label)} ${range.start}-${range.end}" style="position:absolute;left:${left}%;top:0;height:100%;width:${width}%;background:${color};border-radius:999px;opacity:.92;"></span>`;
							})
							.join("");
						return `
							<div>
								<div style="display:flex;align-items:center;justify-content:space-between;gap:8px;margin-bottom:4px;">
									<span style="font-size:12px;color:#334155;">${htmlEscape(row.label)}</span>
									<span class="muted" style="font-size:12px;">${row.rangeLabel}</span>
								</div>
								<div style="position:relative;height:14px;border-radius:999px;background:#eef2f7;border:1px solid #e2e8f0;overflow:hidden;">${segments}</div>
							</div>
						`;
					})
					.join("")}
			</div>
		</div>
	`;
}

function renderMultiPieCharts(title, pies = []) {
	const safePies = Array.isArray(pies)
		? pies
			.map((item) => ({
				label: String(item?.label || "-").trim() || "-",
				value: Math.max(0, Math.min(100, Number(item?.value || 0))),
				color: String(item?.color || "").trim()
			}))
			.filter((item) => Number.isFinite(item.value))
		: [];
	if (safePies.length === 0) {
		return `<div class="muted" style="margin-bottom:10px;">暂无可用于图表展示的数据。</div>`;
	}
	const colors = ["#2563eb", "#22c55e", "#f59e0b", "#8b5cf6", "#ef4444"];
	return `
		<div style="margin-bottom:14px;border:1px solid #e2e8f0;border-radius:10px;background:#fff;padding:12px;">
			<div style="display:flex;align-items:center;justify-content:space-between;gap:8px;margin-bottom:10px;">
				<strong style="font-size:14px;color:#1e293b;">${htmlEscape(title)}</strong>
				<span class="muted" style="font-size:12px;">扇形图：占比 / 未占比</span>
			</div>
			<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:12px;">
				${safePies
					.map((item, index) => {
						const color = item.color || colors[index % colors.length];
						const value = Number(item.value.toFixed(1));
						return `
							<div style="border:1px solid #e2e8f0;border-radius:10px;padding:10px;background:#fff;">
								<div style="font-size:12px;color:#334155;margin-bottom:8px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">${htmlEscape(item.label)}</div>
								<div style="display:flex;align-items:center;gap:10px;">
									<div style="width:72px;height:72px;border-radius:50%;background:conic-gradient(${color} ${value}%, #e2e8f0 ${value}% 100%);"></div>
									<div>
										<div style="font-size:20px;font-weight:700;color:#0f172a;line-height:1;">${value}%</div>
										<div class="muted" style="font-size:12px;margin-top:6px;">剩余 ${(100 - value).toFixed(1)}%</div>
									</div>
								</div>
							</div>
						`;
					})
					.join("")}
			</div>
		</div>
	`;
}

function renderStateSwitch(pageKey) {
	const curr = state.pageState[pageKey];
	const states = ["loading", "empty", "error", "no-permission", "success"];
	return `
		<div class="state-toolbar">
			${states
				.map(
					(item) =>
						`<button class="state-chip ${item === curr ? "active" : ""}" data-action="set-page-state" data-page="${pageKey}" data-value="${item}">${item}</button>`
				)
				.join("")}
		</div>
	`;
}

function renderPageStateBlock(pageKey, bodyRenderer) {
	const status = state.pageState[pageKey];
	if (status === "loading") {
		if (["experiments", "visual", "mc"].includes(pageKey)) {
			return "";
		}
		return `<div class="loading">加载中，请稍候...</div>`;
	}
	if (status === "empty") {
		return `<div class="empty">暂无数据，点击“新增”开始录入。</div>`;
	}
	if (status === "error") {
		return `<div class="error-state">请求失败，请点击重试。<div style="margin-top: 8px;"><button data-action="retry-state" data-page="${pageKey}">重试</button></div></div>`;
	}
	if (status === "no-permission") {
		return `<div class="no-perm">当前账号无权限访问该页面。<div style="margin-top: 8px;"><button class="btn-link" data-nav="/">返回导航</button></div></div>`;
	}
	return bodyRenderer();
}

function imageFallback(text) {
	return `data:image/svg+xml;utf8,${encodeURIComponent(`<svg xmlns='http://www.w3.org/2000/svg' width='600' height='320'><rect width='100%' height='100%' fill='#eaf0fa'/><text x='50%' y='50%' dominant-baseline='middle' text-anchor='middle' font-size='28' fill='#6a7280'>${text}</text></svg>`)}`;
}

function ensureShipTypeDeckSelectionState() {
	if (!state.ui || typeof state.ui !== "object") {
		state.ui = {};
	}
	const shipTypeIdSet = new Set((state.shipTypes || []).map((item) => String(item?.id || "").trim()).filter(Boolean));
	const preferredId = String(state.ui.shipTypeDeckSelectedId || state.ui.deckShipTypeFilter || "").trim();
	const selectedId = shipTypeIdSet.has(preferredId) ? preferredId : String(state.shipTypes[0]?.id || "").trim();
	state.ui.shipTypeDeckSelectedId = selectedId;
	if (selectedId) {
		state.ui.deckShipTypeFilter = selectedId;
	}
	return selectedId;
}

function renderShipTypeModelingPage() {
	const isReadOnly = getCurrentRole() === ROLE.USER;
	const selectedShipTypeId = ensureShipTypeDeckSelectionState();
	const selectedIds = new Set(state.ui.selectedShipTypeIds || []);
	const allSelected = state.shipTypes.length > 0 && state.shipTypes.every(item => selectedIds.has(item.id));
	const tableRows = state.shipTypes.map((item, index) => `
		<tr class="shiptype-table-row ${selectedShipTypeId === item.id ? "active-shiptype-row" : ""}" style="cursor:pointer;" data-action="select-shiptype-modeling" data-id="${item.id}">
			<td onclick="event.stopPropagation()"><input type="checkbox" data-action="toggle-shiptype-select" data-id="${item.id}" ${selectedIds.has(item.id) ? "checked" : ""} /></td>
			<td>${index + 1}</td>
			<td class="shiptype-name-cell">${htmlEscape(item.name || "")}</td>
			<td class="shiptype-actions-cell">
				<div class="shiptype-action-group">
					<button data-action="edit-shiptype" data-id="${item.id}" onclick="event.stopPropagation()">编辑</button>
					<button class="btn-danger" data-action="delete-shiptype" data-id="${item.id}" onclick="event.stopPropagation()">删除</button>
				</div>
			</td>
		</tr>
	`).join("");

	const shipTypeTableCard = `
		<div class="card projects-list-card" style="height:100%;display:flex;flex-direction:column;">
			<div class="page-head" style="margin-bottom:10px;">
				<h3 style="margin:0;">船型列表</h3>
			</div>
			<div class="toolbar">
				<button class="btn-primary" data-action="new-shiptype">新建</button>
				<button class="btn-danger" data-action="delete-shiptype-batch">批量删除</button>
			</div>
			<div class="table-wrap projects-table-wrap" style="margin-top:8px;flex:1;min-height:0;">
				<table class="shiptype-table" style="table-layout: fixed; width: 100%;">
					<thead>
						<tr>
							<th style="width:44px;"><input type="checkbox" data-action="toggle-shiptype-select-all" ${allSelected ? "checked" : ""} /></th>
							<th style="width:44px;white-space:nowrap;">序号</th>
							<th class="shiptype-name-cell">船型名称</th>
							<th style="width:126px;">操作</th>
						</tr>
					</thead>
					<tbody>
						${tableRows || "<tr><td colspan='4' class='muted'>暂无船型数据</td></tr>"}
					</tbody>
				</table>
			</div>
		</div>
	`;

	const deckWorkspaceHtml = selectedShipTypeId
		? renderDeckModelingPage({
			showHeader: false,
			showShipTypeFilter: false,
			heading: "舰面建模",
			fixedShipTypeId: selectedShipTypeId
		})
		: `<div class="card" style="height:100%;display:flex;align-items:center;justify-content:center;"><div class="empty">请先新建船型，再维护舰面建模四个部分。</div></div>`;

	return `
		<div class="projects-page page ${isReadOnly ? "shiptype-deck-readonly" : ""}">
			<div class="page-head">
				<h2>船型与舰面建模</h2>
				<button class="btn-link" data-nav="/">返回导航</button>
			</div>
			${isReadOnly ? `<div class="muted shiptype-deck-readonly-hint">当前为只读模式，仅可查看船型与舰面建模数据。</div>` : ""}
			<div style="display:grid;grid-template-columns:minmax(420px,520px) minmax(0,1fr);gap:12px;align-items:stretch;min-height:720px;">
				${shipTypeTableCard}
				<div style="min-width:0;">${deckWorkspaceHtml}</div>
			</div>
		</div>
	`;
}

function ensureInitialLayoutTreeUiState() {
	if (!state.ui || typeof state.ui !== "object") {
		state.ui = {};
	}
	if (!Array.isArray(state.ui.collapsedInitialLayoutShipTypeIds)) {
		state.ui.collapsedInitialLayoutShipTypeIds = [];
	}
	const validShipTypeIds = new Set((Array.isArray(state.shipTypes) ? state.shipTypes : []).map((item) => String(item?.id || "").trim()).filter(Boolean));
	state.ui.collapsedInitialLayoutShipTypeIds = state.ui.collapsedInitialLayoutShipTypeIds.filter((id) => validShipTypeIds.has(String(id || "").trim()));
	return state.ui.collapsedInitialLayoutShipTypeIds;
}

function renderInitialLayoutModelingPage() {
	ensureInitialLayoutTreeUiState();
	if (!state.ui.initialLayoutSelectedShipType && state.shipTypes.length > 0) {
		state.ui.initialLayoutSelectedShipType = state.shipTypes[0].id;
	}

	const getPlanShortName = (planName, shipTypeId) => {
		const rawName = String(planName || "").trim();
		if (!rawName) return "";
		const shipTypeName = state.shipTypes.find((item) => String(item?.id || "").trim() === String(shipTypeId || "").trim())?.name || "";
		if (shipTypeName && rawName.startsWith(`${shipTypeName}-`)) {
			return rawName.slice(shipTypeName.length + 1).trim();
		}
		return rawName.replace(/^\d+号船-/, "").trim();
	};

	const allPlans = Array.isArray(state.initialLayoutPlans) ? state.initialLayoutPlans : [];
	const currentPlan = allPlans.find((item) => String(item?.id || "").trim() === String(state.ui.initialLayoutSelectedPlanId || "").trim()) || null;
	if (currentPlan?.shipTypeId) {
		state.ui.initialLayoutSelectedShipType = String(currentPlan.shipTypeId || "").trim();
	}

	const selectedShipType = String(state.ui.initialLayoutSelectedShipType || state.shipTypes[0]?.id || "").trim();
	const currentShipPlans = allPlans.filter((item) => String(item?.shipTypeId || "").trim() === selectedShipType);
	const allPlanIds = new Set(allPlans.map((item) => String(item?.id || "").trim()).filter(Boolean));
	if (!allPlanIds.has(String(state.ui.initialLayoutSelectedPlanId || "").trim())) {
		state.ui.initialLayoutSelectedPlanId = currentShipPlans[0]?.id || "";
		state.ui.selectedInitialLayoutPlanIds = [];
		state.ui.selectedInitialLayoutItemIds = [];
	}

	const selectedPlanId = String(state.ui.initialLayoutSelectedPlanId || "").trim();
	const selectedPlan = allPlans.find((item) => String(item?.id || "").trim() === selectedPlanId) || null;
	const detailShipTypeId = String(selectedPlan?.shipTypeId || selectedShipType || "").trim();
	const filteredItems = state.initialLayoutItems.filter((item) => String(item?.layoutPlanId || "").trim() === selectedPlanId);
	const supportStationOptions = getInitialLayoutSupportStationOptions(detailShipTypeId);
	const parkingStationOptions = getInitialLayoutParkingStationCodeOptions(detailShipTypeId);
	const selectedSupportMap = new Map();
	const selectedParkingMap = new Map();
	filteredItems.forEach((item) => {
		const stationKind = String(item.stationKind || "").trim();
		const stationCode = String(item.stationCode || "").trim();
		const supportCode = stationKind === "support" ? stationCode : String(item.supportStation || "").trim();
		const parkingCode = stationKind === "parking" ? stationCode : String(item.parkingStation || "").trim();
		if (supportCode) selectedSupportMap.set(supportCode, item);
		if (parkingCode) selectedParkingMap.set(parkingCode, item);
	});
    const aircraftTypeOptions = state.aircraftTypes.map((aircraft) => String(aircraft?.name || "").trim()).filter(Boolean);
    const renderAircraftTypeSelect = (item, stationKind, stationCode, enabled) => `
		<select data-action="change-initiallayout-station-aircraft" data-kind="${stationKind}" data-code="${htmlEscape(stationCode)}" style="width:100%;" ${enabled ? "" : "disabled"}>
			<option value="">请选择机型</option>
			${aircraftTypeOptions.map((name) => `<option value="${htmlEscape(name)}" ${String(item?.aircraftType || "") === name ? "selected" : ""}>${htmlEscape(name)}</option>`).join("")}
		</select>
	`;

	const collapsedShipTypes = new Set(state.ui.collapsedInitialLayoutShipTypeIds || []);
	const treeHtml = state.shipTypes.map((shipType) => {
		const shipTypeId = String(shipType?.id || "").trim();
		const shipPlans = allPlans.filter((item) => String(item?.shipTypeId || "").trim() === shipTypeId);
		const isShipSelected = shipTypeId === selectedShipType;
		const isCollapsed = shipPlans.length > 0 ? collapsedShipTypes.has(shipTypeId) : false;
		return `
			<div class="tree-node-item">
				<div class="tree-node-label ${isShipSelected ? "selected" : ""}" data-action="select-initiallayout-shiptype" data-id="${htmlEscape(shipTypeId)}">
					<span class="tree-node-toggle" ${shipPlans.length > 0 ? `data-action="toggle-initiallayout-shiptype" data-id="${htmlEscape(shipTypeId)}"` : ""}>${shipPlans.length > 0 ? (isCollapsed ? "▶" : "▼") : "•"}</span>
					<span class="tree-node-text">${htmlEscape(String(shipType?.name || "未命名船型"))}</span>
				</div>
				${shipPlans.length > 0 && !isCollapsed ? `<div class="tree-node-children">
					${shipPlans.map((plan) => {
						const planId = String(plan?.id || "").trim();
						const isSelected = planId === selectedPlanId;
						const shortName = getPlanShortName(plan?.name || "", shipTypeId) || String(plan?.name || "未命名方案").trim();
						return `
							<div class="tree-node-item">
								<div class="tree-node-label ${isSelected ? "selected" : ""}" data-action="select-initiallayout-plan" data-id="${htmlEscape(planId)}">
									<span class="tree-node-toggle">•</span>
									<span class="tree-node-text initial-layout-plan-name" title="${htmlEscape(String(plan?.name || ""))}">${htmlEscape(shortName)}</span>
								</div>
							</div>`;
					}).join("") || "<div class='muted' style='padding:8px 12px;'>暂无布列方案</div>"}
				</div>` : ""}
			</div>`;
	}).join("");

	return `
		<div class="projects-page page">
			<div class="page-head">
				<h2>初始布列建模</h2>
				<button class="btn-link" data-nav="/">返回导航</button>
			</div>
			

			<div class="organization-layout initial-layout-layout">
				<div class="tree-container initial-layout-tree-panel">
					<div class="page-head" style="margin-bottom:10px;">
						<h3 style="margin:0;">初始布列方案树</h3>
					</div>
					<div class="toolbar initial-layout-tree-toolbar">
						<button class="btn-primary" data-action="new-initiallayout-plan">新建</button>
						<button class="btn-danger" data-action="delete-initiallayout-plan" data-id="${htmlEscape(selectedPlanId)}" ${selectedPlanId ? "" : "disabled"}>删除</button>
					</div>
					<div class="muted initial-layout-tree-hint">当前新建目标船型：${htmlEscape(state.shipTypes.find((item) => String(item?.id || "").trim() === selectedShipType)?.name || "未选择")}</div>
					${treeHtml || "<div class='muted' style='padding:8px 12px;'>暂无船型数据</div>"}
				</div>

				<div class="detail-panel">
					<div class="card projects-list-card initial-layout-detail-card" style="display:flex;flex-direction:column;overflow:hidden;margin:0;">
						<div class="page-head" style="margin-bottom:10px;">
							<h3 style="margin:0;">详情列表</h3>
						</div>
						${!selectedPlan ? `
							<div class="empty" style="flex:1;display:flex;align-items:center;justify-content:center;">请先从左侧树选择布列方案</div>
						` : `
							<div style="display:grid;grid-template-columns:1fr 1fr;gap:12px;flex:1;min-height:0;">
						<div style="display:flex;flex-direction:column;min-height:0;">
							<h4 style="margin:0 0 8px 0;">保障站位编号</h4>
							<div class="table-wrap projects-table-wrap" style="min-height:0;flex:1;">
							<table style="table-layout: fixed; width: 100%;">
								<thead>
									<tr>
										<th style="width:44px;">选择</th>
										<th style="width:140px;">保障站位编号</th>
										<th>机型</th>
									</tr>
								</thead>
								<tbody>
									${supportStationOptions.map((row) => {
										const code = String(row.code || row.name || "").trim();
										const selectedItem = selectedSupportMap.get(code);
										const checked = Boolean(selectedItem);
										return `
											<tr>
												<td><input type="checkbox" data-action="toggle-initiallayout-station-enabled" data-kind="support" data-code="${htmlEscape(code)}" ${checked ? "checked" : ""} ${selectedPlanId ? "" : "disabled"} /></td>
												<td title="${htmlEscape(code)}">${htmlEscape(code || "-")}</td>
												<td>${renderAircraftTypeSelect(selectedItem, "support", code, checked && Boolean(selectedPlanId))}</td>
											</tr>
										`;
									}).join("") || "<tr><td colspan='3' class='muted'>暂无保障站位数据</td></tr>"}
								</tbody>
							</table>
							</div>
						</div>
						<div style="display:flex;flex-direction:column;min-height:0;">
							<h4 style="margin:0 0 8px 0;">非保障停机站位编号</h4>
							<div class="table-wrap projects-table-wrap" style="min-height:0;flex:1;">
							<table style="table-layout: fixed; width: 100%;">
								<thead>
									<tr>
										<th style="width:44px;">选择</th>
										<th style="width:140px;">非保障停机站位编号</th>
										<th>机型</th>
									</tr>
								</thead>
								<tbody>
									${parkingStationOptions.map((row) => {
										const code = String(row.code || "").trim();
										const selectedItem = selectedParkingMap.get(code);
										const checked = Boolean(selectedItem);
										return `
											<tr>
												<td><input type="checkbox" data-action="toggle-initiallayout-station-enabled" data-kind="parking" data-code="${htmlEscape(code)}" ${checked ? "checked" : ""} ${selectedPlanId ? "" : "disabled"} /></td>
												<td>${htmlEscape(code || "-")}</td>
												<td>${renderAircraftTypeSelect(selectedItem, "parking", code, checked && Boolean(selectedPlanId))}</td>
											</tr>
										`;
									}).join("") || "<tr><td colspan='3' class='muted'>暂无非保障停机站位数据</td></tr>"}
								</tbody>
							</table>
							</div>
						</div>
					</div>
							</div>
						`}
					</div>
				</div>
			</div>
		</div>
	`;
}

function renderLayout(content, route) {
	if (route === "/login") return content;
	const isHomeRoute = route === "/";
	const role = getCurrentRole();
	const hideTopContext = route === "/" || route === "/plans" || route === "/projects" || route === "/admin/users";
	const showContextNearLogout =
		route.startsWith("/modeling/") ||
		route.startsWith("/simulation/") ||
		route === "/plans/analysis" ||
		route === "/plans/optimization" ||
		route === "/plans/generation" ||
		route.startsWith("/optimization/");
	const currentProjectName = state.projects.find((project) => project.id === state.currentProjectId)?.name || "未选择";
	const currentPlanLabel = getCurrentPlanContextLabel();
	const currentPlanName = getCurrentPlanContextValue();
	const currentShipTypeName = state.currentProjectId ? getProjectShipTypeDisplayName(state.currentProjectId) : "未选择";
	const currentLayoutPlanName = state.currentProjectId ? getInitialLayoutPlanShortDisplayName(getProjectLayoutPlanDisplayName(state.currentProjectId)) : "未选择";
	const showUserProjectContext = role === ROLE.USER && Boolean(state.currentProjectId) && route !== "/projects";
	const topbar = `
		<header class="topbar">
			<div class="left">
				<div class="brand">${[APP_CONFIG.systemName, APP_CONFIG.version].filter((item) => String(item || "").trim()).join(" ")}</div>
				${
					hideTopContext || showContextNearLogout || role === ROLE.DATA_ADMIN || role === ROLE.USER
						? ""
						: `
							<span class="topbar-static">项目：${htmlEscape(currentProjectName)}</span>
							<span class="topbar-static">${currentPlanLabel}：${htmlEscape(currentPlanName)}</span>
						`
				}
			</div>
			<div class="right">
				${
					showUserProjectContext
						? `<span class="topbar-static">项目：${htmlEscape(currentProjectName)}</span><span class="topbar-static">船型：${htmlEscape(currentShipTypeName)}</span><span class="topbar-static">布列方案：${htmlEscape(currentLayoutPlanName)}</span>`
						: ""
				}
				<div class="user-avatar" data-action="logout" title="退出系统">
					${state.auth.username.charAt(0).toUpperCase()}
				</div>
			</div>
		</header>
	`;

	return `
		<div class="layout">
			${topbar}
			<div class="main ${isHomeRoute ? "main-home" : ""}">
				<main class="content ${isHomeRoute ? "content-home" : ""}">${content}</main>
			</div>
		</div>
	`;
}

