	const selectedNodeFaultSampleDistributionConfig = getEquipmentFaultSampleDistributionParamConfig(selectedNodeFaultSampleDistribution);
	const selectedNodeFaultSampleDistributionParam1 = String(selectedNode?.faultSampleDistributionParam1 || "").trim();
	const selectedNodeFaultSampleDistributionParam2 = String(selectedNode?.faultSampleDistributionParam2 || "").trim();
	const selectedNodeIsTestable = selectedNodeIsLru ? Boolean(selectedNode?.isTestable) : false;
