	document.querySelectorAll("[data-action='toggle-initiallayout-station-enabled']").forEach((el) => {
		el.addEventListener("change", () => {
			const selectedPlanId = String(state.ui.initialLayoutSelectedPlanId || "").trim();
			const stationKind = String(el.dataset.kind || "").trim();
			const stationCode = String(el.dataset.code || "").trim();
			if (!selectedPlanId) {
				showToast("请先选择布列方案");
				render();
				return;
			}
			if (!stationCode || !["support", "parking"].includes(stationKind)) return;
			const matchedIndex = state.initialLayoutItems.findIndex((item) => {
				if (String(item?.layoutPlanId || "").trim() !== selectedPlanId) return false;
				const itemKind = String(item?.stationKind || "").trim();
				const itemCode = String(item?.stationCode || "").trim();
				const legacyCode = stationKind === "support" ? String(item?.supportStation || "").trim() : String(item?.parkingStation || "").trim();
				if (itemKind === stationKind && itemCode === stationCode) return true;
				if (!itemKind && legacyCode === stationCode) return true;
				return false;
			});
			if (el.checked) {
				if (matchedIndex < 0) {
					const defaultAircraftType = String(state.aircraftTypes[0]?.name || "").trim();
					state.initialLayoutItems.push({
						id: uid("ili"),
						layoutPlanId: selectedPlanId,
						stationKind,
						stationCode,
						supportStation: stationKind === "support" ? stationCode : "",
						parkingStation: stationKind === "parking" ? stationCode : "",
						aircraftType: defaultAircraftType
					});
				}
			} else if (matchedIndex >= 0) {
				state.initialLayoutItems.splice(matchedIndex, 1);
			}
			render();
		});
	});

	document.querySelectorAll("[data-action='change-initiallayout-station-aircraft']").forEach((el) => {
		el.addEventListener("change", () => {
			const selectedPlanId = String(state.ui.initialLayoutSelectedPlanId || "").trim();
			const stationKind = String(el.dataset.kind || "").trim();
			const stationCode = String(el.dataset.code || "").trim();
			const aircraftType = String(el.value || "").trim();
			if (!selectedPlanId || !stationCode || !["support", "parking"].includes(stationKind)) return;
			const target = state.initialLayoutItems.find((item) => {
				if (String(item?.layoutPlanId || "").trim() !== selectedPlanId) return false;
				const itemKind = String(item?.stationKind || "").trim();
				const itemCode = String(item?.stationCode || "").trim();
				const legacyCode = stationKind === "support" ? String(item?.supportStation || "").trim() : String(item?.parkingStation || "").trim();
				if (itemKind === stationKind && itemCode === stationCode) return true;
				if (!itemKind && legacyCode === stationCode) return true;
				return false;
			});
			if (!target) return;
			target.stationKind = stationKind;
			target.stationCode = stationCode;
			target.supportStation = stationKind === "support" ? stationCode : "";
			target.parkingStation = stationKind === "parking" ? stationCode : "";
			target.aircraftType = aircraftType;
			render();
		});
	});

