	document.querySelectorAll("[data-action='save-initiallayout-item']").forEach((el) => {
		el.addEventListener("click", () => {
			const parkingInput = document.getElementById("initiallayoutItemModalParkingStation").value.trim();
			const aircraftInput = document.getElementById("initiallayoutItemModalAircraftType").value.trim();
			if (!parkingInput) {
				showToast(`甲板基本${DECK_PARKING_TYPE_LABEL}不能为空`);
				return;
			}
			if (!aircraftInput) {
				showToast("飞机类型不能为空");
				return;
			}
			const payload = state.ui.modal.payload;
			const currentPlanId = String(payload.layoutPlanId || state.ui.initialLayoutSelectedPlanId || "").trim();
			const duplicated = state.initialLayoutItems.some((item) => {
				if (String(item?.layoutPlanId || "").trim() !== currentPlanId) return false;
				if (String(item?.parkingStation || "").trim() !== parkingInput) return false;
				if (payload.id && String(item?.id || "").trim() === String(payload.id || "").trim()) return false;
				return true;
			});
			if (duplicated) {
				showToast(`当前方案中该站位编号已存在，请选择其他${DECK_PARKING_TYPE_LABEL}`);
				return;
			}
			if (payload.id) {
				const idx = state.initialLayoutItems.findIndex(item => item.id === payload.id);
				if (idx >= 0) {
					state.initialLayoutItems[idx] = { ...state.initialLayoutItems[idx], aircraftType: aircraftInput, parkingStation: parkingInput };
				}
			} else {
				state.initialLayoutItems.push({
					id: uid("ili"),
					layoutPlanId: currentPlanId,
					aircraftType: aircraftInput,
					parkingStation: parkingInput
				});
			}
			closeModal();
			showToast("保存成功");
			render();
		});
	});

