	document.querySelectorAll("[data-action='toggle-equipment-aircraft-info-select-all']").forEach((el) => {
		el.addEventListener("change", () => {
			const selectedNode = findNodeById(state.equipmentTree, state.selectedEquipmentId || "");
			if (!selectedNode || selectedNode.type !== "aircraft") return;
			const rows = getEquipmentAircraftInfoRows(selectedNode);
			ensureEquipmentAircraftInfoSelectionState();
			state.ui.selectedEquipmentAircraftInfoIds[selectedNode.id] = el.checked ? rows.map((row) => row.id) : [];
			render();
		});
	});

	document.querySelectorAll("[data-action='toggle-equipment-aircraft-info-select']").forEach((el) => {
		el.addEventListener("change", () => {
			const selectedNode = findNodeById(state.equipmentTree, state.selectedEquipmentId || "");
			if (!selectedNode || selectedNode.type !== "aircraft") return;
			ensureEquipmentAircraftInfoSelectionState();
			const selectedSet = new Set((state.ui.selectedEquipmentAircraftInfoIds[selectedNode.id] || []).map((id) => String(id || "").trim()));
			const rowId = String(el.dataset.rowId || "").trim();
			if (!rowId) return;
			if (el.checked) {
				selectedSet.add(rowId);
			} else {
				selectedSet.delete(rowId);
			}
			state.ui.selectedEquipmentAircraftInfoIds[selectedNode.id] = Array.from(selectedSet);
			render();
		});
	});

	const equipmentDetailIsLruVisibleInput = document.getElementById("equipmentDetailIsLruVisible");
