	const equipmentDetailFaultSampleDistributionParam2Wrap = document.getElementById("equipmentDetailFaultSampleDistributionParam2Wrap");
	const equipmentDetailFaultSampleDistributionParam2Label = document.getElementById("equipmentDetailFaultSampleDistributionParam2Label");
