	const basicActivityImportSubmitBtn = document.querySelector("[data-action='basic-activity-import-submit']");
	if (basicActivityImportSubmitBtn) {
		basicActivityImportSubmitBtn.addEventListener("click", async () => {
			const errEl = document.getElementById("basicActivityImportErr");
			const importMeta = getBasicActivityLibraryTypeMeta(document.getElementById("basicActivityImportType")?.value, "basic_ops");
			const file = document.getElementById("basicActivityImportFileInput")?.files?.[0];
			if (errEl) {
				errEl.style.display = "none";
				errEl.textContent = "";
			}
			if (!file) {
				if (errEl) {
					errEl.style.display = "block";
					errEl.textContent = "请先上传文件。";
				}
				return;
			}
			try {
				const { importedItems, rowErrors } = await importBasicActivitiesByExcel(importMeta.activityType, file);
				importedItems.forEach((item) => {
					upsertBasicActivityItem(importMeta.activityType, { ...item, libraryTypeKey: importMeta.key });
				});
				if (rowErrors.length > 0) {
					showToast(`导入完成：成功 ${importedItems.length} 条，失败 ${rowErrors.length} 条`);
				} else {
					showToast(`导入成功：${importedItems.length} 条`);
				}
				closeModal();
			} catch (error) {
				if (errEl) {
					errEl.style.display = "block";
					errEl.textContent = error.message || "导入失败，请检查文件格式后重试。";
				}
			}
		});
	}

