	document.querySelectorAll("[data-action='open-org-resource-modal']").forEach((el) => {
		el.addEventListener("click", () => {
			const tableKey = el.dataset.table || "";
			const rowId = el.dataset.id || "";
			if (!ORG_RESOURCE_TABLE_CONFIG[tableKey]) return;
			const resources = ensureOrgResourceModelState();
			const selectedNode = findOrgNodeById(state.organizationTree, state.selectedOrgId);
			const selectedDepartmentName = isOrgResourceTreeScopedTable(tableKey) ? String(selectedNode?.name || "").trim() : "";
			const selectedEquipmentNode = getOrgResourceEquipmentScopeNode(tableKey);
			const payloadItem = rowId
				? resources[tableKey].find((item) => item.id === rowId)
				: { ...createOrgResourceDefaultItem(tableKey, selectedDepartmentName, selectedEquipmentNode), id: "" };
			if (!payloadItem) {
				showToast("未找到待编辑数据");
				return;
			}
			const rowDepartment = String(payloadItem.department || "").trim();
			if (isOrgResourceTreeScopedTable(tableKey) && rowId && selectedDepartmentName && rowDepartment && rowDepartment !== selectedDepartmentName) {
				const continueEdit = window.confirm(
					`提示：当前选中节点为“${selectedDepartmentName}”，该数据所属部门为“${rowDepartment}”。\n是否继续编辑？`
				);
				if (!continueEdit) return;
			}
			const rowEquipmentNodeName = String(payloadItem.equipmentNodeName || "").trim();
			const selectedEquipmentNodeName = String(selectedEquipmentNode?.name || "").trim();
			if (isOrgResourceEquipmentTreeScopedTable(tableKey) && rowId && selectedEquipmentNodeName && rowEquipmentNodeName && rowEquipmentNodeName !== selectedEquipmentNodeName) {
				const continueEdit = window.confirm(
					`提示：当前选中装备节点为“${selectedEquipmentNodeName}”，该数据关联节点为“${rowEquipmentNodeName}”。\n是否继续编辑？`
				);
				if (!continueEdit) return;
			}
			openModal("org-resource-edit", { tableKey, item: payloadItem });
		});
	});

	document.querySelectorAll("[data-action='delete-org-resource-row']").forEach((el) => {
		el.addEventListener("click", () => {
			const tableKey = el.dataset.table || "";
			const rowId = el.dataset.id || "";
			if (!ORG_RESOURCE_TABLE_CONFIG[tableKey] || !rowId) return;
			const resources = ensureOrgResourceModelState();
			const rowItem = (resources[tableKey] || []).find((item) => item.id === rowId);
			const selectedDepartmentName = isOrgResourceTreeScopedTable(tableKey)
				? String(findOrgNodeById(state.organizationTree, state.selectedOrgId)?.name || "").trim()
				: "";
			const selectedEquipmentNodeName = isOrgResourceEquipmentTreeScopedTable(tableKey)
				? String(getOrgResourceEquipmentScopeNode(tableKey)?.name || "").trim()
				: "";
			const rowDepartment = String(rowItem?.department || "").trim();
			const rowEquipmentNodeName = String(rowItem?.equipmentNodeName || "").trim();
			const warningText =
				selectedDepartmentName && rowDepartment && rowDepartment !== selectedDepartmentName
					? `\n提示：该数据所属部门为“${rowDepartment}”，不是当前选中节点“${selectedDepartmentName}”。`
					: selectedEquipmentNodeName && rowEquipmentNodeName && rowEquipmentNodeName !== selectedEquipmentNodeName
						? `\n提示：该数据关联装备节点为“${rowEquipmentNodeName}”，不是当前选中节点“${selectedEquipmentNodeName}”。`
					: "";
			if (!window.confirm(`确认删除该行数据？${warningText}`)) return;
			removeOrgResourceRows(tableKey, new Set([rowId]));
			showToast("删除成功");
			render();
		});
	});

	document.querySelectorAll("[data-action='delete-org-resource-batch']").forEach((el) => {
		el.addEventListener("click", () => {
			const tableKey = el.dataset.table || "";
			if (!ORG_RESOURCE_TABLE_CONFIG[tableKey]) return;
			ensureOrgResourceSelectedState();
			const visibleRows = getOrgResourceViewMetaByTable(tableKey).filteredRows;
			const visibleIdSet = new Set(visibleRows.map((item) => item.id));
			const selectedIds = new Set((state.ui.selectedOrgResourceIds[tableKey] || []).filter((id) => visibleIdSet.has(id)));
			if (selectedIds.size === 0) {
				showToast(isOrgResourceTreeScopedTable(tableKey) ? "请先勾选当前组织节点下需要删除的数据" : "请先勾选需要删除的数据");
				return;
			}
			const selectedDepartmentName = isOrgResourceTreeScopedTable(tableKey)
				? String(findOrgNodeById(state.organizationTree, state.selectedOrgId)?.name || "").trim()
				: "";
			const selectedEquipmentNodeName = isOrgResourceEquipmentTreeScopedTable(tableKey)
				? String(getOrgResourceEquipmentScopeNode(tableKey)?.name || "").trim()
				: "";
			const selectedRows = visibleRows.filter((item) => selectedIds.has(item.id));
			const nonSelectedNodeRows = selectedDepartmentName
				? selectedRows.filter((item) => String(item?.department || "").trim() !== selectedDepartmentName)
				: selectedEquipmentNodeName
					? selectedRows.filter((item) => String(item?.equipmentNodeName || "").trim() !== selectedEquipmentNodeName)
					: [];
			const warningText =
				nonSelectedNodeRows.length > 0
					? `\n提示：其中 ${nonSelectedNodeRows.length} 条数据${selectedDepartmentName ? `所属部门不是当前选中节点“${selectedDepartmentName}”` : `关联装备节点不是当前选中节点“${selectedEquipmentNodeName}”`}。`
					: "";
			if (!window.confirm(`确认批量删除已勾选的 ${selectedIds.size} 条数据？${warningText}`)) return;
			removeOrgResourceRows(tableKey, selectedIds);
			showToast("批量删除成功");
			render();
		});
	});

	document.querySelectorAll("[data-action='import-org-resource']").forEach((el) => {
		el.addEventListener("click", () => {
			const tableKey = el.dataset.table || "";
			if (!ORG_RESOURCE_TABLE_CONFIG[tableKey]) return;
			const fileInput = document.getElementById(`orgResourceImportInput_${tableKey}`);
			if (!fileInput) return;
			fileInput.click();
		});
	});

	document.querySelectorAll("[data-action='org-resource-file']").forEach((el) => {
		el.addEventListener("change", async () => {
			const tableKey = el.dataset.table || "";
			if (!ORG_RESOURCE_TABLE_CONFIG[tableKey]) return;
			const file = el.files?.[0];
			if (!file) return;
			try {
				const { importedItems, rowErrors } = await importOrgResourceByExcel(tableKey, file);
				const resources = ensureOrgResourceModelState();
				resources[tableKey] = [...(resources[tableKey] || []), ...importedItems];
				if (rowErrors.length) {
					showToast(`导入完成：成功 ${importedItems.length} 条，失败 ${rowErrors.length} 条`);
				} else {
					showToast(`导入成功：${importedItems.length} 条`);
				}
				render();
			} catch (error) {
				showToast(`导入失败：${error.message || "文件格式不正确"}`);
			} finally {
				el.value = "";
			}
		});
	});

	const opsModelInput = document.getElementById("opsModel");
	if (opsModelInput) {
		opsModelInput.addEventListener("change", () => {
			state.ui.opsPlanDraft = state.ui.opsPlanDraft || createDefaultOpsPlanDraft();
			state.ui.opsPlanDraft.model = normalizeAircraftNodeName(opsModelInput.value || APP_CONFIG.modelTypes[0] || "");
			render();
		});
	}

	const opsPlanTypeInput = document.getElementById("opsPlanType");
	if (opsPlanTypeInput) {
		opsPlanTypeInput.addEventListener("change", () => {
			state.ui.opsPlanDraft = state.ui.opsPlanDraft || createDefaultOpsPlanDraft();
			state.ui.opsPlanDraft.planType = opsPlanTypeInput.value;
			render();
		});
	}

	document.querySelectorAll("[data-action='switch-ops-plan-type']").forEach((el) => {
		el.addEventListener("click", () => {
			state.ui.opsPlanDraft = state.ui.opsPlanDraft || createDefaultOpsPlanDraft();
			const nextType = String(el.dataset.type || "").trim();
			if (!OPS_PLAN_TYPE_OPTIONS.includes(nextType)) return;
			const activeOpsPlan = getActiveComprehensivePlan("ops_plan");
			const activeSchemeInfo = getOpsPlanSchemeByPlanId(activeOpsPlan?.id || "");
			if (activeSchemeInfo?.scheme) {
				const targetPlan = getOpsPlanPlanByTypeInScheme(activeSchemeInfo.scheme, nextType);
				if (targetPlan?.id) {
					setActiveComprehensivePlan("ops_plan", targetPlan.id);
				} else {
					state.ui.opsPlanDraft.planType = nextType;
				}
			} else {
				state.ui.opsPlanDraft.planType = nextType;
			}
			render();
		});
	});

	const opsActivityNameInput = document.getElementById("opsActivityName");
	if (opsActivityNameInput) {
		opsActivityNameInput.addEventListener("input", () => {
			const draft = getComprehensiveDraftByTab("ops_plan");
			const nextActivityName = String(opsActivityNameInput.value || "").trim();
			draft.activityName = nextActivityName;
			state.ui.opsPlanDraft = draft;

			const activePlan = getActiveComprehensivePlan("ops_plan");
			const activeSchemeInfo = getOpsPlanSchemeByPlanId(activePlan?.id || "");
			if (activeSchemeInfo?.scheme?.allPlans?.length) {
				activeSchemeInfo.scheme.allPlans.forEach((plan) => {
					if (plan?.draft && typeof plan.draft === "object") {
						plan.draft.activityName = nextActivityName;
					}
				});
			}

			if (activeSchemeInfo?.equipmentName) {
				const activeSchemeNo = Number(activeSchemeInfo?.scheme?.schemeNo || 1);
				const nextNodeLabel = nextActivityName || buildOpsPlanSchemeDisplayName(activeSchemeInfo.equipmentName, activeSchemeNo);
				document.querySelectorAll("[data-action='select-ops-plan-scheme']").forEach((nodeEl) => {
					const nodeEquipment = String(nodeEl.dataset.equipment || "").trim();
					const nodeSchemeNo = Number(nodeEl.dataset.schemeNo || 0);
					if (nodeEquipment !== activeSchemeInfo.equipmentName || nodeSchemeNo !== activeSchemeNo) return;
					const textEl = nodeEl.querySelector(".tree-node-text");
					if (textEl) textEl.textContent = nextNodeLabel;
				});
			}
		});
	}

	const opsMaxWorkTimeRefInput = document.getElementById("opsMaxWorkTimeRef");
	if (opsMaxWorkTimeRefInput) {
		opsMaxWorkTimeRefInput.addEventListener("change", () => {
			state.ui.opsPlanDraft = state.ui.opsPlanDraft || createDefaultOpsPlanDraft();
			state.ui.opsPlanDraft.maxWorkTimeRef = Number(opsMaxWorkTimeRefInput.value || 0);
		});
	}

	const opsSimulationRunRuleInput = document.getElementById("opsSimulationRunRule");
	if (opsSimulationRunRuleInput) {
		opsSimulationRunRuleInput.addEventListener("change", () => {
			state.ui.opsPlanDraft = state.ui.opsPlanDraft || createDefaultOpsPlanDraft();
			const nextRule = String(opsSimulationRunRuleInput.value || "").trim();
			state.ui.opsPlanDraft.simulationRunRule = OPS_SIMULATION_RUN_RULE_OPTIONS.includes(nextRule)
				? nextRule
				: OPS_SIMULATION_RUN_RULE_OPTIONS[0];
		});
	}

	document.querySelectorAll("[data-action='ops-job-toggle']").forEach((el) => {
		el.addEventListener("change", () => {
			const draft = state.ui.opsPlanDraft || createDefaultOpsPlanDraft();
			state.ui.opsPlanDraft = draft;
			const jobName = el.dataset.job;
			if (!jobName) return;
			if (el.checked) {
				if (!draft.selectedJobs.includes(jobName)) draft.selectedJobs.push(jobName);
				if (!draft.jobs[jobName]) {
					draft.jobs[jobName] = { duration: BASIC_OPS_DURATION_MAP[jobName] || 10, predecessors: [] };
				}
			} else {
				draft.selectedJobs = draft.selectedJobs.filter((name) => name !== jobName);
				Object.keys(draft.jobs).forEach((name) => {
					draft.jobs[name].predecessors = (draft.jobs[name].predecessors || []).filter((prev) => prev !== jobName);
				});
			}
			const orderedKnownJobs = BASIC_OPS_WORK_NAMES.filter((name) => draft.selectedJobs.includes(name));
			const customJobs = draft.selectedJobs.filter((name) => !BASIC_OPS_WORK_NAMES.includes(name));
			draft.selectedJobs = [...orderedKnownJobs, ...customJobs];
			render();
		});
	});

	document.querySelectorAll("[data-action='ops-duration-change']").forEach((el) => {
		el.addEventListener("change", () => {
			const draft = state.ui.opsPlanDraft || createDefaultOpsPlanDraft();
			state.ui.opsPlanDraft = draft;
			const jobName = el.dataset.job;
			if (!jobName) return;
			if (!draft.jobs[jobName]) {
				draft.jobs[jobName] = { duration: BASIC_OPS_DURATION_MAP[jobName] || 10, predecessors: [] };
			}
			draft.jobs[jobName].duration = Number(el.value || 0);
			render();
		});
	});

	document.querySelectorAll("[data-action='ops-prev-toggle']").forEach((el) => {
		el.addEventListener("change", () => {
			const draft = state.ui.opsPlanDraft || createDefaultOpsPlanDraft();
			state.ui.opsPlanDraft = draft;
			const jobName = el.dataset.job;
			const prevName = el.dataset.prev;
			if (!jobName || !prevName) return;
			if (!draft.jobs[jobName]) {
				draft.jobs[jobName] = { duration: BASIC_OPS_DURATION_MAP[jobName] || 10, predecessors: [] };
			}
			const predecessors = new Set(draft.jobs[jobName].predecessors || []);
			if (el.checked) predecessors.add(prevName);
			else predecessors.delete(prevName);
			draft.jobs[jobName].predecessors = draft.selectedJobs.filter((name) => name !== jobName && predecessors.has(name));
			render();
		});
	});

