	document.querySelectorAll("[data-action='prev-job-toggle']").forEach((el) => {
		el.addEventListener("change", () => {
			const draft = state.ui.prevRepairDraft || createDefaultPrevRepairDraft();
			state.ui.prevRepairDraft = draft;
			const jobName = el.dataset.job;
			if (!jobName) return;
			if (el.checked) {
				if (!draft.selectedJobs.includes(jobName)) draft.selectedJobs.push(jobName);
				if (!draft.jobs[jobName]) {
					draft.jobs[jobName] = createComprehensiveJobConfig(resolveRepairDurationByJobName(jobName, draft.equipmentName), [], null);
				}
			} else {
				draft.selectedJobs = draft.selectedJobs.filter((name) => name !== jobName);
				Object.keys(draft.jobs).forEach((name) => {
					draft.jobs[name].predecessors = (draft.jobs[name].predecessors || []).filter((prev) => prev !== jobName);
				});
			}
			const orderedKnownJobs = BASIC_REPAIR_WORK_NAMES.filter((name) => draft.selectedJobs.includes(name));
			const customJobs = draft.selectedJobs.filter((name) => !BASIC_REPAIR_WORK_NAMES.includes(name));
			draft.selectedJobs = [...orderedKnownJobs, ...customJobs];
			render();
		});
	});

	document.querySelectorAll("[data-action='prev-duration-change']").forEach((el) => {
		el.addEventListener("change", () => {
			const draft = state.ui.prevRepairDraft || createDefaultPrevRepairDraft();
			state.ui.prevRepairDraft = draft;
			const jobName = el.dataset.job;
			if (!jobName) return;
			if (!draft.jobs[jobName]) {
				draft.jobs[jobName] = { duration: BASIC_REPAIR_DURATION_MAP[jobName] || 10, predecessors: [] };
			}
			draft.jobs[jobName].duration = Number(el.value || 0);
			render();
		});
	});

	document.querySelectorAll("[data-action='prev-prev-toggle']").forEach((el) => {
		el.addEventListener("change", () => {
			const draft = state.ui.prevRepairDraft || createDefaultPrevRepairDraft();
			state.ui.prevRepairDraft = draft;
			const jobName = el.dataset.job;
			const prevName = el.dataset.prev;
			if (!jobName || !prevName) return;
			if (!draft.jobs[jobName]) {
				draft.jobs[jobName] = { duration: BASIC_REPAIR_DURATION_MAP[jobName] || 10, predecessors: [] };
			}
			const predecessors = new Set(draft.jobs[jobName].predecessors || []);
			if (el.checked) predecessors.add(prevName);
			else predecessors.delete(prevName);
			draft.jobs[jobName].predecessors = draft.selectedJobs.filter((name) => name !== jobName && predecessors.has(name));
			render();
		});
	});

