	document.querySelectorAll("[data-action='run-sim-start']").forEach((el) => {
		el.addEventListener("click", () => {
			const sceneKey = el.dataset.scene === "mc" ? "mc" : "visual";
			const scene = sceneKey === "mc" ? "蒙特卡洛实验" : "可视化推演";
			const errors = buildSimulationPrecheckErrors(sceneKey);
			if (Array.isArray(errors) && errors.length > 0) {
				showToast(`${scene}资源校核未通过，请先查看预校核详情。`);
				return;
			}
			showToast(`${scene}启动（模拟）：按飞机所属保障组织调配保障资源`);
		});
	});

	document.querySelectorAll("[data-action='run-sim-precheck']").forEach((el) => {
		el.addEventListener("click", () => {
			const scene = el.dataset.scene === "mc" ? "mc" : "visual";
			const resultIds = scene === "mc" ? ["simMcPrecheckResult"] : ["simVisualPrecheckResult"];
			const resultElements = resultIds
				.map((id) => document.getElementById(id))
				.filter((node) => Boolean(node));
			const errors = buildSimulationPrecheckErrors(scene);
			if (!Array.isArray(errors) || errors.length === 0) {
				resultElements.forEach((node) => {
					node.style.display = "block";
					node.style.whiteSpace = "pre-wrap";
					node.className = "alert success";
					node.textContent = "校核通过：任务执行将按飞机所属保障组织调配机务人员和保障资源，并按保障活动要求匹配舰面保障设施。";
				});
				return;
			}
			const normalizedErrors = errors.map((item) => String(item || "").trim()).filter(Boolean);
			const hintLine = normalizedErrors[0] || "";
			const detailLines = normalizedErrors.slice(1);
			const numberedDetailLines = detailLines.map((item, index) => `${index + 1}. ${item}`);
			const message = ["校核未通过：", hintLine, ...numberedDetailLines].filter(Boolean).join("\n\n");
			resultElements.forEach((node) => {
				node.style.display = "block";
				node.style.whiteSpace = "pre-wrap";
				node.className = "alert error";
				node.textContent = message;
			});
		});
	});

