	document.querySelectorAll("[data-action='metric-rule-change']").forEach((el) => {
		const eventName = el.tagName === "SELECT" ? "change" : "input";
		el.addEventListener(eventName, () => {
			const pageType = el.dataset.page === "optimization" ? "optimization" : "analysis";
			const configType = String(el.dataset.type || "").trim() || (pageType === "optimization" ? (state.ui.currentOptimization || "rl") : (state.ui.currentAnalysis || "task-min-demand"));
			const section = el.dataset.section === "targets" ? "targets" : "constraints";
			const field = String(el.dataset.field || "").trim();
			const rowIndex = Number.parseInt(el.dataset.index || "", 10);
			if (!["indicatorId", "operator", "threshold"].includes(field) || !Number.isInteger(rowIndex) || rowIndex < 0) return;

			const config = ensureMetricConfigState(pageType, configType);
			if (!Array.isArray(config[section]) || !config[section][rowIndex]) return;
			config[section][rowIndex][field] = el.value;
			if (pageType === "optimization" && section === "targets") {
				config.targets = config.targets.slice(0, 1);
			}
		});
	});

	document.querySelectorAll("[data-action='analysis-model-target-change']").forEach((el) => {
		const eventName = el.tagName === "SELECT" ? "change" : "input";
		el.addEventListener(eventName, () => {
			const configType = String(el.dataset.type || "").trim() || (state.ui.currentAnalysis || "task-min-demand");
			const modelName = String(el.dataset.model || "").trim();
			const field = String(el.dataset.field || "indicatorId").trim();
			if (!modelName) return;
			const config = ensureMetricConfigState("analysis", configType);
			if (!config.modelTargets || typeof config.modelTargets !== "object") {
				config.modelTargets = {};
			}
			const currentTarget = getAnalysisModelTargetConfig(config, modelName);
			if (field === "operator") {
				currentTarget.operator = ["≤", "≥", "="].includes(String(el.value || "").trim()) ? String(el.value).trim() : "≥";
			} else if (field === "threshold") {
				currentTarget.threshold = String(el.value ?? "");
			} else {
				currentTarget.indicatorId = String(el.value || "").trim() || "sortie_rate";
			}
			config.modelTargets[modelName] = currentTarget;
		});
	});

	document.querySelectorAll("[data-action='analysis-constraint-toggle']").forEach((el) => {
		el.addEventListener("change", () => {
			const configType = String(el.dataset.type || "").trim() || (state.ui.currentAnalysis || "task-min-demand");
			const indicatorId = String(el.dataset.id || "").trim();
			if (!indicatorId) return;
			const config = ensureMetricConfigState("analysis", configType);
			const selectedSet = new Set(Array.isArray(config.selectedConstraintIndicatorIds) ? config.selectedConstraintIndicatorIds : []);
			if (el.checked) {
				selectedSet.add(indicatorId);
			} else {
				selectedSet.delete(indicatorId);
			}
			config.selectedConstraintIndicatorIds = Array.from(selectedSet);
		});
	});

	document.querySelectorAll("[data-action='analysis-constraint-select-all']").forEach((el) => {
		el.addEventListener("click", () => {
			const configType = String(el.dataset.type || "").trim() || (state.ui.currentAnalysis || "task-min-demand");
			const config = ensureMetricConfigState("analysis", configType);
			config.selectedConstraintIndicatorIds = (state.indicators || []).map((item) => String(item?.id || "").trim()).filter(Boolean);
			render();
		});
	});

	document.querySelectorAll("[data-action='add-metric-rule']").forEach((el) => {
		el.addEventListener("click", () => {
			const pageType = el.dataset.page === "optimization" ? "optimization" : "analysis";
			const configType = String(el.dataset.type || "").trim() || (pageType === "optimization" ? (state.ui.currentOptimization || "rl") : (state.ui.currentAnalysis || "task-min-demand"));
			const section = el.dataset.section === "targets" ? "targets" : "constraints";
			const config = ensureMetricConfigState(pageType, configType);
			if (!Array.isArray(config[section])) {
				config[section] = [];
			}
			config[section].push({ indicatorId: "", operator: "≤", threshold: "" });
			if (pageType === "optimization" && section === "targets") {
				config.targets = config.targets.slice(0, 1);
			}
			render();
		});
	});

	document.querySelectorAll("[data-action='optimization-matrix-page']").forEach((el) => {
		el.addEventListener("click", () => {
			const optimizationType = el.dataset.type;
			const direction = el.dataset.direction;
			if (!optimizationType || !["ga", "pso"].includes(optimizationType)) return;
			const uiState = ensureOptimizationMatrixUiState();
			const currentPage = Number(uiState[optimizationType]) || 1;
			uiState[optimizationType] = direction === "prev" ? Math.max(1, currentPage - 1) : currentPage + 1;
			render();
		});
	});

	document.querySelectorAll("[data-action='switch-tasks-tab']").forEach((el) => {
		el.addEventListener("click", () => {
			state.tasksTab = el.dataset.tab;
			render();
		});
	});

	if (!state.ui.selectedTaskIds) {
		state.ui.selectedTaskIds = { unit: [], single: [], basic: [], composite: [] };
	}
	if (!Array.isArray(state.ui.selectedProjectIds)) {
		state.ui.selectedProjectIds = [];
	}
	if (!state.ui.selectedDeckIds || typeof state.ui.selectedDeckIds !== "object") {
		state.ui.selectedDeckIds = { stations: [], parking: [], facilities: [], matrix: [] };
	}
	["stations", "parking", "facilities", "matrix"].forEach((tableKey) => {
		if (!Array.isArray(state.ui.selectedDeckIds[tableKey])) {
			state.ui.selectedDeckIds[tableKey] = [];
		}
	});
	if (!Array.isArray(state.ui.selectedPermissionIds)) {
		state.ui.selectedPermissionIds = [];
	}
	["unit", "single", "basic", "composite"].forEach((type) => {
		if (!Array.isArray(state.ui.selectedTaskIds[type])) {
			state.ui.selectedTaskIds[type] = [];
		}
	});
	ensureUnitGroupState();

	document.querySelectorAll("[data-action='toggle-task-select-all']").forEach((el) => {
		el.addEventListener("change", () => {
			const type = el.dataset.type;
			if (!type) return;
			const tasksTab = String(state.tasksTab || "").trim();
			const compositeSource =
				String(state.ui?.expTab || "").trim() === "experiments" || tasksTab === "periodic"
					? getPeriodicTaskList()
					: getTrainingCompositeTaskList();
			const sourceMap = {
				unit: getUnitsBySelectedBasicTask(),
				single: getSingleMissionsByModel(state.ui.selectedSingleModel),
				basic: state.tasks.basicTasks,
				composite: compositeSource
			};
			const source = sourceMap[type] || [];
			state.ui.selectedTaskIds[type] = el.checked ? source.map((item) => item.id) : [];
			render();
		});
	});

	document.querySelectorAll("[data-action='toggle-task-select']").forEach((el) => {
		el.addEventListener("change", () => {
			const type = el.dataset.type;
			const id = el.dataset.id;
			if (!type || !id) return;
			const selectedSet = new Set(state.ui.selectedTaskIds[type] || []);
			if (el.checked) selectedSet.add(id);
			else selectedSet.delete(id);
			state.ui.selectedTaskIds[type] = Array.from(selectedSet);
			render();
		});
	});

	document.querySelectorAll("[data-action='delete-task-selected']").forEach((el) => {
		el.addEventListener("click", () => {
			const type = el.dataset.type;
			if (!type) return;
			const tasksTab = String(state.tasksTab || "").trim();
			const selectedIds = new Set(state.ui.selectedTaskIds[type] || []);
			if (selectedIds.size === 0) {
				showToast("请先勾选需要删除的数据");
				return;
			}
			const labelMap = {
				unit: "基本作战单元建模",
				single: "单机任务建模",
				basic: "基本任务建模",
				composite: String(state.ui?.expTab || "").trim() === "experiments" || tasksTab === "periodic" ? "仿真实验" : "复合任务"
			};
			showConfirm(`确认删除已勾选的 ${selectedIds.size} 条${labelMap[type] || "数据"}记录？`, (ok) => {
				if (!ok) return;
				if (type === "unit") {
					state.tasks.units = state.tasks.units.filter((item) => !selectedIds.has(item.id));
					if (selectedIds.has(state.ui.selectedUnitId)) {
						state.ui.selectedUnitId = "";
					}
					ensureUnitGroupState();
					state.ui.tasksDirty = false;
				}
				if (type === "single") {
					state.tasks.singleMissions = state.tasks.singleMissions.filter((item) => !selectedIds.has(item.id));
					if (selectedIds.has(state.ui.activeSingleMissionId)) {
						state.ui.activeSingleMissionId = "";
						state.ui.singleEditorMode = "empty";
					}
					syncSingleMissionSchemeOverrides();
					state.ui.tasksDirty = true;
				}
				if (type === "basic") {
					state.tasks.basicTasks = state.tasks.basicTasks.filter((item) => !selectedIds.has(item.id));
					resetCompositeTimelineResult();
					state.ui.tasksDirty = false;
				}
				if (type === "composite") {
					state.tasks.compositeTasks = state.tasks.compositeTasks.filter((item) => !selectedIds.has(item.id));
					if (selectedIds.has(String(state.ui.selectedCompositeSchemeId || "").trim())) {
						state.ui.selectedCompositeSchemeId = "";
						state.ui.selectedUnitBasicTaskId = "";
					}
					state.ui.compositeSchedulePopover = { taskId: "", monthKey: "" };
					resetCompositeTimelineResult();
					state.ui.tasksDirty = false;
				}
				state.ui.selectedTaskIds[type] = [];
				render();
			});
		});
	});

	document.querySelectorAll("[data-action='select-unit-basic-task']").forEach((el) => {
		el.addEventListener("click", () => {
			const taskId = String(el.dataset.id || "").trim();
			if (!taskId) return;
			state.ui.selectedUnitBasicTaskId = taskId;
			state.ui.selectedTaskIds.unit = [];
			render();
		});
	});

	document.querySelectorAll("[data-action='select-unit-composite-scheme']").forEach((el) => {
		el.addEventListener("click", () => {
			const schemeId = String(el.dataset.id || "").trim();
			if (!schemeId) return;
			state.ui.selectedCompositeSchemeId = schemeId;
			state.ui.selectedUnitBasicTaskId = "";
			state.ui.selectedTaskIds.unit = [];
			render();
		});
	});

	document.querySelectorAll("[data-action='unit-aircraft-group-toggle']").forEach((el) => {
		el.addEventListener("change", () => {
			const rowId = String(el.dataset.rowId || "").trim();
			const taskId = String(el.dataset.taskId || state.ui.selectedCompositeSchemeId || "").trim();
			const groupName = normalizeUnitGroupName(String(el.dataset.groupName || "").trim(), "");
			const modelName = String(el.dataset.model || "").trim();
			const requiredCount = Math.max(0, Math.floor(Number(el.dataset.required || 0)));
			if (!rowId) return;
			if (el.checked && groupName && modelName) {
				const scopedRows = getAllShipborneAircraftRows({ onboardOnly: true, periodicTaskId: taskId });
				const configuredCount = scopedRows.filter((row) =>
					String(row?.model || "").trim() === modelName &&
					normalizeShipborneAircraftUnitNames(row?.unitNames || row?.unitName).includes(groupName)
				).length;
				if (configuredCount >= requiredCount) {
					el.checked = false;
					showToast(`编队 ${groupName} 的 ${modelName} 已达需求上限（${requiredCount}）`);
					return;
				}
			}
			const selectedUnitNames = Array.from(document.querySelectorAll(`[data-action='unit-aircraft-group-toggle'][data-row-id='${rowId}']:checked`))
				.map((checkbox) => String(checkbox.dataset.groupName || "").trim())
				.filter(Boolean);
			assignShipborneAircraftUnit(rowId, selectedUnitNames, taskId);
			render();
		});
	});

	document.querySelectorAll("[data-action='add-unit-row']").forEach((el) => {
		el.addEventListener("click", () => {
			const selectedScheme = getSelectedUnitCompositeScheme();
			if (!selectedScheme) {
				showToast("当前暂无复合任务");
				return;
			}
			const selectedTask = getSelectedUnitBasicTask();
			openModal("unit", { mode: "add", taskId: selectedTask?.id || "" });
		});
	});

	document.querySelectorAll("[data-action='edit-unit-row']").forEach((el) => {
		el.addEventListener("click", () => {
			const unitId = String(el.dataset.id || "").trim();
			if (!unitId) return;
			const targetUnit = state.tasks.units.find((item) => String(item?.id || "").trim() === unitId) || null;
			if (!targetUnit) return;
			openModal("unit", { mode: "edit", item: targetUnit, taskId: state.ui.selectedUnitBasicTaskId });
		});
	});

	document.querySelectorAll("[data-action='delete-unit-row']").forEach((el) => {
		el.addEventListener("click", () => {
			const unitId = String(el.dataset.id || "").trim();
			if (!unitId) return;
			const targetUnit = state.tasks.units.find((item) => String(item?.id || "").trim() === unitId) || null;
			showConfirm(`确认删除该使用单元${targetUnit?.aircraftNo ? `（${targetUnit.aircraftNo}）` : ""}？`, (ok) => {
				if (!ok) return;
				state.tasks.units = state.tasks.units.filter((item) => String(item?.id || "").trim() !== unitId);
				state.ui.selectedTaskIds.unit = (state.ui.selectedTaskIds.unit || []).filter((id) => String(id || "").trim() !== unitId);
				render();
			});
		});
	});

	document.querySelectorAll("[data-action='create-unit-draft']").forEach((el) => {
		el.addEventListener("click", () => {
			const selectedGroupName = normalizeUnitGroupName(state.ui.selectedUnitGroupName || "", "");
			if (state.ui.selectedUnitGroupName === UNIT_GROUP_LIST_ROOT_ID) {
				let index = (state.tasks.unitGroups?.length || 0) + 1;
				let groupName = `编队${index}`;
				while ((state.tasks.unitGroups || []).includes(groupName)) {
					index += 1;
					groupName = `编队${index}`;
				}
				state.tasks.unitGroups.push(groupName);
				state.ui.collapsedUnitGroupNames = (state.ui.collapsedUnitGroupNames || []).filter((name) => name !== groupName);
				state.ui.selectedUnitGroupName = groupName;
				state.ui.selectedUnitId = "";
				state.ui.unitEditorMode = "empty";
				state.ui.selectedTaskIds.unit = [];
				showToast(`${groupName} 已新增`);
				render();
				return;
			}
			const groupName = upsertUnitGroup(selectedGroupName || state.tasks.units.find((item) => item.id === state.ui.selectedUnitId)?.groupName || "编队1") || "编队1";
			state.ui.selectedUnitGroupName = groupName;
			state.ui.collapsedUnitGroupNames = (state.ui.collapsedUnitGroupNames || []).filter((name) => name !== groupName);
			state.ui.selectedUnitId = "";
			state.ui.unitEditorMode = "create";
			state.ui.selectedTaskIds.unit = [];
			render();
		});
	});

	document.querySelectorAll("[data-action='create-single-draft']").forEach((el) => {
		el.addEventListener("click", () => {
			const modelRoots = getSingleMissionModelRootList();
			const preferredModel = String(el.dataset.model || state.ui.selectedSingleModel || "").trim();
			const selectedCategory = String(el.dataset.category || state.ui.selectedSingleCategory || "").trim();
			const modelName = modelRoots.includes(preferredModel) ? preferredModel : modelRoots[0] || "";
			if (!modelName) {
				showToast("请先在基本作战单元建模中维护机型");
				return;
			}
			const missionDraft = createSingleMissionDraft({ id: uid("single"), model: modelName }, modelName);
			// 如果已选中类别，设置category；否则根据推断规则设置
			if (selectedCategory) {
				missionDraft.category = selectedCategory;
			}
			const firstMountItem = missionDraft.requiredMountItems[0] || { type: "", count: 0 };
			const newMission = {
				...missionDraft,
				requiredFuelAmount: missionDraft.requiredFuelAmountT,
				requiredAmmunitionType: String(firstMountItem.type || "").trim(),
				requiredAmmunitionCount: Number(firstMountItem.count || 0)
			};
			state.tasks.singleMissions.push(newMission);
			state.ui.selectedSingleModel = modelName;
			state.ui.selectedSingleCategory = selectedCategory;
			state.ui.collapsedSingleModelNames = (state.ui.collapsedSingleModelNames || []).filter((name) => name !== modelName);
			state.ui.activeSingleMissionId = newMission.id;
			state.ui.singleEditorMode = "edit";
			render();
		});
	});

	document.querySelectorAll("[data-action='toggle-single-model']").forEach((el) => {
		el.addEventListener("click", (event) => {
			event.stopPropagation();
			const modelName = String(el.dataset.model || "").trim();
			if (!modelName) return;
			const collapsedSet = new Set(state.ui.collapsedSingleModelNames || []);
			if (collapsedSet.has(modelName)) {
				collapsedSet.delete(modelName);
			} else {
				collapsedSet.add(modelName);
			}
			state.ui.collapsedSingleModelNames = Array.from(collapsedSet);
			render();
		});
	});

	document.querySelectorAll("[data-action='select-single-model']").forEach((el) => {
		el.addEventListener("click", () => {
			const modelName = String(el.dataset.model || "").trim();
			if (!modelName) return;
			state.ui.selectedSingleModel = modelName;
			state.ui.selectedSingleCategory = "";
			state.ui.activeSingleMissionId = "";
			state.ui.singleEditorMode = "empty";
			state.ui.selectedTaskIds.single = [];
			render();
		});
	});

	document.querySelectorAll("[data-action='select-single-category']").forEach((el) => {
		el.addEventListener("click", () => {
			const modelName = String(el.dataset.model || "").trim();
			const categoryName = String(el.dataset.category || "").trim();
			if (!modelName || !categoryName) return;
			state.ui.selectedSingleModel = modelName;
			state.ui.selectedSingleCategory = categoryName;
			state.ui.activeSingleMissionId = "";
			state.ui.singleEditorMode = "empty";
			state.ui.selectedTaskIds.single = [];
			render();
		});
	});

	document.querySelectorAll("[data-action='select-single-node']").forEach((el) => {
		el.addEventListener("click", () => {
			const missionId = el.dataset.id;
			const modelName = String(el.dataset.model || "").trim();
			if (!missionId || !modelName) return;
			state.ui.selectedSingleModel = modelName;
			state.ui.selectedSingleCategory = "";
			state.ui.collapsedSingleModelNames = (state.ui.collapsedSingleModelNames || []).filter((name) => name !== modelName);
			state.ui.activeSingleMissionId = missionId;
			state.ui.singleEditorMode = "edit";
			render();
		});
	});


	document.querySelectorAll("[data-action='toggle-unit-root']").forEach((el) => {
		el.addEventListener("click", (event) => {
			event.stopPropagation();
			state.ui.unitGroupListCollapsed = !Boolean(state.ui.unitGroupListCollapsed);
			render();
		});
	});

	document.querySelectorAll("[data-action='select-unit-root']").forEach((el) => {
		el.addEventListener("click", () => {
			state.ui.selectedUnitGroupName = UNIT_GROUP_LIST_ROOT_ID;
			state.ui.selectedUnitId = "";
			state.ui.unitEditorMode = "empty";
			state.ui.selectedTaskIds.unit = [];
			render();
		});
	});

	document.querySelectorAll("[data-action='toggle-unit-group']").forEach((el) => {
		el.addEventListener("click", (event) => {
			event.stopPropagation();
			const groupName = normalizeUnitGroupName(el.dataset.group || "", "");
			if (!groupName) return;
			const collapsedSet = new Set(state.ui.collapsedUnitGroupNames || []);
			if (collapsedSet.has(groupName)) {
				collapsedSet.delete(groupName);
			} else {
				collapsedSet.add(groupName);
			}
			state.ui.collapsedUnitGroupNames = Array.from(collapsedSet);
			render();
		});
	});

	document.querySelectorAll("[data-action='select-unit-group']").forEach((el) => {
		el.addEventListener("click", () => {
			const groupName = upsertUnitGroup(el.dataset.group || "");
			if (!groupName) return;
			state.ui.selectedUnitGroupName = groupName;
			state.ui.selectedUnitId = "";
			state.ui.unitEditorMode = "empty";
			state.ui.selectedTaskIds.unit = [];
			render();
		});
	});

	document.querySelectorAll("[data-action='rename-unit-group']").forEach((el) => {
		el.addEventListener("click", () => {
			const oldName = el.dataset.origin;
			const newName = document.getElementById('renameUnitGroupName')?.value.trim();
			if (!newName) {
				alert('编队名称不能为空');
				return;
			}
			if (oldName === newName) return;
			state.tasks.units.forEach(u => {
				if (u.groupName === oldName) u.groupName = newName;
			});
			state.ui.selectedUnitGroupName = newName;
			render();
		});
	});

	document.querySelectorAll("[data-action='select-unit-node']").forEach((el) => {
		el.addEventListener("click", () => {
			const id = el.dataset.id;
			const groupName = normalizeUnitGroupName(el.dataset.group || "", "");
			if (!id || !groupName) return;
			state.ui.selectedUnitGroupName = groupName;
			state.ui.collapsedUnitGroupNames = (state.ui.collapsedUnitGroupNames || []).filter((name) => name !== groupName);
			state.ui.selectedUnitId = id;
			state.ui.unitEditorMode = "edit";
			render();
		});
	});

	document.querySelectorAll("[data-action='delete-selected-unit']").forEach((el) => {
		el.addEventListener("click", () => {
			const deletedId = state.ui.selectedUnitId;
			if (deletedId) {
				const targetUnit = state.tasks.units.find((item) => item.id === deletedId) || null;
				showConfirm(`确认删除飞机节点“${targetUnit?.aircraftNo || "未命名飞机"}”？`, (ok) => {
					if (!ok) return;
					state.tasks.units = state.tasks.units.filter((item) => item.id !== deletedId);
					state.ui.selectedTaskIds.unit = (state.ui.selectedTaskIds.unit || []).filter((id) => id !== deletedId);
					state.ui.selectedUnitId = "";
					state.ui.unitEditorMode = "empty";
					ensureUnitGroupState();
					state.ui.tasksDirty = false;
					render();
				});
				return;
			}

			const selectedGroupName = normalizeUnitGroupName(state.ui.selectedUnitGroupName || "", "");
			if (!selectedGroupName || state.ui.selectedUnitGroupName === UNIT_GROUP_LIST_ROOT_ID) {
				showToast("请先选择需要删除的编队节点");
				return;
			}
			const childUnits = state.tasks.units.filter((item) => item.groupName === selectedGroupName);
			const childUnitIds = new Set(childUnits.map((item) => item.id));
			const confirmMessage = `确认删除编队节点“${selectedGroupName}”及其下 ${childUnits.length} 个飞机节点？`;
			if (!window.confirm(confirmMessage)) return;

			state.tasks.unitGroups = (state.tasks.unitGroups || []).filter((name) => name !== selectedGroupName);
			state.tasks.units = state.tasks.units.filter((item) => item.groupName !== selectedGroupName);
			state.ui.collapsedUnitGroupNames = (state.ui.collapsedUnitGroupNames || []).filter((name) => name !== selectedGroupName);
			state.ui.selectedTaskIds.unit = (state.ui.selectedTaskIds.unit || []).filter((id) => !childUnitIds.has(id));
			state.ui.selectedUnitId = "";
			state.ui.unitEditorMode = "empty";
			ensureUnitGroupState();
			state.ui.tasksDirty = false;
			render();
		});
	});

	document.querySelectorAll("[data-action='delete-single-node']").forEach((el) => {
		el.addEventListener("click", () => {
			const activeMissionId = state.ui.activeSingleMissionId;
			if (activeMissionId) {
				const targetMission = state.tasks.singleMissions.find((item) => item.id === activeMissionId) || null;
				if (!targetMission) return;
				showConfirm(`确认删除单机任务“${targetMission.name || "未命名单机任务"}”？`, (ok) => {
					if (!ok) return;
					state.tasks.singleMissions = state.tasks.singleMissions.filter((item) => item.id !== activeMissionId);
					state.ui.activeSingleMissionId = "";
					state.ui.singleEditorMode = "empty";
					syncSingleMissionSchemeOverrides();
					state.ui.tasksDirty = true;
					showToast("已删除");
					render();
				});
				return;
			}

			const selectedModel = String(state.ui.selectedSingleModel || "").trim();

		const selectedCategory = String(state.ui.selectedSingleCategory || "").trim();

		if (selectedCategory) {
			// Delete all missions in this category
			const missionList = getSingleMissionsByModel(selectedModel);
			const categoryMissions = missionList.filter((item) => inferSingleMissionCategoryName(item) === selectedCategory);
			if (categoryMissions.length === 0) {
				showToast("当前类别下暂无单机任务");
				return;
			}
			if (!window.confirm(`确认删除"${selectedCategory}"类别下的 ${categoryMissions.length} 个单机任务？删除后相关基本任务引用可能失效。`)) return;
			const categoryMissionIdSet = new Set(categoryMissions.map((item) => item.id));
			state.tasks.singleMissions = state.tasks.singleMissions.filter((item) => !categoryMissionIdSet.has(item.id));
			state.ui.activeSingleMissionId = "";
			state.ui.selectedSingleCategory = "";
			state.ui.singleEditorMode = "empty";
			syncSingleMissionSchemeOverrides();
			state.ui.tasksDirty = true;
			showToast("已删除，若存在引用失效请在基本任务页修正后保存");
			render();
			return;
		}

		if (!selectedModel) {
			showToast("请先选择需要删除的机型或单机任务");
				return;
			}
			const missionList = getSingleMissionsByModel(selectedModel);
			if (missionList.length === 0) {
				showToast("当前机型下暂无可删除的单机任务");
				return;
			}
			if (!window.confirm(`确认删除机型“${selectedModel}”下的 ${missionList.length} 个单机任务？删除后相关基本任务引用可能失效。`)) return;
			const missionIdSet = new Set(missionList.map((item) => item.id));
			state.tasks.singleMissions = state.tasks.singleMissions.filter((item) => !missionIdSet.has(item.id));
			state.ui.activeSingleMissionId = "";
			state.ui.singleEditorMode = "empty";
			syncSingleMissionSchemeOverrides();
			state.ui.tasksDirty = true;
			showToast("已删除，若存在引用失效请在基本任务页修正后保存");
			render();
		});
	});

	document.querySelectorAll("[data-action='open-single-modal']").forEach((el) => {
		el.addEventListener("click", () => {
			const id = el.dataset.id;
			const payload = state.tasks.singleMissions.find((item) => item.id === id);
			if (payload) {
				state.ui.selectedSingleModel = String(payload.model || "").trim() || state.ui.selectedSingleModel;
				state.ui.activeSingleMissionId = payload.id;
				openModal("single", payload);
				return;
			}
			openModal("single", { model: state.ui.selectedSingleModel || APP_CONFIG.modelTypes[0] || "" });
		});
	});

	const getSingleMountItemsFromHidden = () => {
		const raw = document.getElementById("singleRequiredMountItemsJson")?.value || "[]";
		try {
			return normalizeSingleMissionMountItems(JSON.parse(raw));
		} catch {
			return [];
		}
	};

	const buildSingleDraftFromMainModal = () => {
		return {
			id: state.ui.modal?.payload?.id || "",
			name: document.getElementById("singleName")?.value?.trim() || "",
			code: normalizeSingleMissionCode(document.getElementById("singleCode")?.value || ""),
			model: document.getElementById("singleModel")?.value || APP_CONFIG.modelTypes[0] || "",
			prePlan: document.getElementById("singlePre")?.value || "",
			relaunchPlan: document.getElementById("singleRelaunch")?.value || "",
			postPlan: document.getElementById("singlePost")?.value || "",
			mountPlan: document.getElementById("singleMount")?.value || "",
			fuelPlan: document.getElementById("singleFuel")?.value || "",
			requiredFuelAmountT: Number(document.getElementById("singleRequiredFuelAmountT")?.value || 0),
			requiredMountItems: getSingleMountItemsFromHidden()
		};
	};

	const collectSingleMountItemsFromEditor = () => {
		const typeInputs = Array.from(document.querySelectorAll("[data-role='single-mount-type']"));
		const countInputs = Array.from(document.querySelectorAll("[data-role='single-mount-count']"));
		return typeInputs.map((typeInput, index) => ({
			type: typeInput.value.trim(),
			count: Number(countInputs[index]?.value || 0)
		}));
	};

	document.querySelectorAll("[data-action='open-single-mount-edit']").forEach((el) => {
		el.addEventListener("click", () => {
			const draft = buildSingleDraftFromMainModal();
			openModal("single-mount-edit", { item: draft });
		});
	});

	document.querySelectorAll("[data-action='open-single-fuel-edit']").forEach((el) => {
		el.addEventListener("click", () => {
			const draft = buildSingleDraftFromMainModal();
			openModal("single-fuel-edit", { item: draft });
		});
	});

	const singleMountBackBtn = document.querySelector("[data-action='single-mount-back']");
	if (singleMountBackBtn) {
		singleMountBackBtn.addEventListener("click", () => {
			const item = state.ui.modal?.payload?.item || null;
			openModal("single", item);
		});
	}

	const addSingleMountRowBtn = document.querySelector("[data-action='add-single-mount-row']");
	if (addSingleMountRowBtn) {
		addSingleMountRowBtn.addEventListener("click", () => {
			const item = state.ui.modal?.payload?.item || {};
			const mountItems = collectSingleMountItemsFromEditor();
			const defaultMountType = getSpareResourceNameOptions()[0] || "";
			mountItems.push({ type: defaultMountType, count: 1 });
			openModal("single-mount-edit", { item: { ...item, requiredMountItems: mountItems } });
		});
	}

	document.querySelectorAll("[data-action='remove-single-mount-row']").forEach((el) => {
		el.addEventListener("click", () => {
			const item = state.ui.modal?.payload?.item || {};
			const index = Number(el.dataset.index);
			const mountItems = collectSingleMountItemsFromEditor();
			mountItems.splice(index, 1);
			if (mountItems.length === 0) {
				mountItems.push({ type: "", count: 1 });
			}
			openModal("single-mount-edit", { item: { ...item, requiredMountItems: mountItems } });
		});
	});

	const saveSingleMountBtn = document.querySelector("[data-action='save-single-mount']");
	if (saveSingleMountBtn) {
		saveSingleMountBtn.addEventListener("click", () => {
			const item = state.ui.modal?.payload?.item || {};
			const mountItems = collectSingleMountItemsFromEditor();
			const errEl = document.getElementById("singleMountErr");

			if (!mountItems.length) {
				errEl.style.display = "block";
				errEl.textContent = "请至少维护一条挂弹项。";
				return;
			}
			for (const mountItem of mountItems) {
				if (!String(mountItem.type || "").trim()) {
					errEl.style.display = "block";
					errEl.textContent = "挂弹种类为必填项。";
					return;
				}
				if (!(Number.isInteger(mountItem.count) && mountItem.count >= 0)) {
					errEl.style.display = "block";
					errEl.textContent = "挂弹数量必须为大于等于 0 的整数。";
					return;
				}
			}

			const updatedItem = {
				...item,
				requiredMountItems: mountItems
			};
			openModal("single", updatedItem);
		});
	}

	const singleFuelBackBtn = document.querySelector("[data-action='single-fuel-back']");
	if (singleFuelBackBtn) {
		singleFuelBackBtn.addEventListener("click", () => {
			const item = state.ui.modal?.payload?.item || null;
			openModal("single", item);
		});
	}

	const saveSingleFuelBtn = document.querySelector("[data-action='save-single-fuel']");
	if (saveSingleFuelBtn) {
		saveSingleFuelBtn.addEventListener("click", () => {
			const item = state.ui.modal?.payload?.item || {};
			const fuelAmountT = Number(document.getElementById("singleFuelAmountT")?.value || 0);
			const errEl = document.getElementById("singleFuelErr");
			if (!(fuelAmountT >= 0)) {
				errEl.style.display = "block";
				errEl.textContent = "任务需要油量(t)必须大于等于 0。";
				return;
			}
			openModal("single", {
				...item,
				requiredFuelAmountT: fuelAmountT
			});
		});
	}

	document.querySelectorAll("[data-action='delete-single']").forEach((el) => {
		el.addEventListener("click", () => {
			if (!window.confirm("删除单机任务后，相关基本任务引用可能失效，确认继续？")) return;
			const removedId = el.dataset.id;
			const removedMission = state.tasks.singleMissions.find((item) => item.id === removedId) || null;
			state.tasks.singleMissions = state.tasks.singleMissions.filter((item) => item.id !== el.dataset.id);
			if (state.ui.activeSingleMissionId === removedId) {
				state.ui.activeSingleMissionId = "";
			}
			if (removedMission && String(state.ui.selectedSingleModel || "").trim() === String(removedMission.model || "").trim()) {
				const remainingForModel = getSingleMissionsByModel(removedMission.model);
				if (remainingForModel.length === 0) {
					state.ui.selectedSingleModel = getSingleMissionModelRootList()[0] || "";
				}
			}
			syncSingleMissionSchemeOverrides();
			state.ui.tasksDirty = true;
			showToast("已删除，若存在引用失效请在基本任务页修正后保存");
			render();
		});
	});

	document.querySelectorAll("[data-action='open-basic-modal']").forEach((el) => {
		el.addEventListener("click", () => {
			const id = el.dataset.id;
			const payload = state.tasks.basicTasks.find((item) => item.id === id);
			const preferredAircraftType = String(el.dataset.aircraftType || state.ui.selectedBasicTaskAircraftType || "").trim();
			openModal("basic", createBasicTaskDraft(payload || (preferredAircraftType ? { equipmentType: preferredAircraftType } : null)));
		});
	});

	document.querySelectorAll("[data-action='select-basic-row']").forEach((el) => {
		el.addEventListener("click", (event) => {
			if (event.target.closest("button,input,select,textarea,a,label")) return;
			const selectedId = String(el.dataset.id || "").trim();
			if (!selectedId) return;
			state.ui.selectedBasicTaskId = selectedId;
			const selectedTask = (state.tasks.basicTasks || []).find((item) => String(item?.id || "").trim() === selectedId) || null;
			state.ui.selectedBasicTaskAircraftType = String(createBasicTaskDraft(selectedTask).equipmentType || "").trim();
			render();
		});
	});

	document.querySelectorAll("[data-action='select-basic-task-aircraft']").forEach((el) => {
		el.addEventListener("click", (event) => {
			if (event.target.closest("[data-action='toggle-basic-task-aircraft']")) return;
			const aircraftType = String(el.dataset.aircraftType || "").trim();
			if (!aircraftType) return;
			state.ui.selectedBasicTaskAircraftType = aircraftType;
			state.ui.selectedBasicTaskId = "";
			render();
		});
	});

	document.querySelectorAll("[data-action='toggle-basic-task-aircraft']").forEach((el) => {
		el.addEventListener("click", () => {
			const aircraftType = String(el.dataset.aircraftType || "").trim();
			if (!aircraftType) return;
			if (!Array.isArray(state.ui.collapsedBasicTaskAircraftTypes)) {
				state.ui.collapsedBasicTaskAircraftTypes = [];
			}
			const collapsedSet = new Set(state.ui.collapsedBasicTaskAircraftTypes);
			if (collapsedSet.has(aircraftType)) {
				collapsedSet.delete(aircraftType);
			} else {
				collapsedSet.add(aircraftType);
			}
			state.ui.collapsedBasicTaskAircraftTypes = Array.from(collapsedSet);
			render();
		});
	});

	document.querySelectorAll("[data-action='open-composite-modal']").forEach((el) => {
		el.addEventListener("click", () => {
			const id = el.dataset.id;
			const payload = state.tasks.compositeTasks.find((item) => item.id === id) || null;
			openModal("composite", createCompositeTaskDraft(payload || null));
		});
	});

	document.querySelectorAll("[data-action='open-periodic-task-modal']").forEach((el) => {
		el.addEventListener("click", () => {
			const id = String(el.dataset.id || "").trim();
			const payload = (state.tasks.compositeTasks || []).find((item) => String(item?.id || "").trim() === id) || null;
			openModal("periodic-task", createPeriodicTaskDraft(payload || null));
		});
	});

	document.querySelectorAll("[data-action='open-experiment-name-modal']").forEach((el) => {
		el.addEventListener("click", () => {
			const selectedId = String(el.dataset.id || "").trim();
			const payload = selectedId
				? (state.tasks.compositeTasks || []).find((item) => String(item?.id || "").trim() === selectedId) || null
				: null;
			openModal("experiment-name", createPeriodicTaskDraft(payload || null));
		});
	});

	const getSelectedTrainingCompositeTask = () =>
		getTrainingCompositeTaskList().find((item) => String(item?.id || "").trim() === String(state.ui.selectedCompositeSchemeId || "").trim()) || null;

	const upsertTrainingCompositeTaskInline = (updater) => {
		const currentTask = getSelectedTrainingCompositeTask();
		if (!currentTask) return false;
		const nextSource = typeof updater === "function" ? updater(createCompositeTaskDraft(currentTask)) : updater;
		const nextItem = buildTrainingCompositeTaskItem({ ...currentTask, ...nextSource, id: currentTask.id });
		const err = validateCompositeTask(nextItem, nextItem.id);
		if (err) {
			showToast(err);
			return false;
		}
		state.tasks.compositeTasks = state.tasks.compositeTasks.map((task) => (String(task?.id || "").trim() === String(nextItem.id || "").trim() ? nextItem : task));
		state.ui.selectedCompositeSchemeId = String(nextItem.id || "").trim();
		state.ui.tasksDirty = false;
		return true;
	};

	document.querySelectorAll("[data-action='create-inline-composite']").forEach((el) => {
		el.addEventListener("click", () => {
			const nextItem = buildTrainingCompositeTaskItem({ id: uid("composite") });
			state.tasks.compositeTasks.push(nextItem);
			state.ui.selectedCompositeSchemeId = String(nextItem.id || "").trim();
			state.ui.selectedTaskIds.composite = [];
			render();
		});
	});

	const compositeInlineSchemeNameInput = document.getElementById("compositeInlineSchemeName");
	if (compositeInlineSchemeNameInput) {
		compositeInlineSchemeNameInput.addEventListener("change", () => {
			upsertTrainingCompositeTaskInline((draft) => ({ ...draft, name: String(compositeInlineSchemeNameInput.value || "").trim() }));
			render();
		});
	}

	document.querySelectorAll("[data-action='add-composite-task-row']").forEach((el) => {
		el.addEventListener("click", () => {
			const currentTask = getSelectedTrainingCompositeTask();
			if (!currentTask) {
				showToast("请先选择复合任务");
				return;
			}
			const basicTaskId = String((state.tasks.basicTasks || [])[0]?.id || "").trim();
			if (!basicTaskId) {
				showToast("请先维护基本任务");
				return;
			}
			const selectedTask = (state.tasks.basicTasks || []).find((task) => String(task?.id || "").trim() === basicTaskId) || null;
			const firstWaveTime = "08:00";
			const preparationMinutes = resolveBasicTaskPreparationMinutes({ ...(selectedTask || {}), ...createBasicTaskDraft(selectedTask || {}) }, 0);
			const taskDispatchTime = minutesToCompositeTime(compositeTimeToMinutes(firstWaveTime, 8 * 60) - preparationMinutes - 1);
			upsertTrainingCompositeTaskInline((draft) => ({
				...draft,
				taskItems: [
					...getCompositeTaskModelRows(draft, state.tasks.basicTasks || []),
					{ id: uid("ctrow"), basicTaskId, groupName: "", taskDispatchTime, firstWaveTime, dailyRepeatCount: 1, intervalHours: 4 }
				]
			}));
			render();
		});
	});

	document.querySelectorAll("[data-action='delete-composite-task-row']").forEach((el) => {
		el.addEventListener("click", () => {
			const rowId = String(el.dataset.rowId || "").trim();
			if (!rowId) return;
			const currentTask = getSelectedTrainingCompositeTask();
			if (!currentTask) return;
			const currentRows = getCompositeTaskModelRows(currentTask, state.tasks.basicTasks || []);
			if (currentRows.length <= 1) {
				showToast("复合任务至少保留一个基本任务");
				return;
			}
			upsertTrainingCompositeTaskInline((draft) => ({
				...draft,
				taskItems: currentRows.filter((row) => String(row?.id || "").trim() !== rowId),
				timelineEdits: normalizeCompositeTaskTimelineEdits((draft.timelineEdits || []).filter((edit) => !String(edit?.eventId || "").includes(`__${rowId}__`)))
			}));
			render();
		});
	});

	document.querySelectorAll("[data-action='composite-inline-row-change']").forEach((el) => {
		const handler = () => {
			const rowId = String(el.dataset.rowId || "").trim();
			const field = String(el.dataset.field || "").trim();
			if (!rowId || !field) return;
			const rawValue = el.value;
			upsertTrainingCompositeTaskInline((draft) => ({
				...draft,
				taskItems: getCompositeTaskModelRows(draft, state.tasks.basicTasks || []).map((row) => {
					if (String(row?.id || "").trim() !== rowId) return row;
					if (field === "basicTaskId") {
						const selectedTask = (state.tasks.basicTasks || []).find((task) => String(task?.id || "").trim() === String(rawValue || "").trim()) || null;
						const selectedTaskDraft = createBasicTaskDraft(selectedTask || {});
						const firstWaveTime = normalizeCompositeTimeHHmm(row.firstWaveTime, "08:00");
						const preparationMinutes = resolveBasicTaskPreparationMinutes({ ...(selectedTask || {}), ...selectedTaskDraft }, 0);
						return {
							...row,
							basicTaskId: String(rawValue || "").trim(),
							basicTaskName: String(selectedTask?.name || row.basicTaskName || "未命名基本任务").trim() || "未命名基本任务",
							equipmentType: String(selectedTaskDraft.equipmentType || selectedTask?.equipmentType || "").trim(),
							equipmentQuantity: Number(selectedTaskDraft.equipmentQuantity ?? selectedTask?.equipmentQuantity),
							taskDispatchTime: minutesToCompositeTime(compositeTimeToMinutes(firstWaveTime, 8 * 60) - preparationMinutes - 1),
							preparationMinutes,
							relaunchPreparationMinutes: resolveBasicTaskPreparationMinutes({ ...(selectedTask || {}), ...selectedTaskDraft }, 1)
						};
					}
					if (field === "dailyRepeatCount" || field === "intervalHours") {
						return { ...row, [field]: normalizeCompositePositiveInt(rawValue, row[field]) };
					}
					if (field === "firstWaveTime" || field === "taskDispatchTime") {
						return { ...row, [field]: normalizeCompositeTimeHHmm(rawValue, row[field]) };
					}
					return { ...row, [field]: String(rawValue || "").trim() };
				})
			}));
			render();
		};
		el.addEventListener("change", handler);
	});

	document.querySelectorAll("[data-action='set-composite-timeline-view']").forEach((el) => {
		el.addEventListener("click", () => {
			state.ui.compositeTimelineView = String(el.dataset.view || "table").trim() === "chart" ? "chart" : "table";
			render();
		});
	});

	document.querySelectorAll("[data-action='composite-timeline-edit']").forEach((el) => {
		el.addEventListener("change", () => {
			const eventId = String(el.dataset.eventId || "").trim();
			const field = String(el.dataset.field || "").trim();
			if (!eventId || !field) return;
			upsertTrainingCompositeTaskInline((draft) => {
				const editMap = new Map(normalizeCompositeTaskTimelineEdits(draft.timelineEdits).map((edit) => [edit.eventId, edit]));
				const currentEdit = editMap.get(eventId) || { eventId, departureTime: "08:00", recoveryTime: "10:00" };
				currentEdit[field] = normalizeCompositeTimeHHmm(el.value, currentEdit[field]);
				editMap.set(eventId, currentEdit);
				return {
					...draft,
					timelineEdits: Array.from(editMap.values())
				};
			});
			render();
		});
	});

	const generateCompositeTimelineBtn = document.querySelector("[data-action='generate-composite-timeline']");
	if (generateCompositeTimelineBtn) {
		generateCompositeTimelineBtn.addEventListener("click", () => {
			const chartData = buildCompositeTimelineChartData();
			state.ui.compositeTimelineData = chartData;
			state.ui.compositeTimelineGenerated = true;
			render();
		});
	}

	document.querySelectorAll("[data-action='toggle-composite-basic-task']").forEach((el) => {
		el.addEventListener("change", () => {
			if (state.ui.modal?.type !== "composite") return;
			const taskId = String(el.dataset.id || "").trim();
			if (!taskId) return;
			const draft = createCompositeTaskDraft(state.ui.modal?.payload || null);
			const selectedSet = new Set(getCompositeTaskLinkedBasicTaskIds(draft, state.tasks.basicTasks || []));
			if (el.checked) {
				selectedSet.add(taskId);
			} else {
				selectedSet.delete(taskId);
			}
			openModal("composite", {
				...draft,
				basicTaskIds: Array.from(selectedSet)
			});
		});
	});

	document.querySelectorAll("[data-action='toggle-periodic-composite-task']").forEach((el) => {
		el.addEventListener("change", () => {
			if (state.ui.modal?.type !== "periodic-task") return;
			const taskId = String(el.dataset.id || "").trim();
			if (!taskId) return;
			const draft = createPeriodicTaskDraft(state.ui.modal?.payload || null);
			const selectedSet = new Set(normalizeCompositeTaskIds(draft.compositeTaskIds, getTrainingCompositeTaskList(), draft?.id));
			if (el.checked) {
				selectedSet.add(taskId);
			} else {
				selectedSet.delete(taskId);
			}
			openModal("periodic-task", {
				...draft,
				compositeTaskIds: Array.from(selectedSet)
			});
		});
	});

	document.querySelectorAll("[data-action='change-composite-calendar-month']").forEach((el) => {
		el.addEventListener("click", () => {
			const step = Number(el.dataset.step || 0);
			if (!Number.isFinite(step) || step === 0) return;
			const scope = String(el.dataset.scope || "").trim();
			if (scope === "modal") {
				if (state.ui.modal?.type !== "composite") return;
				const draft = createCompositeTaskDraft(state.ui.modal?.payload || null);
				const nextMonthKey = shiftCompositeCalendarMonth(draft.scheduleCalendarMonth, step);
				openModal("composite", { ...draft, scheduleCalendarMonth: nextMonthKey });
				return;
			}
			if (scope === "popover") {
				const taskId = String(el.dataset.id || "").trim();
				if (!taskId) return;
				const currentPopover = state.ui.compositeSchedulePopover || { taskId: "", monthKey: "" };
				const nextMonthKey = shiftCompositeCalendarMonth(currentPopover.monthKey, step);
				state.ui.compositeSchedulePopover = { taskId, monthKey: nextMonthKey };
				render();
			}
		});
	});

	document.querySelectorAll("[data-action='toggle-composite-schedule-popover']").forEach((el) => {
		el.addEventListener("click", () => {
			const taskId = String(el.dataset.id || "").trim();
			if (!taskId) return;
			const monthKey = resolveCompositeCalendarMonthKey([], String(el.dataset.monthKey || "").trim());
			const currentTaskId = String(state.ui.compositeSchedulePopover?.taskId || "").trim();
			if (currentTaskId === taskId) {
				state.ui.compositeSchedulePopover = { taskId: "", monthKey: "" };
			} else {
				state.ui.compositeSchedulePopover = { taskId, monthKey };
			}
			render();
		});
	});

	document.querySelectorAll("[data-action='close-composite-schedule-popover-btn']").forEach((el) => {
		el.addEventListener("click", () => {
			state.ui.compositeSchedulePopover = { taskId: "", monthKey: "" };
			render();
		});
	});

	document.querySelectorAll("[data-action='close-composite-schedule-popover']").forEach((el) => {
		el.addEventListener("click", (event) => {
			if (event.target.closest("[data-role='composite-schedule-popover-content']")) return;
			state.ui.compositeSchedulePopover = { taskId: "", monthKey: "" };
			render();
		});
	});

	document.querySelectorAll("[data-action='delete-composite']").forEach((el) => {
		el.addEventListener("click", () => {
			const id = String(el.dataset.id || "").trim();
			if (!id) return;
			const targetTask = state.tasks.compositeTasks.find((item) => String(item?.id || "").trim() === id) || null;
			showConfirm(isPeriodicTask(targetTask) ? "确认删除该周期性任务？" : "确认删除该复合任务？", (ok) => {
				if (!ok) return;
				state.tasks.compositeTasks = state.tasks.compositeTasks.filter((item) => String(item.id || "").trim() !== id);
				state.ui.selectedTaskIds.composite = (state.ui.selectedTaskIds.composite || []).filter((selectedId) => String(selectedId || "").trim() !== id);
				if (String(state.ui.selectedCompositeSchemeId || "").trim() === id) {
					state.ui.selectedCompositeSchemeId = "";
					state.ui.selectedUnitBasicTaskId = "";
				}
				if (String(state.ui.compositeSchedulePopover?.taskId || "").trim() === id) {
					state.ui.compositeSchedulePopover = { taskId: "", monthKey: "" };
				}
				state.ui.periodicTaskInlineError = "";
				resetCompositeTimelineResult();
				state.ui.tasksDirty = false;
				render();
			});
		});
	});

	document.querySelectorAll("[data-action='delete-basic']").forEach((el) => {
		el.addEventListener("click", () => {
			showConfirm("确认删除该基本任务？", (ok) => {
				if (!ok) return;
				const deletingId = String(el.dataset.id || "").trim();
				const deletingTask = (state.tasks.basicTasks || []).find((item) => String(item?.id || "").trim() === deletingId) || null;
				if (state.ui.selectedBasicTaskId === el.dataset.id) {
					state.ui.selectedBasicTaskId = "";
				}
				if (deletingTask) {
					state.ui.selectedBasicTaskAircraftType = String(createBasicTaskDraft(deletingTask).equipmentType || state.ui.selectedBasicTaskAircraftType || "").trim();
				}
				state.tasks.basicTasks = state.tasks.basicTasks.filter((item) => item.id !== el.dataset.id);
				if (state.ui.selectedBasicRequiredEquipmentIndexes && typeof state.ui.selectedBasicRequiredEquipmentIndexes === "object") {
					delete state.ui.selectedBasicRequiredEquipmentIndexes[deletingId];
				}
				resetCompositeTimelineResult();
				state.ui.tasksDirty = false;
				render();
			});
		});
	});

	document.querySelectorAll("[data-action='close-modal']").forEach((el) => el.addEventListener("click", closeModal));

	const syncUnitModalDependentOptions = (source = "") => {
		const modelSelect = document.getElementById("unitModalModel");
		const aircraftNoSelect = document.getElementById("unitModalAircraftNo");
		if (!modelSelect || !aircraftNoSelect) return;

		const modelName = String(modelSelect.value || "").trim();

		const aircraftNoOptions = getEquipmentAircraftNosByModel(modelName);
		const currentAircraftNo = String(aircraftNoSelect.value || "").trim();
		const nextAircraftNo = aircraftNoOptions.includes(currentAircraftNo) ? currentAircraftNo : String(aircraftNoOptions[0] || "").trim();
		aircraftNoSelect.innerHTML = aircraftNoOptions.length > 0
			? aircraftNoOptions.map((value) => `<option value="${htmlEscape(value)}" ${nextAircraftNo === value ? "selected" : ""}>${htmlEscape(value)}</option>`).join("")
			: `<option value="" selected>暂无飞机编号</option>`;

	};

	const syncBasicRequiredEquipmentMissionOptions = () => {
		const aircraftTypeSelect = document.getElementById("basicRequiredEquipmentAircraftType");
		const missionTypeSelect = document.getElementById("basicRequiredEquipmentOpsActivityName");
		if (!aircraftTypeSelect || !missionTypeSelect) return;
		const aircraftType = String(aircraftTypeSelect.value || "").trim();
		const options = getSingleMissionNameOptionsByModel(aircraftType);
		const currentValue = String(missionTypeSelect.value || "").trim();
		const rows = [`<option value="">请选择使用保障活动名称</option>`];
		const normalizedOptions = [...options];
		if (currentValue && !normalizedOptions.includes(currentValue)) {
			normalizedOptions.push(currentValue);
		}
		normalizedOptions.forEach((option) => {
			rows.push(`<option value="${htmlEscape(option)}" ${currentValue === option ? "selected" : ""}>${htmlEscape(formatSingleMissionTypeLabel(option) || option)}</option>`);
		});
		missionTypeSelect.innerHTML = rows.join("");
	};

	const unitModalModelSelect = document.getElementById("unitModalModel");
	if (unitModalModelSelect) {
		unitModalModelSelect.addEventListener("change", () => {
			syncUnitModalDependentOptions("model");
		});
	}

	const basicRequiredEquipmentAircraftTypeSelect = document.getElementById("basicRequiredEquipmentAircraftType");
	if (basicRequiredEquipmentAircraftTypeSelect) {
		basicRequiredEquipmentAircraftTypeSelect.addEventListener("change", syncBasicRequiredEquipmentMissionOptions);
	}

	const saveUnitModalBtn = document.querySelector("[data-action='save-unit-modal']");
	if (saveUnitModalBtn) {
		saveUnitModalBtn.addEventListener("click", () => {
			const errEl = document.getElementById("unitModalErr");
			const selectedTask = getSelectedUnitBasicTask();
			const groupName = inferBasicTaskGroupName(selectedTask || {});
			if (!groupName) {
				if (errEl) {
					errEl.style.display = "block";
					errEl.textContent = "当前基本任务未关联有效编队，请先在基本任务中维护编队。";
				}
				return;
			}

			const mode = saveUnitModalBtn.dataset.mode === "edit" ? "edit" : "add";
			const editingId = String(saveUnitModalBtn.dataset.id || "").trim();
			const model = String(document.getElementById("unitModalModel")?.value || "").trim();
			const aircraftNo = String(document.getElementById("unitModalAircraftNo")?.value || "").trim();
			const aircraftInitialStationName = findAircraftInitialStationNameByModelAndNo(model, aircraftNo);
			const supportOrganizationName = normalizeAircraftSupportOrganizationName(
				findAircraftSupportOrganizationNameByModelAndNo(model, aircraftNo) || "",
				model
			);

			const existingUnit = state.tasks.units.find((item) => String(item?.id || "").trim() === editingId) || {};
			const missionOptions = getSingleMissionNameOptionsByModel(model);
			const existingMissionName = String(existingUnit.opsActivityName || existingUnit.singleMissionName || "").trim();
			const opsActivityName = missionOptions.includes(existingMissionName)
				? existingMissionName
				: String(missionOptions[0] || "").trim();
			const unit = {
				id: mode === "edit" && editingId ? editingId : uid("unit"),
				groupName,
				model,
				aircraftNo: aircraftNo,
				supportOrganizationName,
				initialPosition: aircraftInitialStationName || String(existingUnit.initialPosition || "").trim(),
				initialSupportStationNames: [],
				initialStationName: aircraftInitialStationName || String(existingUnit.initialStationName || "").trim(),
				opsActivityName,
				lifeLimit: Number(existingUnit.lifeLimit || 3600),
				flightHours: Number(existingUnit.flightHours || 0),
				takeoffLimit: Number(existingUnit.takeoffLimit || 4200),
				takeoffCount: Number(existingUnit.takeoffCount || 0)
			};

			const err = validateUnit(unit, mode === "edit" ? editingId : "");
			if (err) {
				if (errEl) {
					errEl.style.display = "block";
					errEl.textContent = err;
				}
				return;
			}

			if (mode === "edit" && editingId) {
				state.tasks.units = state.tasks.units.map((item) => (String(item?.id || "").trim() === editingId ? { ...item, ...unit } : item));
			} else {
				state.tasks.units.push(unit);
			}

			state.ui.selectedTaskIds.unit = [];
			state.ui.selectedUnitGroupName = groupName;
			state.ui.selectedUnitId = "";
			state.ui.unitEditorMode = "empty";
			closeModal();
		});
	}

	document.querySelectorAll("[data-action='save-equipment-aircraft-info']").forEach((el) => {
		el.addEventListener("click", () => {
			const nodeId = String(el.dataset.nodeId || "").trim();
			const mode = el.dataset.mode === "edit" ? "edit" : "add";
			const rowId = String(el.dataset.rowId || "").trim();
			const targetNode = findNodeById(state.equipmentTree, nodeId);
			const errEl = document.getElementById("equipmentAircraftInfoErr");
			if (!targetNode || targetNode.type !== "aircraft") {
				if (errEl) {
					errEl.style.display = "block";
					errEl.textContent = "未找到对应飞机节点，请关闭窗口后重试。";
				}
				return;
			}

			const aircraftNo = String(document.getElementById("equipmentAircraftInfoNo")?.value || "").trim();
			const model = String(document.getElementById("equipmentAircraftInfoModel")?.value || getEquipmentAircraftModelName(targetNode) || "").trim();
			const supportOrganizationName = normalizeAircraftSupportOrganizationName(document.getElementById("equipmentAircraftInfoSupportOrganization")?.value || "", model);
			const currentStatus = String(document.getElementById("equipmentAircraftInfoCurrentStatus")?.value || "").trim();
			const unitName = String(state.ui.modal?.payload?.unitName || "").trim();
			const factoryDate = String(document.getElementById("equipmentAircraftInfoFactoryDate")?.value || "").trim();
			const totalRequiredYearsDisplay = String(document.getElementById("equipmentAircraftInfoTotalRequiredYears")?.value || "").trim();
			const totalRequiredLife = String(document.getElementById("equipmentAircraftInfoTotalRequiredLife")?.value || "").trim();
			const totalRequiredTakeoff = Number(document.getElementById("equipmentAircraftInfoTotalRequiredTakeoff")?.value || "");
			const totalFlightTime = String(document.getElementById("equipmentAircraftInfoTotalFlightTime")?.value || "").trim();
			const totalTakeoffCount = Number(document.getElementById("equipmentAircraftInfoTotalTakeoffCount")?.value || "");
			const postOverhaulRequiredYears = String(document.getElementById("equipmentAircraftInfoPostOverhaulRequiredYears")?.value || "").trim();
			const postOverhaulRequiredLife = String(document.getElementById("equipmentAircraftInfoPostOverhaulRequiredLife")?.value || "").trim();
			const postOverhaulRequiredTakeoff = Number(document.getElementById("equipmentAircraftInfoPostOverhaulRequiredTakeoff")?.value || "");
			const flightTime = String(document.getElementById("equipmentAircraftInfoFlightTime")?.value || "").trim();
			const remainingLifeInput = String(document.getElementById("equipmentAircraftInfoRemainingLife")?.value || "").trim();
			const remainingLife = remainingLifeInput || computeAircraftRemainingLifeValue(postOverhaulRequiredLife, flightTime);
			const flightTakeoffCount = Number(document.getElementById("equipmentAircraftInfoFlightTakeoffCount")?.value || "");

			if (!aircraftNo) {
				if (errEl) {
					errEl.style.display = "block";
					errEl.textContent = "飞机编号不能为空。";
				}
				return;
			}
			if (!currentStatus) {
				if (errEl) {
					errEl.style.display = "block";
					errEl.textContent = "现处状态不能为空。";
				}
				return;
			}
			if (!supportOrganizationName) {
				if (errEl) {
					errEl.style.display = "block";
					errEl.textContent = "保障组织不能为空。";
				}
				return;
			}
			if (!totalRequiredYearsDisplay || !totalRequiredLife || !totalFlightTime || !postOverhaulRequiredYears || !postOverhaulRequiredLife || !flightTime || !remainingLife) {
				if (errEl) {
					errEl.style.display = "block";
					errEl.textContent = "请完整填写寿命与时间相关字段。";
				}
				return;
			}
			const numericValues = [
				totalRequiredTakeoff,
				totalTakeoffCount,
				postOverhaulRequiredTakeoff,
				flightTakeoffCount
			];
			if (numericValues.some((value) => !Number.isFinite(value) || value < 0)) {
				if (errEl) {
					errEl.style.display = "block";
					errEl.textContent = "所有数值字段必须为大于等于 0 的数字。";
				}
				return;
			}
			const rows = getEquipmentAircraftInfoRows(targetNode);
			if (mode === "edit") {
				const targetRow = rows.find((row) => String(row.id || "").trim() === rowId);
				if (!targetRow) {
					if (errEl) {
						errEl.style.display = "block";
						errEl.textContent = "未找到要编辑的飞机信息。";
					}
					return;
				}
				targetRow.aircraftNo = aircraftNo;
				targetRow.model = model;
				targetRow.supportOrganizationName = supportOrganizationName;
				targetRow.currentStatus = currentStatus;
				targetRow.unitName = unitName;
				targetRow.factoryDate = factoryDate;
				targetRow.totalRequiredYears = parseAircraftYearsValue(totalRequiredYearsDisplay, targetRow.totalRequiredYears);
				targetRow.totalRequiredYearsDisplay = totalRequiredYearsDisplay;
				targetRow.totalRequiredLife = totalRequiredLife;
				targetRow.totalRequiredTakeoff = Math.floor(totalRequiredTakeoff);
				targetRow.totalFlightTime = totalFlightTime;
				targetRow.totalTakeoffCount = Math.floor(totalTakeoffCount);
				targetRow.postOverhaulRequiredYears = postOverhaulRequiredYears;
				targetRow.postOverhaulRequiredLife = postOverhaulRequiredLife;
				targetRow.postOverhaulRequiredTakeoff = Math.floor(postOverhaulRequiredTakeoff);
				targetRow.flightTime = flightTime;
				targetRow.remainingLife = remainingLife;
				targetRow.flightTakeoffCount = Math.floor(flightTakeoffCount);
				targetRow.isOnboard = currentStatus !== "停用";
				targetRow.lifeLimit = Math.floor(parseAircraftDurationValue(postOverhaulRequiredLife) / 60);
				targetRow.flightHours = Math.floor(parseAircraftDurationValue(flightTime) / 60);
				targetRow.takeoffLimit = Math.floor(postOverhaulRequiredTakeoff);
				targetRow.takeoffCount = Math.floor(flightTakeoffCount);
				targetRow.totalServiceLifeYears = parseAircraftYearsValue(totalRequiredYearsDisplay, targetRow.totalServiceLifeYears);
				targetRow.totalWorkHours = Math.floor(parseAircraftDurationValue(totalFlightTime) / 60);
			} else {
				rows.push({
					id: uid("acf"),
					model,
					aircraftNo,
					supportOrganizationName,
					currentStatus,
					unitName,
					factoryDate,
					totalRequiredYears: parseAircraftYearsValue(totalRequiredYearsDisplay, 30),
					totalRequiredYearsDisplay,
					totalRequiredLife,
					totalRequiredTakeoff: Math.floor(totalRequiredTakeoff),
					totalFlightTime,
					totalTakeoffCount: Math.floor(totalTakeoffCount),
					postOverhaulRequiredYears,
					postOverhaulRequiredLife,
					postOverhaulRequiredTakeoff: Math.floor(postOverhaulRequiredTakeoff),
					flightTime,
					remainingLife,
					flightTakeoffCount: Math.floor(flightTakeoffCount),
					isOnboard: currentStatus !== "停用",
					lifeLimit: Math.floor(parseAircraftDurationValue(postOverhaulRequiredLife) / 60),
					flightHours: Math.floor(parseAircraftDurationValue(flightTime) / 60),
					takeoffLimit: Math.floor(postOverhaulRequiredTakeoff),
					takeoffCount: Math.floor(flightTakeoffCount),
					totalServiceLifeYears: parseAircraftYearsValue(totalRequiredYearsDisplay, 30),
					maintenanceCount: 0,
					totalWorkHours: Math.floor(parseAircraftDurationValue(totalFlightTime) / 60),
					initialStationName: ""
				});
			}

			const aircraftModelName = getEquipmentAircraftModelName(targetNode);
			if (aircraftModelName) {
				state.tasks.units = (state.tasks.units || []).map((unit) => {
					if (inferEquipmentAircraftModelName(unit?.model || "") !== aircraftModelName) return unit;
					if (String(unit?.aircraftNo || "").trim() !== aircraftNo) return unit;
					return {
						...unit,
						currentStatus,
						unitName,
						supportOrganizationName,
						factoryDate,
						totalRequiredYears: parseAircraftYearsValue(totalRequiredYearsDisplay, 30),
						totalRequiredYearsDisplay,
						totalRequiredLife,
						totalRequiredTakeoff: Math.floor(totalRequiredTakeoff),
						totalFlightTime,
						totalTakeoffCount: Math.floor(totalTakeoffCount),
						postOverhaulRequiredYears,
						postOverhaulRequiredLife,
						postOverhaulRequiredTakeoff: Math.floor(postOverhaulRequiredTakeoff),
						flightTime,
						remainingLife,
						flightTakeoffCount: Math.floor(flightTakeoffCount),
						aircraftInfoCustomized: true,
						lifeLimit: Math.floor(parseAircraftDurationValue(postOverhaulRequiredLife) / 60),
						flightHours: Math.floor(parseAircraftDurationValue(flightTime) / 60),
						takeoffLimit: Math.floor(postOverhaulRequiredTakeoff),
						takeoffCount: Math.floor(flightTakeoffCount),
						totalServiceLifeYears: parseAircraftYearsValue(totalRequiredYearsDisplay, 30),
						totalWorkHours: Math.floor(parseAircraftDurationValue(totalFlightTime) / 60),
						isOnboard: currentStatus !== "停用"
					};
				});
			}

			targetNode.quantity = rows.length;
			ensureEquipmentAircraftInfoSelectionState();
			if (!Array.isArray(state.ui.selectedEquipmentAircraftInfoIds[targetNode.id])) {
				state.ui.selectedEquipmentAircraftInfoIds[targetNode.id] = [];
			}
			closeModal();
		});
	});

	const importProjectSubmitBtn = document.querySelector("[data-action='import-project-submit']");
